const ICON_ALIASES={
  '⌂':'house','◫':'chart-no-axes-combined','✦':'sparkles','▧':'file-chart-column','✚':'clipboard-list','◷':'notebook-tabs','◴':'calendar-days','✓':'list-todo','☰':'activity','◈':'megaphone','◇':'bell','R$':'wallet-cards','◎':'scan-heart','◉':'user-round','▤':'school','♛':'graduation-cap','◬':'notebook-tabs','↻':'refresh-cw','▣':'boxes','♟':'users','⚙':'settings','!':'triangle-alert','○':'circle','◌':'circle','↙':'trending-down','↗':'trending-up','↘':'trending-down','⌁':'activity','⇄':'arrow-right-left','≡':'menu','☎':'phone','☏':'messages-square','▦':'file-chart-column','◨':'notebook-tabs','♢':'bell','◆':'megaphone','♜':'graduation-cap','⌕':'search','✎':'pencil','🗑':'trash-2','⭐':'star','👥':'users-round','⚠':'triangle-alert'
};
function appIcon(name,label=''){
  const resolved=ICON_ALIASES[name]||name;
  const paths=LUCIDE_ICONS[resolved]||LUCIDE_ICONS.circle;
  return '<svg class="pg-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+paths+'</svg>'+(label?'<span class="sr-only">'+escapeHTML(label)+'</span>':'');
}
function renderShellIcons(){
  const icons={mobileMenuIcon:'menu',sidebarCloseIcon:'x',sidebarLogoutIcon:'log-out',notificationIcon:'bell'};
  Object.entries(icons).forEach(([id,icon])=>{const node=document.getElementById(id);if(node)node.innerHTML=appIcon(icon)});
}

function safeCatalogList(...keys){for(const key of keys){const list=State?.db?.[key];if(Array.isArray(list))return list}return []}
function catalogLabelById(id,keys=['classes'],labelFields=['name','title','label','courseName']){if(!id)return '—';const list=safeCatalogList(...keys);const found=list.find(item=>String(item?.id||item?.key||item?.code||'')===String(id));if(!found)return '—';for(const field of labelFields){const value=found?.[field];if(value)return String(value)}return String(found?.name||found?.title||found?.label||found?.code||'—')}
function classLabelById(id){return catalogLabelById(id,['classes','turmas'],['name','title','label'])}
function teacherLabelById(id){return catalogLabelById(id,['teachers','professors','users'],['name','fullName','displayName','title'])}
function bookLabelById(id){return catalogLabelById(id,['books','library','inventory'],['name','title','bookName','label'])}

