function intelligenceSnapshots(){return State.db?.intelligenceSnapshots||[]}
const INTELLIGENCE_FREQUENCY_PRIORITY=['diario','semanal','quinzenal','mensal'];
function orderedIntelligenceSnapshots(sector,sourceKind=null){return intelligenceSnapshots().filter(snapshot=>snapshot.sector===sector&&(!sourceKind||snapshot.sourceKind===sourceKind)).sort((a,b)=>`${a.periodEnd||''}${a.sourceUpdatedAt||''}`.localeCompare(`${b.periodEnd||''}${b.sourceUpdatedAt||''}`))}
function resolveIntelligenceFrequency(sector,preferred='semanal'){
  const available=[...new Set(orderedIntelligenceSnapshots(sector,'report').map(snapshot=>snapshot.frequency).filter(Boolean))];
  if(!available.length)return null;
  const order=[preferred,...INTELLIGENCE_FREQUENCY_PRIORITY.filter(f=>f!==preferred),...available.filter(f=>!INTELLIGENCE_FREQUENCY_PRIORITY.includes(f))];
  return order.find(f=>available.includes(f))||available[0];
}
function intelligenceSnapshotsFor(sector,frequency='semanal'){
  const snapshots=orderedIntelligenceSnapshots(sector,'report');
  if(!frequency)return snapshots;
  const exact=snapshots.filter(snapshot=>snapshot.frequency===frequency);
  if(exact.length)return exact;
  const resolved=resolveIntelligenceFrequency(sector,frequency);
  return resolved?snapshots.filter(snapshot=>snapshot.frequency===resolved):[];
}
function latestIntelligenceSnapshot(sector,frequency='semanal'){return intelligenceSnapshotsFor(sector,frequency).at(-1)||null}
function intelligenceFrequencyLabel(sector,preferred='semanal'){const resolved=resolveIntelligenceFrequency(sector,preferred);return FREQUENCY_LABELS[resolved]||resolved||'—'}
function mergeReportSnapshotFallback(db,remoteSnapshots=[]){
  const remote=Array.isArray(remoteSnapshots)?remoteSnapshots:[];
  const local=buildLocalIntelligenceSnapshots(db).filter(snapshot=>snapshot.sourceKind==='report');
  if(!local.length)return remote;
  const remoteKeys=new Set(remote.filter(snapshot=>snapshot.sourceKind==='report').map(snapshot=>`${snapshot.sector}:${snapshot.frequency}`));
  const missingLocal=local.filter(snapshot=>!remoteKeys.has(`${snapshot.sector}:${snapshot.frequency}`));
  if(missingLocal.length)console.warn('Purple Intelligence report snapshots unavailable — using reports already loaded as indicator fallback');
  return [...remote,...missingLocal];
}
function operationalDiarySnapshotsFor(sector){return orderedIntelligenceSnapshots(sector,'operational_diary').filter(snapshot=>snapshot.frequency==='diario')}
function latestOperationalDiarySnapshot(sector){return operationalDiarySnapshotsFor(sector).at(-1)||null}
function todayOperationalDiarySnapshot(sector){return operationalDiarySnapshotsFor(sector).filter(snapshot=>snapshot.periodEnd===todayISO()||snapshot.periodStart===todayISO()).at(-1)||null}
function intelligenceMetric(snapshot,key,bucket='metrics'){return intelligenceNumber(snapshot?.[bucket]?.[key])}
function intelligenceMetricChange(rows,key,bucket='metrics'){if(rows.length<2)return 0;const prev=intelligenceMetric(rows.at(-2),key,bucket),cur=intelligenceMetric(rows.at(-1),key,bucket);return prev===0?0:(cur-prev)/Math.abs(prev)*100}
