async function refreshIntelligenceSnapshots(){
  const {data,error}=await Supabase.from('intelligence_snapshots').select('*').order('period_end',{ascending:false}).order('source_updated_at',{ascending:false}).limit(400);
  if(error){
    const missing=error.code==='42P01'||error.code==='PGRST205'||String(error.message||'').includes('intelligence_snapshots');
    if(missing){
      console.warn('Purple Intelligence migration pending — using temporary report fallback');
      State.db.intelligenceSnapshots=buildLocalIntelligenceSnapshots(State.db);
      State.db.intelligenceMode='fallback';
      return;
    }
    throw error;
  }
  const remoteSnapshots=(data||[]).map(normalizeIntelligenceSnapshot);
  State.db.intelligenceSnapshots=mergeReportSnapshotFallback(State.db,remoteSnapshots);
  State.db.intelligenceMode=remoteSnapshots.some(snapshot=>snapshot.sourceKind==='report')?'database':'fallback';
}

