async function cleanupClassesExceptDiscover3({silent=true}={}){
  if(State.user&&State.user.role==='teacher')return false;
  if(State.user&&State.user.accessScope!=='all_sectors'&&State.user.role!=='direction')return false;
  State.db.classes=Array.isArray(State.db.classes)?State.db.classes:[];
  const settings=State.db.settings=State.db.settings||{};
  if(settings.classesCleanupDiscover3Only==='v1')return false;
  const keep=State.db.classes.find(classIsDiscover3)||seedClasses()[0];
  const removed=State.db.classes.filter(item=>item.id!==keep.id);
  State.db.classes=[{...keep,name:'DISCOVER 3',course:keep.course||'DISCOVER',level:keep.level||'3',status:keep.status||'Ativa'}];
  settings.classesCleanupDiscover3Only='v1';
  try{
    if(hasSupabaseClient()){
      for(const item of removed)await deleteClassRecord(item).catch(error=>console.warn('Purple Gestão — limpeza de turma antiga:',item?.name,error));
      await saveClassRecord(State.db.classes[0]).catch(error=>console.warn('Purple Gestão — preservação da Discover 3:',error));
      await saveSettingsRecord().catch(error=>console.warn('Purple Gestão — marcador de limpeza de turmas:',error));
    }else await Storage.save(State.db);
    if(!silent)toast('Turmas antigas removidas. Discover 3 mantida.');
  }catch(error){
    console.warn('Purple Gestão — limpeza de turmas mantida localmente:',error);
    await Storage.save(State.db).catch(saveError=>console.warn('Purple Gestão — cache local de limpeza de turmas:',saveError));
  }
  return true;
}
