function fmtMoney(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function fmtMetric(v,type){if(type==='money')return fmtMoney(v);if(type==='percent')return `${fmtNumber(v,1)}%`;if(type==='decimal')return fmtNumber(v,1);return fmtNumber(v)}
