function studentTabLabel(tab){return ({search:'Procura',profile:'Cadastro',courses:'Cursos',payments:'Financeiro',schedule:'Horários',frequency:'Frequência',grades:'Notas',contacts:'Contatos',followup:'Follow-up',documents:'Documentos',history:'Histórico',whatsapp:'WhatsApp',more:'Mais Ações',enrollment:'Dados da Matrícula'}[tab]||'Procura')}
