function studentMoneyRowsLegacy1(s){const name=String(s?.name||'').toLowerCase(),doc=studentIdentity(s?.document||''),contract=String(s?.contract||'').toLowerCase();return (State.db.financialEntries||[]).filter(x=>{const hay=String(`${x.student||''} ${x.person||''} ${x.description||''} ${x.notes||''} ${x.contract||''}`).toLowerCase();return hay.includes(name)||(contract&&hay.includes(contract))||(doc&&studentIdentity(hay).includes(doc))}).sort((a,b)=>String(a.dueDate||'').localeCompare(String(b.dueDate||'')))}
function studentFinancialTotalsLegacy1(s){const rows=studentMoneyRows(s),paid=rows.reduce((sum,x)=>sum+Number(x.paidAmount||0),0),total=rows.reduce((sum,x)=>sum+Number(x.amount||x.value||0),0),open=rows.reduce((sum,x)=>sum+Math.max(0,Number(x.amount||x.value||0)-Number(x.paidAmount||0)),0);return {rows,paid,total,open,paidRows:rows.filter(x=>financialStatusFor(x)==='paid'),openRows:rows.filter(x=>!['paid','cancelled'].includes(financialStatusFor(x)))}}
const STUDENT_SUBACCOUNTS=['Mensalidade','Material didático','Matrícula','Reposição','Evento','Acordo','Taxa administrativa','Outro'];
