function studentFinancialContent(s,financial=studentFinancialTotals(s)){const rows=financial.rows,openRows=financial.openRows,overdue=rows.filter(x=>financialStatusFor(x)==='overdue'),overdueTotal=overdue.reduce((sum,x)=>sum+Math.max(0,Number(x.amount||0)-Number(x.paidAmount||0)),0),interest=rows.reduce((sum,x)=>sum+Number(x.interest||0)+Number(x.fine||0),0),bonus=rows.reduce((sum,x)=>sum+Number(x.bonusAmount||0),0),received=financial.paid,open=financial.open,total=financial.total,first=studentFirstOpenFinancialEntry(s);return `<div class="student-financial-panel"><section class="student-financial-actions"><button class="btn primary small" onclick="App.openStudentInstallments('${s.id}')">Inserir parcelas</button><button class="btn ghost small" onclick="${first?`App.editFinancialEntry('receivable','${first.id}')`:`App.openStudentInstallments('${s.id}')`}">Alterar parcela</button><button class="btn danger small" onclick="${first?`App.deleteFinancialEntry('${first.id}')`:`App.toast('Nenhuma parcela selecionada.')`}">Excluir parcela</button><button class="btn success small" onclick="${first?`App.openStudentReceivePayment('${s.id}','${first.id}')`:`App.toast('Nenhuma parcela em aberto para receber.')`}">Receber</button><button class="btn ghost small" onclick="${first?`App.openStudentCardInstallment('${s.id}','${first.id}')`:`App.toast('Nenhuma parcela selecionada.')`}">Parcelar no cartão</button><button class="btn ghost small" onclick="${first?`App.printStudentReceipt('${s.id}','${first.id}')`:`App.toast('Nenhuma parcela selecionada.')`}">Imprimir recibo</button><button class="btn ghost small" onclick="App.printStudentCarnet('${s.id}')">Imprimir carnê</button><button class="btn soft small" onclick="App.openStudentInstallments('${s.id}')">Reparcelamento</button></section><section class="student-financial-summary"><span><b>Parcelas recebidas</b>${fmtMoney(received)}</span><span><b>Parcelas a receber</b>${fmtMoney(open)}</span><span><b>Bônus pontualidade</b>${fmtMoney(bonus)}</span><span><b>Valor total em atraso</b>${fmtMoney(overdueTotal)}</span><span><b>Juros / multa</b>${fmtMoney(interest)}</span><span><b>Total em atraso + juros/multa</b>${fmtMoney(overdueTotal+interest)}</span><span><b>Valor total</b>${fmtMoney(total)}</span></section><section class="form-card"><h3>Contas do aluno</h3><div class="table-wrap student-financial-table"><table><thead><tr><th>Nº lanç.</th><th>Documento</th><th>Histórico</th><th>Vencimento</th><th>Valor</th><th>Bônus pont.</th><th>Juros</th><th>Multa</th><th>Valor pago</th><th>Pagamento</th><th>Forma</th><th>Subconta</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(x=>{const status=financialStatusFor(x),amount=Number(x.amount||x.value||0),paid=Number(x.paidAmount||0);return `<tr><td>${escapeHTML(String(x.launchNumber||x.id||'').replace('fin-','').slice(0,8)||'—')}</td><td>${escapeHTML(x.contract||studentCourseContractNumber(s))}</td><td>${escapeHTML(x.description||'Parcela')}</td><td>${fmtDate(x.dueDate||x.date||x.createdAt)}</td><td>${fmtMoney(amount)}</td><td>${fmtMoney(x.bonusAmount||0)}</td><td>${fmtMoney(x.interest||0)}</td><td>${fmtMoney(x.fine||0)}</td><td>${fmtMoney(paid)}</td><td>${fmtDate(x.paidDate)}</td><td>${escapeHTML(x.paymentMethod||'—')}</td><td>${escapeHTML(x.subaccount||x.category||'—')}</td><td><span class="status ${status==='paid'?'approved':status==='overdue'?'adjust':status==='partial'?'review':status==='cancelled'?'archived':'draft'}">${FINANCIAL_STATUS[status]||status}</span></td><td><div class="table-actions"><button class="btn success small" onclick="App.openStudentReceivePayment('${s.id}','${x.id}')">Receber</button><button class="btn ghost small" onclick="App.editFinancialEntry('receivable','${x.id}')">Editar</button><button class="btn danger small" onclick="App.deleteFinancialEntry('${x.id}')">Excluir</button></div></td></tr>`}).join('')||'<tr><td colspan="14">Nenhuma parcela cadastrada. Use “Inserir parcelas”.</td></tr>'}</tbody></table></div></section></div>`}
