studentDetailContent=function(s){const tab=State.studentTab||'profile';if(s&&tab==='payments')return studentFinancialContent(s,studentFinancialTotals(s));return studentDetailContentLegacy(s)}
const STUDENT_SCHEDULE_MODES=[['normal','Normal'],['reposicao','Reposições'],['outros','Outros']];
function studentClassRecord(s){return (State.db.classes||[]).find(x=>x.id===s?.classId)||null}
function studentScheduleRows(s){const saved=Array.isArray(s.scheduleEntries)?s.scheduleEntries:[],klass=studentClassRecord(s),fallbackTime=studentNextClass(s);const rows=saved.map(row=>({...row,_source:'student'}));if(!rows.length&&(klass||fallbackTime!=='—'))rows.push({id:'class-default',kind:'normal',day:klass?.day||'Conforme turma',startDate:s.courseStartDate||s.enrollmentDate||todayISO(),time:fallbackTime,endTime:'',room:klass?.room||klass?.classroom||'—',teacherId:s.teacherId||klass?.teacherId||'',teacher:teacherLabelById(s.teacherId||klass?.teacherId),type:s.courseType||'Turma',notes:'Horário vindo do vínculo de turma.',locked:true,_source:'class'});return rows}
function studentScheduleKindLabel(kind='normal'){return ({normal:'Normal',reposicao:'Reposição',outros:'Outro'}[kind]||'Normal')}
function studentScheduleContent(s){const mode=State.studentScheduleMode||'normal',all=studentScheduleRows(s),rows=all.filter(row=>(row.kind||'normal')===mode),first=rows[0]||all[0]||null;return `<div class="student-schedule-panel"><section class="student-schedule-actions"><button class="btn primary small" onclick="App.openStudentScheduleModal('${s.id}','','normal')">Trocar horário</button><button class="btn ghost small" onclick="App.openStudentScheduleModal('${s.id}','','reposicao')">Marcar reposição</button><button class="btn ghost small" onclick="App.openStudentScheduleModal('${s.id}','','outros')">Horário extra</button><button class="btn danger small" onclick="${first&&!first.locked?`App.deleteStudentSchedule('${s.id}','${first.id}')`:`App.toast('Selecione um horário cadastrado para excluir.')`}">Excluir horário</button><button class="btn ghost small" onclick="App.printStudentSchedule('${s.id}')">Imprimir</button></section><section class="student-schedule-switch">${STUDENT_SCHEDULE_MODES.map(([key,label])=>`<button class="${mode===key?'active':''}" onclick="App.setStudentScheduleMode('${key}')">${escapeHTML(label)}</button>`).join('')}</section><section class="form-card student-schedule-card"><div class="panel-head"><div><h3>Horários do aluno</h3><small>${escapeHTML(s.name)} • ${escapeHTML(classLabelById(s.classId))}</small></div><span class="status ${mode==='reposicao'?'review':mode==='outros'?'draft':'approved'}">${escapeHTML(studentScheduleKindLabel(mode))}</span></div><div class="table-wrap student-schedule-table"><table><thead><tr><th>Dia</th><th>Agendado a partir de</th><th>Horário</th><th>Laboratório / Sala</th><th>Professor</th><th>Tipo de aula</th><th>Ações</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHTML(row.day||'—')}</td><td>${fmtDate(row.startDate||row.date||row.createdAt)}</td><td>${escapeHTML(row.time||'—')}${row.endTime?` às ${escapeHTML(row.endTime)}`:''}</td><td>${escapeHTML(row.room||'—')}</td><td>${escapeHTML(row.teacher||teacherLabelById(row.teacherId)||'—')}</td><td>${escapeHTML(row.type||studentScheduleKindLabel(row.kind))}</td><td><div class="table-actions">${row.locked?`<button class="btn ghost small" onclick="App.openStudentScheduleModal('${s.id}','','normal')">Trocar</button>`:`<button class="btn ghost small" onclick="App.openStudentScheduleModal('${s.id}','${row.id}','${row.kind||'normal'}')">Editar</button><button class="btn danger small" onclick="App.deleteStudentSchedule('${s.id}','${row.id}')">Excluir</button>`}</div></td></tr>`).join('')||`<tr><td colspan="7"><div class="empty"><p>Nenhum horário em ${escapeHTML(studentScheduleKindLabel(mode).toLowerCase())}. Use os botões acima para cadastrar.</p></div></td></tr>`}</tbody></table></div></section></div>`}
function setStudentScheduleMode(mode='normal'){State.studentScheduleMode=STUDENT_SCHEDULE_MODES.some(([key])=>key===mode)?mode:'normal';renderPage()}
function openStudentScheduleModal(id,scheduleId='',kind='normal'){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const rows=studentScheduleRows(s),current=rows.find(row=>row.id===scheduleId)||{},klass=studentClassRecord(s),teacherOptions=(State.db.teachers||[]).map(t=>`<option value="${t.id}" ${(current.teacherId||s.teacherId)===t.id?'selected':''}>${escapeHTML(t.name)}</option>`).join(''),selectedKind=current.kind||kind||'normal';modal(`<div class="modal-head"><div><span class="eyebrow">Horários</span><h3>${scheduleId?'Editar horário':'Cadastrar horário'}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3"><div class="field"><label>Tipo de registro</label><select id="studentScheduleKind">${STUDENT_SCHEDULE_MODES.map(([key,label])=>`<option value="${key}" ${selectedKind===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Dia</label><select id="studentScheduleDay">${['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo','Conforme turma'].map(day=>`<option ${String(current.day||klass?.day||'Conforme turma')===day?'selected':''}>${day}</option>`).join('')}</select></div><div class="field"><label>Agendado a partir de</label><input id="studentScheduleStartDate" type="date" value="${current.startDate||current.date||todayISO()}"/></div><div class="field"><label>Horário inicial</label><input id="studentScheduleTime" type="time" value="${escapeHTML(current.time||'08:00')}"/></div><div class="field"><label>Horário final</label><input id="studentScheduleEndTime" type="time" value="${escapeHTML(current.endTime||'')}"/></div><div class="field"><label>Laboratório / sala</label><input id="studentScheduleRoom" value="${escapeHTML(current.room||klass?.room||klass?.classroom||'')}"/></div><div class="field"><label>Professor</label><select id="studentScheduleTeacher"><option value="">—</option>${teacherOptions}</select></div><div class="field"><label>Tipo de aula</label><select id="studentScheduleType">${['Turma','Individual','Reposição','Extra','Online','Outros'].map(type=>`<option ${String(current.type||s.courseType||'Turma')===type?'selected':''}>${type}</option>`).join('')}</select></div></div><div class="field"><label>Observações</label><textarea id="studentScheduleNotes" placeholder="Ex.: horário extra, sala alternativa, reposição de falta...">${escapeHTML(current.notes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveStudentSchedule('${s.id}','${scheduleId}')">Salvar horário</button></div>`,true)}
async function saveStudentSchedule(id,scheduleId=''){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const before=cloneValue(s),teacherId=$('#studentScheduleTeacher')?.value||'',teacher=teacherLabelById(teacherId),time=$('#studentScheduleTime')?.value||'',day=$('#studentScheduleDay')?.value||'';if(!day||!time)return toast('Informe o dia e o horário inicial.');const row={id:scheduleId||uid('sch'),kind:$('#studentScheduleKind')?.value||'normal',day,startDate:$('#studentScheduleStartDate')?.value||todayISO(),time,endTime:$('#studentScheduleEndTime')?.value||'',room:$('#studentScheduleRoom')?.value.trim()||'',teacherId,teacher:teacher==='—'?'':teacher,type:$('#studentScheduleType')?.value||'Turma',notes:$('#studentScheduleNotes')?.value.trim()||'',updatedAt:new Date().toISOString()};s.scheduleEntries=Array.isArray(s.scheduleEntries)?s.scheduleEntries:[];const idx=s.scheduleEntries.findIndex(x=>x.id===scheduleId);if(idx>=0)s.scheduleEntries[idx]=row;else s.scheduleEntries.unshift(row);s.updatedAt=new Date().toISOString();s.timeline=s.timeline||[];s.timeline.unshift({at:new Date().toISOString(),title:idx>=0?'Horário alterado':'Horário cadastrado',detail:`${studentScheduleKindLabel(row.kind)} • ${row.day} • ${row.time}${row.endTime?` às ${row.endTime}`:''} • ${row.room||'sem sala'}`});try{await Storage.save(State.db);await logAudit(idx>=0?'Alterou horário do aluno':'Cadastrou horário do aluno',`${s.name} • ${row.day} • ${row.time}`);closeModal();State.studentScheduleMode=row.kind;toast('Horário salvo.');renderPage()}catch(error){restoreRecord(s,before);toast(friendlyError(error,'horário do aluno'))}}
async function deleteStudentSchedule(id,scheduleId){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const row=(s.scheduleEntries||[]).find(x=>x.id===scheduleId);if(!row)return toast('Horário não encontrado.');if(!confirm(`Excluir o horário ${row.day} ${row.time}?`))return;const before=cloneValue(s);s.scheduleEntries=(s.scheduleEntries||[]).filter(x=>x.id!==scheduleId);s.updatedAt=new Date().toISOString();s.timeline=s.timeline||[];s.timeline.unshift({at:new Date().toISOString(),title:'Horário excluído',detail:`${studentScheduleKindLabel(row.kind)} • ${row.day} • ${row.time}`});try{await Storage.save(State.db);await logAudit('Excluiu horário do aluno',`${s.name} • ${row.day} • ${row.time}`);toast('Horário excluído.');renderPage()}catch(error){restoreRecord(s,before);toast(friendlyError(error,'exclusão do horário'))}}
function printStudentSchedule(id){const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const rows=studentScheduleRows(s);return printableStudentDocument(`Horários — ${s.name}`,`<div class="box"><b>Aluno:</b> ${escapeHTML(s.name)}<br/><b>Turma:</b> ${escapeHTML(classLabelById(s.classId))}<br/><b>Professor:</b> ${escapeHTML(teacherLabelById(s.teacherId))}</div><table><thead><tr><th>Tipo</th><th>Dia</th><th>A partir de</th><th>Horário</th><th>Sala</th><th>Professor</th><th>Tipo de aula</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHTML(studentScheduleKindLabel(row.kind))}</td><td>${escapeHTML(row.day||'—')}</td><td>${fmtDate(row.startDate||row.date)}</td><td>${escapeHTML(row.time||'—')}${row.endTime?` às ${escapeHTML(row.endTime)}`:''}</td><td>${escapeHTML(row.room||'—')}</td><td>${escapeHTML(row.teacher||teacherLabelById(row.teacherId)||'—')}</td><td>${escapeHTML(row.type||'—')}</td></tr>`).join('')}</tbody></table>`)}
const STUDENT_ATTENDANCE_FILTERS=[['all','Todos'],['present','Presenças'],['absent','Faltas']];
function studentAttendanceRows(s){return (Array.isArray(s.attendanceEntries)?s.attendanceEntries:[]).map(row=>({...row})).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.scheduledTime||'').localeCompare(String(a.scheduledTime||'')))}
function studentAttendanceStats(rows,s){const total=rows.length,present=rows.filter(x=>x.present!==false).length,absent=rows.filter(x=>x.present===false).length,replacements=rows.filter(x=>x.replacementScheduled).length,frequency=total?Math.round((present/total)*100):Number(s.frequency||0);return {total,present,absent,replacements,frequency}}
function studentAttendanceContent(s){const filter=State.studentAttendanceFilter||'all',all=studentAttendanceRows(s),rows=filter==='present'?all.filter(x=>x.present!==false):filter==='absent'?all.filter(x=>x.present===false):all,stats=studentAttendanceStats(all,s);return `<div class="student-attendance-panel"><section class="student-attendance-actions"><button class="btn primary small" onclick="App.openStudentAttendanceModal('${s.id}','','present')">Marcar presença</button><button class="btn ghost small" onclick="App.openStudentAttendanceModal('${s.id}','','absent')">Registrar falta</button><button class="btn ghost small" onclick="App.openStudentAttendanceModal('${s.id}','','replacement')">Agendar reposição</button><button class="btn ghost small" onclick="App.printStudentAttendance('${s.id}')">Imprimir</button></section><section class="student-attendance-filter">${STUDENT_ATTENDANCE_FILTERS.map(([key,label])=>`<button class="${filter===key?'active':''}" onclick="App.setStudentAttendanceFilter('${key}')">${escapeHTML(label)}</button>`).join('')}</section><section class="student-attendance-summary"><span><b>Nº de aulas</b>${fmtNumber(stats.total)}</span><span><b>Nº de presenças</b>${fmtNumber(stats.present)}</span><span><b>Nº de faltas</b>${fmtNumber(stats.absent)}</span><span><b>Nº de reposições</b>${fmtNumber(stats.replacements)}</span><span><b>Frequência (%)</b>${fmtNumber(stats.frequency)}</span></section><section class="form-card student-attendance-card"><div class="panel-head"><div><h3>Controle de frequência</h3><small>${escapeHTML(s.name)} • ${escapeHTML(classLabelById(s.classId))}</small></div><span class="status ${stats.frequency<85?'adjust':'approved'}">${fmtNumber(stats.frequency)}%</span></div><div class="table-wrap student-attendance-table"><table><thead><tr><th>Data</th><th>Horário</th><th>Horário entrada</th><th>Professor</th><th>Tipo de aula</th><th>Presença</th><th>Falta antecipada</th><th>Reposição agendada</th><th>Ações</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${fmtDate(row.date)}</td><td>${escapeHTML(row.scheduledTime||'—')}</td><td>${escapeHTML(row.entryTime||'—')}</td><td>${escapeHTML(row.teacher||teacherLabelById(row.teacherId)||'—')}</td><td>${escapeHTML(row.classType||'Normal')}</td><td><input type="checkbox" ${row.present!==false?'checked':''} disabled/></td><td>${row.anticipatedAbsence?'N':'—'}</td><td>${row.replacementScheduled?'Sim':'—'}</td><td><div class="table-actions"><button class="btn ghost small" onclick="App.openStudentAttendanceModal('${s.id}','${row.id}','${row.present===false?'absent':'present'}')">Editar</button><button class="btn danger small" onclick="App.deleteStudentAttendance('${s.id}','${row.id}')">Excluir</button></div></td></tr>`).join('')||'<tr><td colspan="9"><div class="empty"><p>Nenhuma frequência registrada. Use “Marcar presença” ou “Registrar falta”.</p></div></td></tr>'}</tbody></table></div></section></div>`}
function setStudentAttendanceFilter(filter='all'){State.studentAttendanceFilter=STUDENT_ATTENDANCE_FILTERS.some(([key])=>key===filter)?filter:'all';renderPage()}
function openStudentAttendanceModal(id,attendanceId='',mode='present'){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const row=studentAttendanceRows(s).find(x=>x.id===attendanceId)||{},teacherOptions=(State.db.teachers||[]).map(t=>`<option value="${t.id}" ${(row.teacherId||s.teacherId)===t.id?'selected':''}>${escapeHTML(t.name)}</option>`).join(''),isAbsent=mode==='absent'||row.present===false,isReplacement=mode==='replacement'||row.replacementScheduled;modal(`<div class="modal-head"><div><span class="eyebrow">Controle de frequência</span><h3>${attendanceId?'Editar registro':'Novo registro'}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3"><div class="field"><label>Data</label><input id="studentAttendanceDate" type="date" value="${row.date||todayISO()}"/></div><div class="field"><label>Horário da aula</label><input id="studentAttendanceScheduledTime" value="${escapeHTML(row.scheduledTime||studentNextClass(s)||'')}"/></div><div class="field"><label>Horário de entrada</label><input id="studentAttendanceEntryTime" type="time" value="${escapeHTML(row.entryTime||(!isAbsent?new Date().toTimeString().slice(0,5):''))}"/></div><div class="field"><label>Professor</label><select id="studentAttendanceTeacher"><option value="">—</option>${teacherOptions}</select></div><div class="field"><label>Tipo de aula</label><select id="studentAttendanceClassType">${['Normal','Reposição','Extra','Online','Individual'].map(type=>`<option ${String(row.classType||(isReplacement?'Reposição':'Normal'))===type?'selected':''}>${type}</option>`).join('')}</select></div><div class="field"><label>Situação</label><select id="studentAttendanceStatus"><option value="present" ${!isAbsent?'selected':''}>Presença</option><option value="absent" ${isAbsent?'selected':''}>Falta</option></select></div></div><label class="checkline"><input id="studentAttendanceAnticipated" type="checkbox" ${row.anticipatedAbsence?'checked':''}/> Falta antecipada</label><label class="checkline"><input id="studentAttendanceReplacement" type="checkbox" ${isReplacement?'checked':''}/> Reposição agendada</label><div class="field"><label>Observações</label><textarea id="studentAttendanceNotes" placeholder="Ex.: chegou atrasado, falta avisada, reposição combinada...">${escapeHTML(row.notes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveStudentAttendance('${s.id}','${attendanceId}')">Salvar frequência</button></div>`,true)}
async function saveStudentAttendance(id,attendanceId=''){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const before=cloneValue(s),teacherId=$('#studentAttendanceTeacher')?.value||'',teacher=teacherLabelById(teacherId),date=$('#studentAttendanceDate')?.value||todayISO(),status=$('#studentAttendanceStatus')?.value||'present';if(!date)return toast('Informe a data da aula.');const row={id:attendanceId||uid('att'),date,scheduledTime:$('#studentAttendanceScheduledTime')?.value.trim()||'',entryTime:$('#studentAttendanceEntryTime')?.value||'',teacherId,teacher:teacher==='—'?'':teacher,classType:$('#studentAttendanceClassType')?.value||'Normal',present:status!=='absent',anticipatedAbsence:$('#studentAttendanceAnticipated')?.checked||false,replacementScheduled:$('#studentAttendanceReplacement')?.checked||false,notes:$('#studentAttendanceNotes')?.value.trim()||'',updatedAt:new Date().toISOString()};s.attendanceEntries=Array.isArray(s.attendanceEntries)?s.attendanceEntries:[];const idx=s.attendanceEntries.findIndex(x=>x.id===attendanceId);if(idx>=0)s.attendanceEntries[idx]=row;else s.attendanceEntries.unshift(row);const stats=studentAttendanceStats(s.attendanceEntries,s);s.frequency=stats.frequency;s.updatedAt=new Date().toISOString();s.timeline=s.timeline||[];s.timeline.unshift({at:new Date().toISOString(),title:row.present?'Presença registrada':'Falta registrada',detail:`${fmtDate(row.date)} • ${row.scheduledTime||'sem horário'} • ${row.classType}${row.replacementScheduled?' • reposição agendada':''}`});try{await Storage.save(State.db);await logAudit(idx>=0?'Alterou frequência do aluno':'Registrou frequência do aluno',`${s.name} • ${fmtDate(row.date)} • ${row.present?'presença':'falta'}`);closeModal();State.studentAttendanceFilter=row.present?'present':'absent';toast('Frequência salva.');renderPage()}catch(error){restoreRecord(s,before);toast(friendlyError(error,'frequência do aluno'))}}
async function deleteStudentAttendance(id,attendanceId){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const row=(s.attendanceEntries||[]).find(x=>x.id===attendanceId);if(!row)return toast('Registro não encontrado.');if(!confirm(`Excluir frequência de ${fmtDate(row.date)}?`))return;const before=cloneValue(s);s.attendanceEntries=(s.attendanceEntries||[]).filter(x=>x.id!==attendanceId);s.frequency=studentAttendanceStats(s.attendanceEntries,s).frequency;s.updatedAt=new Date().toISOString();s.timeline=s.timeline||[];s.timeline.unshift({at:new Date().toISOString(),title:'Frequência excluída',detail:`${fmtDate(row.date)} • ${row.scheduledTime||'sem horário'}`});try{await Storage.save(State.db);await logAudit('Excluiu frequência do aluno',`${s.name} • ${fmtDate(row.date)}`);toast('Frequência excluída.');renderPage()}catch(error){restoreRecord(s,before);toast(friendlyError(error,'exclusão da frequência'))}}
function printStudentAttendance(id){const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const rows=studentAttendanceRows(s),stats=studentAttendanceStats(rows,s);return printableStudentDocument(`Frequência — ${s.name}`,`<div class="box"><b>Aluno:</b> ${escapeHTML(s.name)}<br/><b>Turma:</b> ${escapeHTML(classLabelById(s.classId))}<br/><b>Frequência:</b> ${fmtNumber(stats.frequency)}%<br/><b>Aulas:</b> ${fmtNumber(stats.total)} • <b>Presenças:</b> ${fmtNumber(stats.present)} • <b>Faltas:</b> ${fmtNumber(stats.absent)} • <b>Reposições:</b> ${fmtNumber(stats.replacements)}</div><table><thead><tr><th>Data</th><th>Horário</th><th>Entrada</th><th>Professor</th><th>Tipo</th><th>Presença</th><th>Reposição</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${fmtDate(row.date)}</td><td>${escapeHTML(row.scheduledTime||'—')}</td><td>${escapeHTML(row.entryTime||'—')}</td><td>${escapeHTML(row.teacher||teacherLabelById(row.teacherId)||'—')}</td><td>${escapeHTML(row.classType||'Normal')}</td><td>${row.present!==false?'Sim':'Não'}</td><td>${row.replacementScheduled?'Sim':'Não'}</td></tr>`).join('')}</tbody></table>`)}
const DEFAULT_STUDENT_GRADE_TYPES=['Participation','Speaking','Listening','Writing','Reading','Midterm Exam','Final Term','Homework Unit 01','Homework Unit 02','Homework Unit 03','Homework Unit 04','Homework Unit 05','Homework Unit 06','Homework Unit 07','Homework Unit 08','Homework Unit 09','Homework Unit 10','Homework Unit 11','Homework Unit 12','Homework Unit 13','Homework Unit 14'];
function canManageStudentGradeTypes(){return State.user?.role==='direction'||/admin|master/i.test(`${State.user?.role||''} ${State.user?.name||''}`)}
function studentGradeTypes(){return DEFAULT_STUDENT_GRADE_TYPES.slice()}
function studentGradeRows(s){return (Array.isArray(s.gradeEntries)?s.gradeEntries:[]).map(row=>({...row})).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(a.type||'').localeCompare(String(b.type||'')))}
function studentGradeStats(rows){const launched=rows.filter(x=>Number.isFinite(Number(x.score))),avg=launched.length?launched.reduce((sum,x)=>sum+Number(x.score||0),0)/launched.length:0,pending=rows.filter(x=>!Number.isFinite(Number(x.score))||String(x.status||'').toLowerCase().includes('aguard')).length;return {launched:launched.length,pending,avg}}
function studentModuleHistoryContent(s){const histories=Array.isArray(s.moduleHistories)?s.moduleHistories:[];return histories.length?`<section class="form-card student-grades-card"><div class="panel-head"><div><h3>Histórico de módulos concluídos</h3><small>Fechado automaticamente ao concluir a turma.</small></div></div><div class="table-wrap"><table><thead><tr><th>Módulo</th><th>Turma</th><th>Média</th><th>Homework</th><th>Frequência</th><th>Situação</th><th>Fechamento</th></tr></thead><tbody>${histories.map(item=>`<tr><td>${escapeHTML(item.module||'—')}</td><td>${escapeHTML(item.className||'—')}</td><td>${Number.isFinite(Number(item.average))?fmtNumber(item.average,1):'—'}%</td><td>${Number.isFinite(Number(item.homeworkAverage))?fmtNumber(item.homeworkAverage,1):'—'}%</td><td>${Number.isFinite(Number(item.frequency))?fmtNumber(item.frequency,1):'—'}%</td><td><span class="status ${item.status==='Aprovado'?'approved':'rejected'}">${escapeHTML(item.status||'—')}</span></td><td>${fmtDate(item.closedAt)}</td></tr>`).join('')}</tbody></table></div></section>`:''}
function studentGradesContent(s){const rows=studentGradeRows(s),stats=studentGradeStats(rows),moduleName=s.coursePackage||s.level||bookLabelById(s.bookId)||'Módulo não definido',situation=rows.some(x=>String(x.status||'').toLowerCase().includes('recuper'))?'Recuperação':rows.length?'Em andamento':'Aguardando notas';return `<div class="student-grades-panel"><section class="student-grades-actions"><button class="btn primary small" onclick="App.openStudentGradeModal('${s.id}')">Incluir nota</button>${canManageStudentGradeTypes()?`<button class="btn ghost small" onclick="App.openStudentGradeTypes()">Tipos e provas</button>`:''}<button class="btn ghost small" onclick="App.printStudentGrades('${s.id}')">Imprimir</button></section><section class="student-grades-summary"><span><b>Módulo</b>${escapeHTML(moduleName)}</span><span><b>Situação</b>${escapeHTML(situation)}</span><span><b>Média (%)</b>${rows.length?fmtNumber(stats.avg,1):'—'}</span><span><b>Provas lançadas</b>${fmtNumber(stats.launched)}</span><span><b>Pendentes</b>${fmtNumber(stats.pending)}</span></section>${studentModuleHistoryContent(s)}<div class="student-grades-grid"><section class="form-card student-grades-card"><div class="panel-head"><div><h3>Resumo do módulo</h3><small>${escapeHTML(s.name)} • ${escapeHTML(classLabelById(s.classId))}</small></div><span class="status ${stats.avg>=70?'approved':rows.length?'adjust':'draft'}">${rows.length?`${fmtNumber(stats.avg,1)}%`:'Aguardando'}</span></div><div class="table-wrap student-grades-module-table"><table><thead><tr><th>Módulo</th><th>Situação</th><th>Média (%)</th></tr></thead><tbody><tr><td>${escapeHTML(moduleName)}</td><td>${escapeHTML(situation)}</td><td>${rows.length?fmtNumber(stats.avg,1):'—'}</td></tr></tbody></table></div></section><section class="form-card student-grades-card"><div class="panel-head"><div><h3>Provas</h3><small>Tipos cadastrados pela Direção/Master</small></div></div><div class="table-wrap student-grades-tests-table"><table><thead><tr><th>Prova</th><th>Nota</th><th>Data</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHTML(row.type||'—')}</td><td>${Number.isFinite(Number(row.score))?fmtNumber(row.score,1):'—'}</td><td>${fmtDate(row.date)}</td><td>${escapeHTML(row.status||'Não aguardado')}</td><td><div class="table-actions"><button class="btn ghost small" onclick="App.openStudentGradeModal('${s.id}','${row.id}')">Editar</button><button class="btn danger small" onclick="App.deleteStudentGrade('${s.id}','${row.id}')">Excluir</button></div></td></tr>`).join('')||studentGradeTypes().map(type=>`<tr><td>${escapeHTML(type)}</td><td>—</td><td>—</td><td>Não lançado</td><td><button class="btn ghost small" onclick="App.openStudentGradeModal('${s.id}','','${escapeHTML(type)}')">Lançar</button></td></tr>`).join('')}</tbody></table></div></section></div></div>`}
function openStudentGradeModal(id,gradeId='',presetType=''){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const row=studentGradeRows(s).find(x=>x.id===gradeId)||{},types=studentGradeTypes();modal(`<div class="modal-head"><div><span class="eyebrow">Notas</span><h3>${gradeId?'Editar nota':'Incluir nota'}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3"><div class="field"><label>Módulo</label><input id="studentGradeModule" value="${escapeHTML(row.module||s.coursePackage||s.level||'')}"/></div><div class="field"><label>Prova / tipo</label><select id="studentGradeType">${types.map(type=>`<option ${String(row.type||presetType||types[0])===type?'selected':''}>${escapeHTML(type)}</option>`).join('')}</select></div><div class="field"><label>Nota (%)</label><input id="studentGradeScore" type="number" min="0" max="100" step="0.1" value="${row.score??''}"/></div><div class="field"><label>Data</label><input id="studentGradeDate" type="date" value="${row.date||todayISO()}"/></div><div class="field"><label>Situação</label><select id="studentGradeStatus">${['Lançado','Aguardando','Recuperação','Revisão','Não aguardado'].map(status=>`<option ${String(row.status||'Lançado')===status?'selected':''}>${status}</option>`).join('')}</select></div></div><div class="field"><label>Observações</label><textarea id="studentGradeNotes" placeholder="Observações pedagógicas sobre a prova ou habilidade avaliada.">${escapeHTML(row.notes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveStudentGrade('${s.id}','${gradeId}')">Salvar nota</button></div>`,true)}
async function saveStudentGrade(id,gradeId=''){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const before=cloneValue(s),scoreRaw=$('#studentGradeScore')?.value,score=scoreRaw===''?null:Number(scoreRaw);if(score!==null&&(score<0||score>100))return toast('A nota deve estar entre 0 e 100.');const row={id:gradeId||uid('grd'),module:$('#studentGradeModule')?.value.trim()||s.level||'',type:$('#studentGradeType')?.value||'Média',score,date:$('#studentGradeDate')?.value||todayISO(),status:$('#studentGradeStatus')?.value||'Lançado',notes:$('#studentGradeNotes')?.value.trim()||'',updatedAt:new Date().toISOString()};s.gradeEntries=Array.isArray(s.gradeEntries)?s.gradeEntries:[];const idx=s.gradeEntries.findIndex(x=>x.id===gradeId);if(idx>=0)s.gradeEntries[idx]=row;else s.gradeEntries.unshift(row);const stats=studentGradeStats(s.gradeEntries);s.evaluation=`Média atual: ${fmtNumber(stats.avg,1)}% • ${stats.launched} prova(s) lançada(s)`;s.updatedAt=new Date().toISOString();s.timeline=s.timeline||[];s.timeline.unshift({at:new Date().toISOString(),title:idx>=0?'Nota alterada':'Nota lançada',detail:`${row.type} • ${row.score===null?'sem nota':fmtNumber(row.score,1)}% • ${row.status}`});try{await Storage.save(State.db);await logAudit(idx>=0?'Alterou nota do aluno':'Lançou nota do aluno',`${s.name} • ${row.type} • ${row.score===null?'sem nota':fmtNumber(row.score,1)}`);closeModal();toast('Nota salva.');renderPage()}catch(error){restoreRecord(s,before);toast(friendlyError(error,'nota do aluno'))}}
async function deleteStudentGrade(id,gradeId){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const row=(s.gradeEntries||[]).find(x=>x.id===gradeId);if(!row)return toast('Nota não encontrada.');if(!confirm(`Excluir a nota de ${row.type}?`))return;const before=cloneValue(s);s.gradeEntries=(s.gradeEntries||[]).filter(x=>x.id!==gradeId);s.updatedAt=new Date().toISOString();s.timeline=s.timeline||[];s.timeline.unshift({at:new Date().toISOString(),title:'Nota excluída',detail:`${row.type} • ${row.score??'sem nota'}`});try{await Storage.save(State.db);await logAudit('Excluiu nota do aluno',`${s.name} • ${row.type}`);toast('Nota excluída.');renderPage()}catch(error){restoreRecord(s,before);toast(friendlyError(error,'exclusão da nota'))}}
function openStudentGradeTypes(){if(!canManageStudentGradeTypes())return toast('Somente Direção/Master pode gerenciar tipos de prova.');modal(`<div class="modal-head"><div><span class="eyebrow">Notas</span><h3>Tipos e provas</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="field"><label>Tipos disponíveis</label><textarea id="studentGradeTypesList" class="large">${escapeHTML(studentGradeTypes().join('\n'))}</textarea><small class="helper">Informe um tipo por linha. Ex.: Speaking, Reading, Writing, Listening, Média.</small></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveStudentGradeTypes()">Salvar tipos</button></div>`,true)}
async function saveStudentGradeTypes(){if(!canManageStudentGradeTypes())return toast('Somente Direção/Master pode gerenciar tipos de prova.');const before=cloneValue(State.db.settings||{}),values=[...new Set(($('#studentGradeTypesList')?.value||'').split(/\n|,|;/).map(x=>x.trim()).filter(Boolean))];if(!values.length)return toast('Informe pelo menos um tipo de prova.');State.db.settings=State.db.settings||{};State.db.settings.studentGradeTypes=values;State.db.settings.updatedAt=new Date().toISOString();try{await Storage.save(State.db);await logAudit('Atualizou tipos de prova',values.join(', '));closeModal();toast('Tipos de prova salvos.');renderPage()}catch(error){State.db.settings=before;toast(friendlyError(error,'tipos de prova'))}}
function printStudentGrades(id){const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const rows=studentGradeRows(s),stats=studentGradeStats(rows);return printableStudentDocument(`Notas — ${s.name}`,`<div class="box"><b>Aluno:</b> ${escapeHTML(s.name)}<br/><b>Módulo:</b> ${escapeHTML(s.coursePackage||s.level||'—')}<br/><b>Média:</b> ${rows.length?fmtNumber(stats.avg,1):'—'}%<br/><b>Provas lançadas:</b> ${fmtNumber(stats.launched)}</div><table><thead><tr><th>Módulo</th><th>Prova</th><th>Nota</th><th>Data</th><th>Situação</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHTML(row.module||'—')}</td><td>${escapeHTML(row.type||'—')}</td><td>${Number.isFinite(Number(row.score))?fmtNumber(row.score,1):'—'}</td><td>${fmtDate(row.date)}</td><td>${escapeHTML(row.status||'—')}</td></tr>`).join('')}</tbody></table>`)}
function addMonthsISO(dateISO,months=0){const base=dateISO?new Date(`${dateISO}T12:00:00`):new Date();base.setMonth(base.getMonth()+Number(months||0));return `${base.getFullYear()}-${String(base.getMonth()+1).padStart(2,'0')}-${String(base.getDate()).padStart(2,'0')}`}
function studentCourseContractNumber(s){return s.contract||s.courseContract||`${String(s.code||s.id||'ALUNO').replace(/[^A-Z0-9]/gi,'').slice(0,8).toUpperCase()}-${new Date().getFullYear()}`}
function studentCourseOpenInstallments(s){return studentMoneyRows(s).filter(x=>!['paid','cancelled'].includes(financialStatusFor(x))&&(!x.dueDate||x.dueDate>=todayISO()))}
function studentCourseCancellationFee(s){return studentCourseOpenInstallments(s).reduce((sum,x)=>sum+Math.max(0,Number(x.amount||x.value||0)-Number(x.paidAmount||0)),0)*.1}
function studentContractReady(s){const missing=[];if(!s.name)missing.push('nome');if(!s.document)missing.push('CPF/documento');if(!s.birthDate)missing.push('data de nascimento');if(!studentPhone(s)&&!studentWhatsApp(s))missing.push('telefone/WhatsApp');if(!s.address)missing.push('endereço');if(!s.financialResponsibleName&&!s.guardian)missing.push('responsável financeiro');if(!s.coursePackage&&!s.level)missing.push('pacote/curso');return missing}
function studentCourseRows(s){return [{contract:studentCourseContractNumber(s),package:s.coursePackage||bookLabelById(s.bookId)||'Pacote não definido',className:classLabelById(s.classId),start:s.courseStartDate||s.enrollmentDate,end:s.courseEndDate,status:normalizeStudentStatus(s.situation),type:s.courseType||'Turma'}]}
function studentCoursesContent(s,financial=studentFinancialTotals(s)){const contractReady=studentContractReady(s),cancelFee=studentCourseCancellationFee(s),rows=studentCourseRows(s);return `<div class="student-course-panel"><section class="student-course-actions"><button class="btn primary small" onclick="App.openStudentEnrollment('${s.id}')">Efetuar matrícula / pacote</button><button class="btn ghost small" onclick="App.openStudentClassLink('${s.id}')">Trocar ou vincular turma</button><button class="btn ghost small" onclick="App.generateStudentContract('${s.id}')">Contrato / Promissória PDF</button><button class="btn soft small" onclick="App.createStudentFutureInstallments('${s.id}')">Criar parcelas futuras teste</button><button class="btn ghost small" onclick="App.generateStudentDeclaration('${s.id}')">Declaração</button><button class="btn danger small" onclick="App.openStudentCancellation('${s.id}')">Cancelar curso</button></section><section class="grid cols-4">${metricCard('Plano / pacote',s.coursePackage||s.level||'Não definido','▤',0,`Contrato ${studentCourseContractNumber(s)}`)}${metricCard('Mensalidade',fmtMoney(s.courseMonthlyValue||0),'R$',0,`${fmtNumber(s.courseInstallments||0)} parcela(s)`)}${metricCard('A vencer',fmtMoney(financial.open),'R$',0,`${fmtNumber(financial.openRows.length)} parcela(s) abertas`,true)}${metricCard('Acordo cancelamento',fmtMoney(cancelFee),'%',0,'10% das mensalidades a vencer')}</section><div class="student-course-grid"><section class="form-card"><h3>Cursos / matrícula</h3><div class="table-wrap"><table><thead><tr><th>Nº Contrato</th><th>Pacote</th><th>Turma</th><th>Data inicial</th><th>Previsão término</th><th>Situação</th><th>Tipo de aula</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${escapeHTML(row.contract)}</td><td>${escapeHTML(row.package)}</td><td>${escapeHTML(row.className)}</td><td>${fmtDate(row.start)}</td><td>${fmtDate(row.end)}</td><td>${escapeHTML(row.status)}</td><td>${escapeHTML(row.type)}</td></tr>`).join('')}</tbody></table></div></section><section class="form-card"><h3>Contrato e documentos</h3>${contractReady.length?`<div class="alert yellow"><div class="alert-icon">!</div><div><b>Contrato ainda incompleto</b><span>Antes de gerar o PDF, complete: ${escapeHTML(contractReady.join(', '))}.</span></div></div>`:`<div class="alert green"><div class="alert-icon">✓</div><div><b>Pronto para contrato</b><span>As informações essenciais do cadastro e matrícula foram preenchidas.</span></div></div>`}<div class="kpi-strip" style="margin-top:10px"><span><b>Responsável financeiro:</b> ${escapeHTML(s.financialResponsibleName||s.guardian||'—')}</span><span><b>Material:</b> ${escapeHTML(bookLabelById(s.bookId))}</span><span><b>Plano:</b> ${escapeHTML(s.coursePlan||'—')}</span></div></section></div><section class="form-card"><h3>Parcelas do pacote</h3><div class="table-wrap"><table><thead><tr><th>Parcela / descrição</th><th>Vencimento</th><th>Valor</th><th>Pago</th><th>A vencer</th><th>Status</th></tr></thead><tbody>${financial.rows.map(x=>{const amount=Number(x.amount||x.value||0),paid=Number(x.paidAmount||0),open=Math.max(0,amount-paid);return `<tr><td>${escapeHTML(x.description||'Mensalidade')}</td><td>${fmtDate(x.dueDate||x.date||x.createdAt)}</td><td>${fmtMoney(amount)}</td><td>${fmtMoney(paid)}</td><td>${fmtMoney(open)}</td><td>${escapeHTML(FINANCIAL_STATUS[financialStatusFor(x)]||x.status||'—')}</td></tr>`}).join('')||'<tr><td colspan="6">Nenhuma parcela vinculada a este aluno. Use “Criar parcelas futuras teste”.</td></tr>'}</tbody></table></div></section></div>`}
function openStudentEnrollment(id){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const classOptions=(State.db.classes||[]).map(c=>`<option value="${c.id}" ${s.classId===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join(''),teacherOptions=(State.db.teachers||[]).map(t=>`<option value="${t.id}" ${s.teacherId===t.id?'selected':''}>${escapeHTML(t.name)}</option>`).join(''),bookOptions=activeBooks().map(b=>`<option value="${b.id}" ${s.bookId===b.id?'selected':''}>${escapeHTML(b.name)}</option>`).join('');modal(`<div class="modal-head"><div><span class="eyebrow">Matrícula</span><h3>Efetuar matrícula / pacote</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3"><div class="field"><label>Pacote / curso</label><input id="enrollmentPackage" value="${escapeHTML(s.coursePackage||s.level||'Purple Idiomas - Inglês')}"/></div><div class="field"><label>Plano</label><select id="enrollmentPlan"><option ${s.coursePlan==='Mensal'?'selected':''}>Mensal</option><option ${s.coursePlan==='Semestral'?'selected':''}>Semestral</option><option ${s.coursePlan==='Anual'?'selected':''}>Anual</option><option ${s.coursePlan==='Intensivo'?'selected':''}>Intensivo</option></select></div><div class="field"><label>Tipo de aula</label><select id="enrollmentType"><option ${s.courseType==='Turma'?'selected':''}>Turma</option><option ${s.courseType==='Individual'?'selected':''}>Individual</option><option ${s.courseType==='Online'?'selected':''}>Online</option></select></div><div class="field"><label>Valor da mensalidade</label><input id="enrollmentMonthlyValue" type="number" min="0" step="0.01" value="${Number(s.courseMonthlyValue||s.monthlyValue||0)}"/></div><div class="field"><label>Nº de parcelas</label><input id="enrollmentInstallments" type="number" min="1" step="1" value="${Number(s.courseInstallments||12)}"/></div><div class="field"><label>Primeiro vencimento</label><input id="enrollmentFirstDueDate" type="date" value="${s.courseFirstDueDate||todayISO()}"/></div><div class="field"><label>Data inicial</label><input id="enrollmentStartDate" type="date" value="${s.courseStartDate||s.enrollmentDate||todayISO()}"/></div><div class="field"><label>Previsão de término</label><input id="enrollmentEndDate" type="date" value="${s.courseEndDate||addMonthsISO(todayISO(),12)}"/></div><div class="field"><label>Situação</label><select id="enrollmentSituation">${studentStatusOptions(s.situation||'Matrícula em andamento')}</select></div><div class="field"><label>Turma</label><select id="enrollmentClass"><option value="">—</option>${classOptions}</select></div><div class="field"><label>Professor</label><select id="enrollmentTeacher"><option value="">—</option>${teacherOptions}</select></div><div class="field"><label>Material / livro</label><select id="enrollmentBook"><option value="">—</option>${bookOptions}</select></div></div><label class="checkline"><input id="enrollmentCreateInstallments" type="checkbox" ${s.courseCreateInstallments===true?'checked':''}/> Criar parcelas futuras automaticamente para teste</label><div class="field"><label>Observações da matrícula</label><textarea id="enrollmentNotes">${escapeHTML(s.courseNotes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveStudentEnrollment('${s.id}')">Salvar matrícula</button></div>`,true)}
async function saveStudentEnrollment(id){if(!catalogCanEdit())return toast('Operação não autorizada.');const s=(State.db.students||[]).find(x=>x.id===id);if(!s)return toast('Aluno não encontrado.');const before=cloneValue(s),beforeFinancial=cloneValue(State.db.financialEntries||[]),monthly=Number($('#enrollmentMonthlyValue').value||0),installments=Math.max(1,Number($('#enrollmentInstallments').value||1));if(monthly<0)return toast('Valor não pode ser negativo.');Object.assign(s,{coursePackage:$('#enrollmentPackage').value.trim(),coursePlan:$('#enrollmentPlan').value,courseType:$('#enrollmentType').value,courseMonthlyValue:monthly,courseInstallments:installments,courseFirstDueDate:$('#enrollmentFirstDueDate').value,courseStartDate:$('#enrollmentStartDate').value,courseEndDate:$('#enrollmentEndDate').value,situation:normalizeStudentStatus($('#enrollmentSituation').value),classId:$('#enrollmentClass').value||'',teacherId:$('#enrollmentTeacher').value||'',bookId:$('#enrollmentBook').value||'',courseNotes:$('#enrollmentNotes').value.trim(),contract:studentCourseContractNumber(s),updatedAt:new Date().toISOString()});s.timeline=s.timeline||[];s.timeline.unshift({at:new Date().toISOString(),title:'Matrícula atualizada',detail:`${s.coursePackage||'Pacote'} • ${fmtMoney(monthly)} • ${installments} parcela(s)`});try{if($('#enrollmentCreateInstallments')?.checked)createStudentInstallments(s,monthly,installments,$('#enrollmentFirstDueDate').value,false);await Storage.save(State.db);await logAudit('Atualizou matrícula do aluno',`${s.name} • ${s.coursePackage}`);closeModal();toast('Matrícula salva.');renderPage()}catch(error){restoreRecord(s,before);State.db.financialEntries=beforeFinancial;toast(friendlyError(error,'matrícula do aluno'))}}
function createStudentInstallments(s,monthly=Number(s.courseMonthlyValue||0),installments=Number(s.courseInstallments||12),firstDue=s.courseFirstDueDate||todayISO(),replace=false){State.db.financialEntries=State.db.financialEntries||[];const contract=studentCourseContractNumber(s);if(replace)State.db.financialEntries=State.db.financialEntries.filter(x=>!(x.contract===contract&&x.studentId===s.id&&x.category==='Mensalidade'));for(let i=0;i<installments;i++){State.db.financialEntries.push({id:uid('fin'),type:'receivable',person:s.name,student:s.name,studentId:s.id,contract,description:`Mensalidade ${String(i+1).padStart(2,'0')}/${String(installments).padStart(2,'0')} • ${s.coursePackage||'Curso Purple'}`,category:'Mensalidade',competence:addMonthsISO(firstDue,i).slice(0,7),dueDate:addMonthsISO(firstDue,i),amount:monthly,paidAmount:0,paymentMethod:'A definir',account:'Caixa / Banco',status:'open',owner:State.user.name,notes:'Parcela gerada pela matrícula do aluno.',active:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})}}
function openStudentEnrollmentPremium(id){openStudentEnrollment(id);requestAnimationFrame(()=>ensureStudentEnrollmentPremiumFields(id))}
function syncStudentClassRoster(studentId,newClassId='',oldClassId=''){
  const rosterKey=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase();
  (State.db.classes||[]).forEach(klass=>{
    klass.studentIds=Array.isArray(klass.studentIds)?klass.studentIds:[];
    if(oldClassId&&klass.id===oldClassId)klass.studentIds=klass.studentIds.filter(id=>String(id)!==String(studentId));
    if(newClassId&&klass.id===newClassId&&!klass.studentIds.some(id=>String(id)===String(studentId)))klass.studentIds.push(studentId);
    if(klass.id===oldClassId||klass.id===newClassId)klass.studentsCount=(State.db.students||[]).filter(student=>String(student.classId||'')===String(klass.id)||klass.studentIds.some(id=>String(id)===String(student.id))||rosterKey(student.className||student.turma||student.group||'')===rosterKey(klass.name||'')).length;
  });
}
function ensureStudentEnrollmentPremiumFields(id){const s=(State.db.students||[]).find(x=>x.id===id)||selectedStudent();const monthlyField=$('#enrollmentMonthlyValue'),installmentsField=$('#enrollmentInstallments'),firstDueField=$('#enrollmentFirstDueDate'),situationField=$('#enrollmentSituation');if(!monthlyField||$('#enrollmentMonthlyDiscountValue'))return;if(situationField&&![...situationField.options].some(option=>option.value==='Aguardando turma')){const option=document.createElement('option');option.value='Aguardando turma';option.textContent='Aguardando turma';situationField.appendChild(option);if(s?.situation==='Aguardando turma')situationField.value='Aguardando turma'}const discountField=document.createElement('div');discountField.className='field';discountField.innerHTML=`<label>Mensalidade com desconto</label><input id="enrollmentMonthlyDiscountValue" type="number" min="0" step="0.01" value="${Number(s?.courseMonthlyDiscountValue||s?.courseMonthlyValueWithDiscount||0)||''}" placeholder="Opcional"/>`;monthlyField.closest('.field')?.after(discountField);const materialCard=document.createElement('section');materialCard.className='form-card enrollment-material-plan';materialCard.innerHTML=`<div class="panel-head"><div><span class="eyebrow">Material didático</span><h3>Plano de material</h3><small>Informe quantos materiais o aluno usará. O sistema gera vencimentos a cada 6 meses.</small></div></div><div class="form-grid cols-3"><div class="field"><label>Qtd. de materiais</label><input id="enrollmentMaterialCount" type="number" min="0" step="1" value="${Number(s?.courseMaterialCount||0)||''}" placeholder="0"/></div><div class="field"><label>Valor sem desconto</label><input id="enrollmentMaterialValue" type="number" min="0" step="0.01" value="${Number(s?.courseMaterialValue||0)||''}" placeholder="0,00"/></div><div class="field"><label>Valor com desconto</label><input id="enrollmentMaterialDiscountValue" type="number" min="0" step="0.01" value="${Number(s?.courseMaterialDiscountValue||0)||''}" placeholder="Opcional"/></div><div class="field"><label>Primeiro vencimento do material</label><input id="enrollmentMaterialFirstDueDate" type="date" value="${s?.courseMaterialFirstDueDate||firstDueField?.value||todayISO()}"/></div><div class="field"><label>Situação do material</label><select id="enrollmentMaterialSituation"><option ${s?.courseMaterialSituation==='Aguardando turma'?'selected':''}>Aguardando turma</option><option ${s?.courseMaterialSituation==='Ativo'?'selected':''}>Ativo</option><option ${s?.courseMaterialSituation==='Em aberto'?'selected':''}>Em aberto</option><option ${s?.courseMaterialSituation==='Concluído'?'selected':''}>Concluído</option></select></div><label class="checkline enrollment-material-check"><input id="enrollmentCreateMaterialPlan" type="checkbox" ${s?.courseCreateMaterialPlan===false?'':'checked'}/> Criar plano de pagamento semestral</label></div>`;const createInstallments=$('#enrollmentCreateInstallments');createInstallments?.closest('label')?.before(materialCard);firstDueField?.addEventListener('change',()=>{const materialDue=$('#enrollmentMaterialFirstDueDate');if(materialDue&&!materialDue.dataset.touched)materialDue.value=firstDueField.value});$('#enrollmentMaterialFirstDueDate')?.addEventListener('input',event=>{event.currentTarget.dataset.touched='1'});const classField=$('#enrollmentClass')?.closest('.field'),teacherField=$('#enrollmentTeacher')?.closest('.field');if(classField&&!$('#enrollmentClassHelper'))classField.insertAdjacentHTML('beforeend',`<small id="enrollmentClassHelper" class="helper">${(State.db.classes||[]).length?'Turmas cadastradas no sistema.':'Nenhuma turma cadastrada ainda.'}</small>`);if(teacherField&&!$('#enrollmentTeacherHelper'))teacherField.insertAdjacentHTML('beforeend',`<small id="enrollmentTeacherHelper" class="helper">${(State.db.teachers||[]).length?'Professores cadastrados no sistema.':'Nenhum professor cadastrado ainda.'}</small>`)}
async function saveStudentEnrollmentReliable(id){
  if(!catalogCanEdit())return toast('Operação não autorizada.');
  ensureStudentEnrollmentPremiumFields(id);
  const student=(State.db.students||[]).find(item=>item.id===id);
  if(!student)return toast('Aluno não encontrado.');
  const button=[...document.querySelectorAll('#modalRoot .section-actions .btn')].find(item=>item.textContent.includes('Salvar matrícula'));
  if(button?.disabled)return;
  const value=key=>$('#'+key)?.value||'';
  const monthly=Number(value('enrollmentMonthlyValue')||0),monthlyDiscount=Number(value('enrollmentMonthlyDiscountValue')||0);
  const installments=Number(value('enrollmentInstallments')||1),materialCount=Number(value('enrollmentMaterialCount')||0);
  const materialValue=Number(value('enrollmentMaterialValue')||0),materialDiscount=Number(value('enrollmentMaterialDiscountValue')||0);
  if([monthly,monthlyDiscount,installments,materialCount,materialValue,materialDiscount].some(n=>!Number.isFinite(n)||n<0)||!Number.isInteger(installments)||installments<1||!Number.isInteger(materialCount))return toast('Revise os valores e a quantidade de parcelas.');
  const before=cloneValue(student),beforeFinancial=cloneValue(State.db.financialEntries||[]),oldClassId=student.classId||'';
  const firstDue=value('enrollmentFirstDueDate')||todayISO(),materialFirstDue=value('enrollmentMaterialFirstDueDate')||firstDue;
  const chargedMonthly=monthlyDiscount>0?monthlyDiscount:monthly,chargedMaterial=materialDiscount>0?materialDiscount:materialValue;
  const now=new Date().toISOString();
  Object.assign(student,{coursePackage:value('enrollmentPackage').trim(),coursePlan:value('enrollmentPlan')||'Mensal',courseType:value('enrollmentType')||'Turma',
    courseMonthlyValue:monthly,courseMonthlyDiscountValue:monthlyDiscount,courseInstallments:installments,courseFirstDueDate:firstDue,
    courseStartDate:value('enrollmentStartDate')||todayISO(),courseEndDate:value('enrollmentEndDate')||addMonthsISO(todayISO(),12),
    situation:normalizeStudentStatus(value('enrollmentSituation')||'Matrícula em andamento'),classId:value('enrollmentClass'),teacherId:value('enrollmentTeacher'),
    bookId:value('enrollmentBook'),courseMaterialCount:materialCount,courseMaterialValue:materialValue,courseMaterialDiscountValue:materialDiscount,
    courseMaterialFirstDueDate:materialFirstDue,courseMaterialSituation:value('enrollmentMaterialSituation')||'Aguardando turma',
    courseCreateMaterialPlan:Boolean($('#enrollmentCreateMaterialPlan')?.checked),courseNotes:value('enrollmentNotes').trim(),
    contract:studentCourseContractNumber(student),updatedAt:now});
  syncStudentClassRoster(student.id,student.classId,oldClassId);
  student.timeline=student.timeline||[];
  student.timeline.unshift({at:now,title:'Matrícula atualizada',detail:`${student.coursePackage||'Pacote'} • Mensalidade ${fmtMoney(chargedMonthly)} • ${installments} parcela(s)`});
  student.courseCreateInstallments=Boolean($('#enrollmentCreateInstallments')?.checked);
  const generated=[];
  State.db.financialEntries=State.db.financialEntries||[];
  const buildPlan=(source,category,count,amount,due,everyMonths)=>{
    const old=beforeFinancial.filter(entry=>entry.studentId===student.id&&entry.contract===student.contract&&entry.source===source&&!['paid','cancelled'].includes(financialStatusFor(entry)));
    const ids=new Set(old.map(entry=>entry.id));
    State.db.financialEntries=State.db.financialEntries.filter(entry=>!ids.has(entry.id));
    for(let index=0;index<count;index++){
      const dueDate=addMonthsISO(due,index*everyMonths),previous=old[index];
      const entry={...previous,id:previous?.id||uid('fin'),type:'receivable',person:student.name,student:student.name,studentId:student.id,
        contract:student.contract,description:`${category} ${String(index+1).padStart(2,'0')}/${String(count).padStart(2,'0')} • ${student.coursePackage||'Curso Purple'}`,
        category,subaccount:category,competence:dueDate.slice(0,7),dueDate,amount,paidAmount:0,paymentMethod:previous?.paymentMethod||'A definir',
        account:previous?.account||'Caixa / Banco',status:'open',owner:State.user.name,
        notes:source==='student-material-plan'?'Parcela semestral gerada pelo plano de material didático.':'Parcela gerada pela matrícula do aluno.',
        active:true,source,createdAt:previous?.createdAt||now,updatedAt:now};
      State.db.financialEntries.push(entry);generated.push(entry);
    }
  };
  if($('#enrollmentCreateInstallments')?.checked&&chargedMonthly>0)buildPlan('student-enrollment-plan','Mensalidade',installments,chargedMonthly,firstDue,1);
  if($('#enrollmentCreateMaterialPlan')?.checked&&materialCount>0&&chargedMaterial>0)buildPlan('student-material-plan','Material didático',materialCount,chargedMaterial,materialFirstDue,6);
  const removed=beforeFinancial.filter(entry=>entry.studentId===student.id&&entry.contract===student.contract&&['student-enrollment-plan','student-material-plan'].includes(entry.source)&&!['paid','cancelled'].includes(financialStatusFor(entry))&&!State.db.financialEntries.some(current=>current.id===entry.id));
  if(button){button.disabled=true;button.textContent='Salvando...'}
  let studentSaved=false;
  try{
    if(canPersistRemotely())await saveStudentRecord(student);
    else await Storage.save(State.db);
    studentSaved=true;
    if(canPersistRemotely()){
      for(const entry of generated)await saveFinancialRecord(entry);
      for(const entry of removed)await Storage.remove(entry.id);
    }
    logAudit('Atualizou matrícula do aluno',`${student.name} • ${student.coursePackage}`).catch(error=>console.warn('Purple Gestão — auditoria da matrícula:',error));
    closeModal();toast('Matrícula salva.');renderPage();
  }catch(error){
    console.error('Purple Gestão — matrícula:',error);
    if(!studentSaved){restoreRecord(student,before);State.db.financialEntries=beforeFinancial}
    toast(studentSaved?`Matrícula salva, mas as parcelas não foram concluídas: ${friendlyError(error,'parcelas')}`:friendlyError(error,'matrícula do aluno'));
  }finally{if(button){button.disabled=false;button.textContent='Salvar matrícula'}}
}
