function financialStatusForLegacy2(item={}){const status=String(item.status||'').toLowerCase();if(['paid','pago'].includes(status))return 'paid';if(['cancelled','canceled','cancelado','archived','deleted','void'].includes(status))return 'cancelled';if(['refunded','estornado'].includes(status))return 'refunded';if(['sync_error','erro de sincronização','erro de sincronizacao'].includes(status))return 'sync_error';if(item.dueDate&&item.dueDate<todayISO()&&status!=='paid')return 'overdue';return 'pending'}
