function financialIsAsaasLegacy2(item={}){const origin=String(item.origin||item.provider||item.account||'').toUpperCase();return origin.includes('ASAAS')||Boolean(item.externalChargeId||item.asaasChargeId||item.invoiceUrl||item.bankSlipUrl||item.pixCopyPaste||item.pixQrCode||item.digitableLine)}
