function openFinancialActionLegacy1(action,id){const item=financialEntries('all').find(entry=>entry.id===id);if(!item)return toast('Cobrança não encontrada.');const link=financialPrimaryLink(item);if(action==='copyPix')return financialClipboardCopy(item.pixCopyPaste,'PIX copiado.');if(action==='copyLine')return financialClipboardCopy(item.digitableLine,'Linha digitável copiada.');if(action==='copyCode')return financialClipboardCopy(financialExternalCode(item),'Código da cobrança copiado.');if(action==='copyLink')return financialClipboardCopy(link,'Link de pagamento copiado.');if(action==='openCharge'&&link)return window.open(link,'_blank','noopener');if(action==='openBoleto'&&(item.bankSlipUrl||link))return window.open(item.bankSlipUrl||link,'_blank','noopener');if(action==='viewPix'){const qrImage=financialQrImageSrc(item.pixQrCode||'');return modal(`<div class="modal-head"><div><span class="eyebrow">PIX</span><h3>${escapeHTML(item.person||'Cobrança')}</h3><p class="helper" style="margin-top:6px">Compartilhe o QR Code, o copia e cola ou o link de pagamento.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div>${qrImage?`<div class="student-financial-qr"><img src="${qrImage}" alt="QR Code PIX da cobrança"/></div>`:''}<div class="field"><label>PIX copia e cola</label><textarea readonly>${escapeHTML(item.pixCopyPaste||'')}</textarea></div><div class="section-actions" style="justify-content:flex-start"><button class="btn primary" onclick="App.openFinancialAction('copyPix','${item.id}')">Copiar PIX</button>${link?`<button class="btn ghost" onclick="App.openFinancialAction('copyLink','${item.id}')">Copiar link</button><button class="btn ghost" onclick="App.openFinancialAction('openCharge','${item.id}')">Abrir cobrança</button>`:''}</div>`,true)}toast('Ação indisponível para esta cobrança.')}
function studentFinancialQuickActionsLegacy2(item){if(!item)return '<span class="muted">Sem ação</span>';const id=item.id,status=financialStatusFor(item),paid=status==='paid',asaas=financialIsAsaas(item),link=financialPrimaryLink(item),actions=[];if(!paid)actions.push(`<button onclick="App.editFinancialEntry('receivable','${id}','${item.studentId||''}')">Editar cobrança</button>`);if(link)actions.push(`<button onclick="App.openFinancialAction('openCharge','${id}')">Abrir cobrança</button>`,`<button onclick="App.openFinancialAction('copyLink','${id}')">Copiar link</button>`);actions.push(`<button onclick="App.openFinancialAction('copyCode','${id}')">Copiar código</button>`);if(item.bankSlipUrl)actions.push(`<button onclick="App.openFinancialAction('openBoleto','${id}')">Abrir boleto</button>`);if(item.digitableLine)actions.push(`<button onclick="App.openFinancialAction('copyLine','${id}')">Copiar linha digitável</button>`);if(item.pixCopyPaste)actions.push(`<button onclick="App.openFinancialAction('copyPix','${id}')">Copiar PIX</button>`);if(!paid&&asaas)actions.push(`<button class="danger" onclick="App.confirmCancelFinancialCharge('${id}')">Cancelar / excluir cobrança</button>`);if(!paid&&!asaas)actions.push(`<button class="danger" onclick="App.archiveHistoricalPayment('${id}')">Excluir / arquivar registro</button>`);if(paid)actions.push('<button disabled>Pagamento protegido</button>');return `<button class="btn ghost small" onclick="App.openFinancialDetails('${id}')">Detalhes</button><details class="financial-actions-menu"><summary aria-label="Mais ações" title="Mais ações">⋯</summary><div>${actions.join('')}</div></details>`}
function confirmCancelFinancialChargeLegacy1(id){const item=(State.db.financialEntries||[]).find(x=>x.id===id);if(!item||financialStatusFor(item)==='paid')return toast('Cobranças pagas não podem ser canceladas.');modal(`<div class="modal-head"><div><span class="eyebrow">Operação sensível</span><h3>Cancelar cobrança?</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="financial-confirm-card"><b>${escapeHTML(item.description)}</b><span>${financialInstallmentLabel(item)} · ${fmtMoney(item.fullValue??item.amount)}</span><small>Esta ação também removerá a cobrança pendente correspondente no Asaas e preservará o histórico local.</small></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Voltar</button><button id="financialCancelButton" class="btn danger" onclick="App.cancelFinancialCharge('${id}')">Cancelar cobrança</button></div>`,true)}
async function cancelFinancialChargeLegacy1(id){const item=(State.db.financialEntries||[]).find(x=>x.id===id),button=$('#financialCancelButton');if(!item||button?.disabled)return;button&&(button.disabled=true,button.textContent='Cancelando...');try{const {data,error}=await Supabase.functions.invoke('asaas-manage-charge',{body:{action:'cancel',chargeId:item.supabaseId||item.id}});if(error||data?.error)throw new Error(data?.error||error?.message);item.status='cancelled';item.active=false;item.cancelledAt=new Date().toISOString();await logAudit('Cancelou cobrança',`${item.person} · ${item.description} · ${item.externalChargeId}`);closeModal();renderPage();toast('Cobrança cancelada e histórico preservado.')}catch(error){toast(humanizeFinancialError(error));button&&(button.disabled=false,button.textContent='Cancelar cobrança')}}
function openHistoricalPayment(studentId){if(!can('financial.transactions.create'))return toast('Operação não autorizada.');const student=(State.db.students||[]).find(x=>x.id===studentId);if(!student)return toast('Aluno não encontrado.');modal(`<div class="financial-charge-modal"><div class="modal-head"><div><span class="eyebrow">Migração financeira</span><h3>Registrar parcelas já pagas</h3><p class="helper">Este fluxo grava somente o histórico do Purple Gestão. Nenhuma cobrança será enviada ao Asaas.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div><input id="historicalStudentId" type="hidden" value="${student.id}"/><div class="student-financial-student-chip"><b>${escapeHTML(student.name)}</b><span>Origem: MIGRATION · sem integração externa</span></div><div class="form-grid cols-2"><div class="field"><label for="historicalTotal">Total de parcelas do contrato</label><input id="historicalTotal" type="number" min="1" max="24" value="12"/></div><div class="field"><label for="historicalPaidCount">Parcelas já pagas</label><input id="historicalPaidCount" type="number" min="1" max="24" value="1"/></div><div class="field"><label for="historicalStart">Parcela inicial</label><input id="historicalStart" type="number" min="1" max="24" value="1"/></div><div class="field"><label for="historicalType">Tipo</label><select id="historicalType"><option value="MENSALIDADE">Mensalidade</option><option value="MATERIAL_DIDATICO">Material didático</option><option value="MATRICULA">Matrícula</option><option value="REPOSICAO">Reposição</option></select></div>${financialMoneyInput('historicalFull','Valor integral',student.financeFullValue||student.financeMonthlyValue||0,'oninput="App.formatFinancialMoneyInput(this)"')}${financialMoneyInput('historicalPaid','Valor efetivamente pago',student.financePunctualValue||student.financeMonthlyValue||0,'oninput="App.formatFinancialMoneyInput(this)"')}<div class="field"><label for="historicalFirstDue">Primeiro vencimento</label><input id="historicalFirstDue" type="date" value="${financialDueDateSuggestion(student)}"/></div><div class="field"><label for="historicalMethod">Forma de pagamento</label><select id="historicalMethod"><option>PIX</option><option>BOLETO</option><option>DINHEIRO</option><option>TRANSFERENCIA</option><option>CARTAO</option></select></div></div><label class="check-chip"><input id="historicalUseDueDate" type="checkbox" checked/> Usar vencimento como data de pagamento</label><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Voltar</button><button id="historicalSaveButton" class="btn primary" onclick="App.saveHistoricalPayments()">Registrar pagamentos</button></div></div>`)}
async function saveHistoricalPayments(){const student=(State.db.students||[]).find(x=>x.id===$('#historicalStudentId')?.value),total=Math.max(1,Math.min(24,Number($('#historicalTotal')?.value||1))),count=Math.max(1,Math.min(total,Number($('#historicalPaidCount')?.value||1))),start=Math.max(1,Number($('#historicalStart')?.value||1)),fullValue=financialReadMoney('historicalFull'),paidValue=financialReadMoney('historicalPaid'),firstDue=$('#historicalFirstDue')?.value,type=$('#historicalType')?.value||'MENSALIDADE',method=$('#historicalMethod')?.value||'PIX',button=$('#historicalSaveButton');if(!student||!firstDue||start+count-1>total||fullValue<0||paidValue<0)return toast('Revise os dados do histórico.');button&&(button.disabled=true);const before=cloneValue(State.db.financialEntries||[]);try{const now=new Date().toISOString(),groupId=`hist-${crypto.randomUUID()}`,rows=Array.from({length:count},(_,index)=>{const installmentNumber=start+index,dueDate=window.PurpleFinancial.addMonths(firstDue,index);return {id:uid('finhist'),type:'receivable',studentId:student.id,person:student.name,student:student.name,description:window.PurpleFinancial.description(type,dueDate),category:chargeTypeLabel(type),chargeType:type,subaccount:chargeTypeLabel(type),competence:dueDate.slice(0,7),dueDate,amount:fullValue,fullValue,punctualValue:paidValue,discountValue:Math.max(0,fullValue-paidValue),installmentNumber,installmentTotal:total,installmentGroupId:groupId,origin:'MIGRATION',paidAmount:paidValue,paidDate:$('#historicalUseDueDate')?.checked?dueDate:todayISO(),paymentMethod:method,status:'paid',account:'HISTÓRICO',externalChargeId:'',active:true,createdBy:State.user.id,createdByName:State.user.name,createdAt:now,updatedAt:now}});State.db.financialEntries=[...rows,...(State.db.financialEntries||[])];await Storage.save(State.db);await logAudit('Importou pagamentos históricos',`${student.name} · ${rows.length} parcela(s) · sem Asaas`);closeModal();renderPage();toast(`${rows.length} pagamento(s) histórico(s) registrado(s).`)}catch(error){State.db.financialEntries=before;toast(friendlyError(error,'registro histórico'))}finally{button&&(button.disabled=false)}}
async function archiveHistoricalPaymentLegacy2(id){const item=(State.db.financialEntries||[]).find(x=>x.id===id);if(!item||item.origin==='ASAAS'||financialStatusFor(item)==='paid')return toast('Fatos pagos não podem ser excluídos.');item.active=false;item.archivedAt=new Date().toISOString();await Storage.save(State.db);await logAudit('Arquivou registro financeiro',`${item.person} · ${item.description}`);renderPage();toast('Registro arquivado com rastreabilidade.')}
function studentPaymentsContentFullLegacy3(s){const f=studentFinancialTotals(s),rows=f.rows,next=f.nextDue,economy=Math.max(0,f.totalFull-f.totalPunctual);return `<div class="student-financial-panel"><section class="student-financial-hero"><div><span class="eyebrow">Central financeira individual</span><h3>${escapeHTML(s.name)}</h3><p class="helper">Contrato, cobranças Asaas e fatos históricos em uma única leitura.</p></div><div class="section-actions">${can('financial.transactions.create')?`<button class="btn ghost" onclick="App.openHistoricalPayment('${s.id}')">Registrar pagamento anterior</button><button class="btn primary" onclick="App.editFinancialEntry('receivable','','${s.id}')">+ Nova cobrança</button>`:''}</div></section><section class="student-financial-stat-grid">${financialStudentCard('Valor integral',fmtMoney(f.totalFull),`${fmtMoney(f.totalPunctual)} com pontualidade · economia ${fmtMoney(economy)}`,'neutral')}${financialStudentCard('Pago',fmtMoney(f.paid),`${f.paidRows.length} pagamento(s) pelo valor realmente recebido`,'positive')}${financialStudentCard('Em aberto',fmtMoney(f.open),`${f.openRows.length} cobrança(s) dentro do prazo`,'accent')}${financialStudentCard('Vencido',fmtMoney(f.overdue),f.overdueRows.length?`${f.overdueRows.length} cobrança(s) com desconto expirado`:'Nenhum atraso','danger')}${financialStudentCard('Próximo',next?fmtDate(next.dueDate):'—',next?`${fmtMoney(f.nextDueAmount)} até a data · integral ${fmtMoney(next.fullValue??next.amount)}`:'Sem vencimento futuro','soft')}</section><section class="student-financial-config-grid"><article class="form-card student-financial-config-card"><div class="panel-head"><div><h3>Configuração financeira</h3><small>Padrões usados para pré-preencher novas cobranças.</small></div></div><div class="kpi-strip"><span><b>Forma:</b> ${escapeHTML(studentFinancialDefaultMethod(s))}</span><span><b>Vencimento:</b> ${s.financeDueDay?`dia ${s.financeDueDay}`:'não definido'}</span><span><b>Integral:</b> ${fmtMoney(s.financeFullValue||s.financeMonthlyValue||0)}</span><span><b>Pontual:</b> ${fmtMoney(s.financePunctualValue||s.financeMonthlyValue||0)}</span><span><b>Responsável:</b> ${escapeHTML(s.financialResponsibleName||s.guardian||'—')}</span></div></article><article class="form-card student-financial-config-card"><div class="panel-head"><div><h3>Resumo operacional</h3><small>Valores pendentes mudam com o vencimento; fatos pagos ficam congelados.</small></div></div><div class="student-financial-highlights"><span class="${f.overdueRows.length?'danger':'positive'}">${f.overdueRows.length?'Há desconto expirado':'Sem atraso ativo'}</span><span>${next?`Próxima cobrança em ${fmtDate(next.dueDate)}`:'Nenhum vencimento futuro'}</span><span>${f.paidRows.length?`${f.paidRows.length} pagamento(s) conciliado(s)`:'Ainda sem pagamento confirmado'}</span></div></article></section><section class="form-card"><div class="panel-head"><div><h3>Histórico financeiro</h3><small>Ações secundárias foram agrupadas no menu ⋯.</small></div></div><div class="student-financial-history">${rows.map(x=>{const status=financialStatusFor(x),paid=status==='paid',due=paid?Number(x.paidAmount??x.amount):financialCurrentValue(x);return `<article class="student-financial-history-row"><div class="student-financial-row-title"><strong>${escapeHTML(x.description||chargeTypeLabel(x.category||''))}</strong><small>${financialInstallmentLabel(x)} · ${escapeHTML(x.subaccount||chargeTypeLabel(x.category||''))} ${financialOriginLabel(x)==='MIGRAÇÃO'?'<span class="badge">MIGRAÇÃO</span>':''}</small></div><div><small>Vencimento</small><b>${fmtDate(x.dueDate)}</b></div><div><small>${paid?'Pago':'Devido agora'}</small><b>${fmtMoney(due)}</b><em>${!paid&&status==='pending'&&Number(x.fullValue||x.amount)>due?`Integral ${fmtMoney(x.fullValue||x.amount)}`:!paid&&status==='overdue'?'desconto expirado':''}</em></div><div><span class="status ${financialStatusTone(status)}">${FINANCIAL_STATUS[status]||status}</span>${paid?`<small>${fmtDate(x.paidDate)}</small>`:''}</div><div class="table-actions">${studentFinancialQuickActions(x)}</div></article>`}).join('')||'<div class="empty"><p>Nenhuma cobrança cadastrada para este aluno.</p></div>'}</div></section></div>`}
function renderStudentRecord(s){const tab=State.studentTab&&State.studentTab!=='search'?State.studentTab:'profile';State.studentTab=tab;return `<div class="page student-erp-page student-record-page"><div class="student-erp-shell">${studentToolPanel()}<main class="student-erp-main student-prontuario"><section class="student-record-hero student-prontuario-header"><button class="btn ghost small" onclick="App.closeStudentDrawer()">← Voltar para lista</button><div class="student-record-main">${renderStudentAvatar(s)}<div><span class="eyebrow">Prontuário do aluno</span><h2>${escapeHTML(s.name)}</h2><p>${escapeHTML([studentPhone(s),studentWhatsApp(s)].filter(x=>x&&x!=='—').join(' • ')||'Contato não informado')}</p></div></div><div class="student-record-status">${studentStatusBadge(s)}<button class="btn ghost small" onclick="App.editStudent('${s.id}')">Editar</button><button class="btn ghost small" onclick="App.openStudent('${s.id}')">Atualizar</button><button class="btn ghost small" onclick="App.setStudentTab('contacts')">Histórico</button></div></section><nav class="student-detail-tabs student-record-tabs">${studentTabs().map(([t,label])=>studentTabButton(t,label)).join('')}</nav><section class="student-record-body">${studentDetailContentNextV2(s)}</section></main></div></div>`}


const CLASS_DAY_OPTIONS=['SEGUNDA-FEIRA','TERÇA-FEIRA','QUARTA-FEIRA','QUINTA-FEIRA','SEXTA-FEIRA','SÁBADO'];
const CLASS_SCHEDULE_OPTIONS=[
  {value:'08:00 ÀS 10:10',label:'08:00 ÀS 10:10'},
  {value:'10:20 ÀS 12:30',label:'10:20 ÀS 12:30'},
  {value:'14:00 ÀS 16:10',label:'14:00 ÀS 16:10'},
  {value:'19:00 ÀS 21:10',label:'19:00 ÀS 21:10'}
];
const CLASS_LIVE_SCHEDULE_OPTIONS=[{value:'19:00 ÀS 20:00',label:'19:00 ÀS 20:00'}];
const CLASS_ROOM_OPTIONS=['SALA 1','SALA 2','SALA 3','SALA 6','SALA 7','SALA 8','SALA 9'];
const CLASS_CATEGORY_OPTIONS=['INFANTIL','YOUNG','ADULTO'];
const CLASS_COURSE_OPTIONS=['LITTLE LEARNERS','SUPER KIDS','YOUNG LEARNERS','DISCOVER','CONNECT','EXPLORE','CHANGE','INSPIRE','TRAVEL','CONEXIÓN','EXPANSIÓN','TRANSFORMACIÓN','INSPIRACIÓN'];
const CLASS_LEVEL_OPTIONS=['','STARTER','1','2','3','4','5','6'];
const CLASS_COURSES_BY_CATEGORY={
  INFANTIL:['LITTLE LEARNERS','SUPER KIDS'],
  YOUNG:['YOUNG LEARNERS'],
  ADULTO:['DISCOVER','CONNECT','EXPLORE','CHANGE','INSPIRE','TRAVEL','CONEXIÓN','EXPANSIÓN','TRANSFORMACIÓN','INSPIRACIÓN']
};
const CLASS_BOOK_DEFAULTS=['LITTLE LEARNERS 1','LITTLE LEARNERS 2','LITTLE LEARNERS 3','LITTLE LEARNERS 4','SUPER KIDS STARTER','SUPER KIDS 1','SUPER KIDS 2','SUPER KIDS 3','SUPER KIDS 4','SUPER KIDS 5','SUPER KIDS 6','DISCOVER','CONNECT','EXPLORE','CHANGE','INSPIRE','TRAVEL','CONEXIÓN','EXPANSIÓN','TRANSFORMACIÓN','INSPIRACIÓN'].map(name=>({id:`preset-${name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]+/gi,'-').toLowerCase()}`,name}));
function classScheduleOptions(selected='',type='PRESENCIAL'){const options=String(type||'PRESENCIAL').toUpperCase()==='AO VIVO'?CLASS_LIVE_SCHEDULE_OPTIONS:CLASS_SCHEDULE_OPTIONS;return options.map(opt=>`<option value="${opt.value}" ${opt.value===selected?'selected':''}>${escapeHTML(opt.label)}</option>`).join('')}
function classDayOptions(selected=''){return ['','...'].concat(CLASS_DAY_OPTIONS).map(day=>day==='...' ? '<option value="" disabled>Defina dia</option>' : `<option value="${day}" ${day===selected?'selected':''}>${escapeHTML(day)}</option>`).join('')}
function classRoomOptions(selected=''){return CLASS_ROOM_OPTIONS.map(room=>`<option value="${room}" ${room===selected?'selected':''}>${escapeHTML(room)}</option>`).join('')}
function classTypeOptions(selected='PRESENCIAL'){return ['PRESENCIAL','AO VIVO'].map(type=>`<option value="${type}" ${String(selected||'PRESENCIAL').toUpperCase()===type?'selected':''}>${type}</option>`).join('')}
function classCategoryOptions(selected='ADULTO'){return CLASS_CATEGORY_OPTIONS.map(item=>`<option value="${item}" ${upperFormValue(selected||'ADULTO')===item?'selected':''}>${item}</option>`).join('')}
function classCoursesForCategory(category='ADULTO'){return CLASS_COURSES_BY_CATEGORY[upperFormValue(category||'ADULTO')]||CLASS_COURSES_BY_CATEGORY.ADULTO}
function classLevelsForCourse(category='ADULTO',course=''){category=upperFormValue(category||'ADULTO');course=upperFormValue(course||'');if(category==='INFANTIL'&&course==='LITTLE LEARNERS')return ['1','2','3','4'];if(category==='INFANTIL'&&course==='SUPER KIDS')return ['STARTER','1','2','3','4','5','6'];if(category==='YOUNG')return ['1','2','3','4'];return ['']}
function classCourseOptions(category='ADULTO',selected='CHANGE'){const options=classCoursesForCategory(category);let current=upperFormValue(selected||options[0]||'');if(!options.includes(current))current=options[0]||'';return options.map(item=>`<option value="${item}" ${current===item?'selected':''}>${item}</option>`).join('')}
function classLevelOptions(category='ADULTO',course='',selected=''){const options=classLevelsForCourse(category,course);let current=upperFormValue(selected||'');if(!options.includes(current))current=options[0]||'';return options.map(item=>`<option value="${item}" ${current===item?'selected':''}>${item||'—'}</option>`).join('')}
function classCatalogBooks(){const books=[...CLASS_BOOK_DEFAULTS,...(State.db.books||[]),...(bookItems()||[])].filter(Boolean);const seen=new Set();return books.filter(book=>{const name=upperFormValue(book?.name||book?.title||book?.internal_code||book?.id||'');if(!name||seen.has(name))return false;seen.add(name);book.name=name;return true})}
function classNameBase(category,course,level){category=upperFormValue(category||'ADULTO');course=upperFormValue(course||'CHANGE');level=upperFormValue(level||'');if(category==='INFANTIL'){if(course==='LITTLE LEARNERS')return `LITTLE LEARNERS ${level||'1'}`.trim();if(course==='SUPER KIDS'&&level==='STARTER')return 'SUPER KIDS STARTER';return `SUPER KIDS ${level||'1'}`.trim()}if(category==='YOUNG')return `YOUNG LEARNERS ${level||'1'}`.trim();return `${course||'CHANGE'}`.trim()}
function classNameNumber(record,base){const raw=upperFormValue(record?.name||'');if(!raw.startsWith(base))return Number(record?.classNumber||0)||0;const suffix=raw.slice(base.length).trim().replace(/^\./,'');const numeric=Number(suffix);return Number.isFinite(numeric)&&numeric>0?numeric:(Number(record?.classNumber||0)||0)}
function classNextNumber(category,course,level,ignoreId=''){const base=classNameBase(category,course,level),targetCategory=upperFormValue(category||''),targetCourse=upperFormValue(course||''),targetLevel=upperFormValue(level||'');const nums=(State.db.classes||[]).filter(c=>{if(c.id===ignoreId)return false;const sameStructured=upperFormValue(c.category||'')===targetCategory&&upperFormValue(c.course||'')===targetCourse&&upperFormValue(c.level||'')===targetLevel;const raw=upperFormValue(c.name||'');return sameStructured||raw.startsWith(base)}).map(c=>classNameNumber(c,base)).filter(n=>n>0);return (nums.length?Math.max(...nums):0)+1}
function classCurrentOrNextNumber(category,course,level,recordId=''){const base=classNameBase(category,course,level),existing=recordId?(State.db.classes||[]).find(c=>c.id===recordId):null;if(existing){const sameCategory=!existing.category||upperFormValue(existing.category)===upperFormValue(category||''),sameCourse=!existing.course||upperFormValue(existing.course)===upperFormValue(course||''),sameLevel=upperFormValue(existing.level||'')===upperFormValue(level||'');const number=sameCategory&&sameCourse&&sameLevel?classNameNumber(existing,base):0;if(number>0)return number}return classNextNumber(category,course,level,recordId)}
function classGenerateName(category,course,level,ignoreId='',number=null){const base=classNameBase(category,course,level);const n=number||classCurrentOrNextNumber(category,course,level,ignoreId);const normalizedLevel=upperFormValue(level||'');const separator=normalizedLevel&&normalizedLevel!=='STARTER'?'.':' ';return upperFormValue(`${base}${separator}${n}`)}
function updateClassCatalogFields(){const category=$('#classCategory')?.value||'ADULTO',courseSelect=$('#classCourse'),levelSelect=$('#classLevel');if(courseSelect){const current=courseSelect.value;courseSelect.innerHTML=classCourseOptions(category,current)}const course=courseSelect?.value||'';if(levelSelect)levelSelect.innerHTML=classLevelOptions(category,course,levelSelect.value);updateClassAutoName()}
function updateClassAutoName(){const input=$('#className');if(!input)return;const category=$('#classCategory')?.value||'ADULTO',course=$('#classCourse')?.value||'CHANGE',level=$('#classLevel')?.value||'',recordId=input.dataset.recordId||'',number=classCurrentOrNextNumber(category,course,level,recordId);input.value=classGenerateName(category,course,level,recordId,number);input.dataset.autoName='true';const classNumber=$('#classNumber');if(classNumber)classNumber.value=String(number)}
function studentsByClassId(classId){if(!classId)return [];return (State.db.students||[]).filter(s=>s.classId===classId||s.class_id===classId)}
function classStudentCount(record){return studentsByClassId(record?.id).length||Number(record?.studentsCount||record?.students_count||0)}
function classMaxStudents(record){return Number(record?.capacity||record?.max_students||0)}
function classIsFull(record){const max=classMaxStudents(record);return max>0&&classStudentCount(record)>=max}
function classOpeningSuggestion(record){if(!classIsFull(record))return '';return `${record.name} está cheia → sugerir criar ${classGenerateName(record.category,record.course,record.level,record.id)}`}
function businessTotals(){const students=(State.db.students||[]),teachers=(State.db.teachers||[]),classes=(State.db.classes||[]);return {studentsTotal:students.length,studentsActive:students.filter(s=>dbStatus(s.status||s.situation)==='ATIVO').length,teachersTotal:teachers.length,teachersActive:teachers.filter(t=>dbStatus(t.status)==='ATIVO').length,classesTotal:classes.length,classesActive:classes.filter(c=>dbStatus(c.status)==='ATIVO').length,fullClasses:classes.filter(classIsFull).length}}
function classBlockSeed(block={}){return {day:upperFormValue(block.day||''),time:upperFormValue(block.time||''),room:upperFormValue(block.room||'')}}
function classEditingBlocks(record){const blocks=Array.isArray(record?.scheduleBlocks)&&record.scheduleBlocks.length?record.scheduleBlocks.map(classBlockSeed):[];while(blocks.length<2)blocks.push(classBlockSeed());return blocks.slice(0,2)}
function classHolidaySeed(item={}){return {id:item.id||uid('hol'),date:item.date||'',name:upperFormValue(item.name||''),scope:upperFormValue(item.scope||'NACIONAL')}}
function normalizeClassHolidays(items=[]){return (Array.isArray(items)?items:[]).filter(item=>item&&item.date&&item.name).map(item=>classHolidaySeed({id:item.id||`hol-${item.date}`,date:item.date,name:item.name,scope:item.scope||'NACIONAL'}))}
function syncClassHolidaySettings(list){const normalized=normalizeClassHolidays(list);State.db.classHolidays=normalized;State.db.settings=State.db.settings||{};State.db.settings.classHolidays=normalized;return normalized}
function classHolidayList(){State.db.settings=State.db.settings||{};if(Array.isArray(State.db.settings.classHolidays))return syncClassHolidaySettings(State.db.settings.classHolidays);if(Array.isArray(State.db.classHolidays))return syncClassHolidaySettings(State.db.classHolidays);return syncClassHolidaySettings(seedClassHolidays())}
function classHolidayBetween(date,start,end){if(!date||!start||!end)return false;return String(date)>=String(start)&&String(date)<=String(end)}
function classIsHoliday(date){return classHolidayList().some(item=>String(item.date||'')===String(date||''))}
function classProjectedEndDate(startDate,hours,blocks=[],recessPeriods=[]){if(!startDate||!hours)return '';const totalLessons=Math.max(1,Math.ceil(Number(hours||0)/2));const start=new Date(`${startDate}T00:00:00`);if(Number.isNaN(start.getTime()))return '';let cursor=new Date(start);let counted=0;const recesses=(recessPeriods||[]).filter(period=>period&&period.start&&period.end);while(counted<totalLessons&&cursor.getFullYear()<2035){const iso=cursor.toISOString().slice(0,10);const inRecess=recesses.some(period=>classHolidayBetween(iso,period.start,period.end));if(!classIsHoliday(iso)&&!inRecess)counted++;if(counted>=totalLessons)break;cursor.setDate(cursor.getDate()+7)}return cursor.toISOString().slice(0,10)}
function classRecordType(record){const type=String(record?.classType||record?.type||'').toUpperCase();if(type==='AO VIVO'||type==='PRESENCIAL')return type;return (Array.isArray(record?.scheduleBlocks)&&record.scheduleBlocks.length>1)?'AO VIVO':'PRESENCIAL'}
function classProjectEndFromRecord(record){return classProjectedEndDate(record?.startDate||record?.initialDate||record?.date||'',record?.moduleHours||record?.hours||0,classMeetingBlocks(record),record?.recessPeriods||[])}
function classAutoRecessEnd(start,hours){if(!start||!hours)return '';const d=new Date(`${start}T00:00:00`);if(Number.isNaN(d.getTime()))return '';d.setDate(d.getDate()+Math.max(1,Math.ceil(Number(hours)/2)));return d.toISOString().slice(0,10)}
function classReadRecessPeriods(){return [1,2].map(index=>{const start=$(`#classRecessStart${index}`)?.value||'',end=$(`#classRecessEnd${index}`)?.value||'';return {start,end}}).filter(period=>period.start||period.end)}
function syncClassRecessEnd(){toggleClassLiveBlocks($('#classType')?.value||'PRESENCIAL')}
function classMeetingBlocks(record){const blocks=Array.isArray(record?.scheduleBlocks)&&record.scheduleBlocks.length?record.scheduleBlocks.filter(block=>block&&(block.day||block.time||block.room)):[];if(blocks.length)return blocks;const raw=String(record?.schedule||'').trim();if(!raw)return [];return raw.split('•').map(chunk=>chunk.trim()).filter(Boolean).map(part=>{const [day,time]=''.concat(part).split(/\s+(?=\d{2}:\d{2})/);return {day:(day||'').replace(/\s*\|\s*.*$/,'').trim(),time:(time||part).trim(),room:record?.room||'SALA 1'}})}
function classScheduleSummary(record){const blocks=classMeetingBlocks(record);if(!blocks.length)return 'HORÁRIO NÃO INFORMADO';return blocks.map(block=>[block.day,block.time].filter(Boolean).join(' ')).join(' • ')}
function classScheduleDetail(record){const blocks=classMeetingBlocks(record);if(!blocks.length)return 'SEM HORÁRIO CADASTRADO';return blocks.map(block=>`${block.day||'—'} • ${block.time||'—'} • ${block.room||'—'}`).join(' | ')}
function classHolidays(){return classHolidayList().slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function renderClassScheduleGrid(rows){const rooms=CLASS_ROOM_OPTIONS,blocks=rows.flatMap(row=>classMeetingBlocks(row).map(block=>({...block,className:row.name,teacher:teacherLabelById(row.teacherId),book:bookLabelById(row.bookId),room:block.room||row.room||'—'})));const days=CLASS_DAY_OPTIONS;return `<div class="form-card"><h3>Grade de horários</h3><p class="muted">Visão geral dos horários ocupados e livres por sala.</p><div class="table-wrap"><table><thead><tr><th>Dia</th>${rooms.map(room=>`<th>${escapeHTML(room)}</th>`).join('')}</tr></thead><tbody>${days.map(day=>`<tr><td><b>${escapeHTML(day)}</b></td>${rooms.map(room=>{const match=blocks.find(block=>block.day===day&&block.room===room);return `<td>${match?`<div><b>${escapeHTML(match.className)}</b><p class="muted">${escapeHTML(match.time||'—')} • ${escapeHTML(match.teacher||'—')}</p></div>`:'<span class="badge soft">LIVRE</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function holidayScopeOptions(selected='NACIONAL'){return ['NACIONAL','ESTADUAL','MUNICIPAL'].map(scope=>`<option value="${scope}" ${String(selected||'NACIONAL').toUpperCase()===scope?'selected':''}>${scope}</option>`).join('')}
function openClassHolidayModal(item=null){if(!catalogCanEdit())return toast('Operação não autorizada.');const record=typeof item==='string'?classHolidayList().find(holiday=>holiday.id===item):item;const model=record||classHolidaySeed();modal(`<div class="modal-head"><div><span class="eyebrow">Feriado</span><h3>${record?'Editar':'Novo'} feriado</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3"><div class="field"><label>Data</label><input id="holidayDate" type="date" value="${escapeHTML(model.date||'')}"/></div><div class="field"><label>Nome</label><input id="holidayName" value="${escapeHTML(model.name||'')}" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)"/></div><div class="field"><label>Escopo</label><select id="holidayScope">${holidayScopeOptions(model.scope||'NACIONAL')}</select></div></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button>${record?`<button class="btn danger" onclick="App.deleteClassHoliday('${model.id}')">Excluir</button>`:''}<button class="btn primary" onclick="App.saveClassHoliday('${record?.id||''}')">Salvar feriado</button></div>`,true)}
function renderClassHolidaysTab(){const items=classHolidays();return `<div class="student-detail-grid"><div class="form-card"><div class="section-title" style="margin:0 0 12px"><div><h3>Feriados</h3><p class="muted">Base para cronograma, recessos e cálculo de aulas previstas.</p></div>${catalogCanEdit()?`<button class="btn primary small" onclick="App.openClassHolidayModal()">Novo feriado</button>`:''}</div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Nome</th><th>Escopo</th>${catalogCanEdit()?'<th>Ações</th>':''}</tr></thead><tbody>${items.map(item=>`<tr><td>${fmtDate(item.date)}</td><td><b>${escapeHTML(item.name)}</b></td><td>${escapeHTML(item.scope)}</td>${catalogCanEdit()?`<td><div class="table-actions"><button class="btn ghost small" onclick="App.openClassHolidayModal('${item.id}')">Editar</button><button class="btn danger small" onclick="App.deleteClassHoliday('${item.id}')">Excluir</button></div></td>`:''}</tr>`).join('')||`<tr><td colspan="${catalogCanEdit()?4:3}">Nenhum feriado cadastrado.</td></tr>`}</tbody></table></div></div><div class="form-card"><h3>Recesso e cronograma</h3><p class="muted">Os períodos de recesso e feriados são usados para recalcular o cronograma da turma conforme a carga horária do módulo.</p><div class="mini-card"><strong>Horários padrão</strong><p>${escapeHTML(['08:00 ÀS 10:10','10:20 ÀS 12:30','14:00 ÀS 16:10','19:00 ÀS 21:10','19:00 ÀS 20:00','10:20 ÀS 11:20','11:30 ÀS 12:30'].join(' • '))}</p></div><div class="mini-card" style="margin-top:12px"><strong>Escopos aceitos</strong><p>Nacional • Estadual • Municipal</p></div></div></div>`}
function setClassTab(tab){State.classTab=tab;renderPage()}
function toggleClassLiveBlocks(value){const live=String(value||'PRESENCIAL').toUpperCase()==='AO VIVO';const first=$('#classBlock1Wrap');const second=$('#classBlock2Wrap');if(first)first.style.gridColumn=live?'':'1 / -1';if(second)second.style.display=live?'':'none';const projected=$('#classProjectedEnd');if(projected){const start=$('#classStartDate')?.value||'';const hours=$('#classModuleHours')?.value||0;const blocks=[1].map(index=>({day:upperFormValue($(`#classBlockDay${index}`)?.value||''),time:upperFormValue($(`#classBlockTime${index}`)?.value||''),room:upperFormValue($(`#classBlockRoom${index}`)?.value||'')})).filter(block=>block.day||block.time||block.room);if(live)blocks.push({day:upperFormValue($('#classBlockDay2')?.value||''),time:upperFormValue($('#classBlockTime2')?.value||''),room:upperFormValue($('#classBlockRoom2')?.value||'')});const projectedIso=classProjectedEndDate(start,hours,blocks,classReadRecessPeriods());projected.value=projectedIso?fmtDate(projectedIso):''}}
async function saveClassHoliday(id=''){if(!catalogCanEdit())return toast('Operação não autorizada.');const date=$('#holidayDate')?.value||'';const name=upperFormValue($('#holidayName')?.value);const scope=upperFormValue($('#holidayScope')?.value||'NACIONAL');if(!date||!name)return toast('Informe a data e o nome do feriado.');const list=classHolidayList();const existing=id?list.find(item=>item.id===id):null;const before=cloneValue(list);const payload=classHolidaySeed({id:existing?.id||uid('hol'),date,name,scope});if(existing)Object.assign(existing,payload);else list.unshift(payload);syncClassHolidaySettings(list);try{await Storage.save(State.db);logAudit(existing?'Atualizou feriado':'Criou feriado',`${payload.name} • ${payload.scope}`);closeModal();renderPage();toast(existing?'Feriado atualizado.':'Feriado salvo.')}catch(error){syncClassHolidaySettings(before);toast(friendlyError(error,'salvamento do feriado'))}}
async function deleteClassHoliday(id){if(!catalogCanEdit())return toast('Operação não autorizada.');const list=classHolidayList();const item=list.find(x=>x.id===id);if(!item)return toast('Feriado não encontrado.');if(!confirm('Excluir este feriado?'))return;const before=cloneValue(list);syncClassHolidaySettings(list.filter(x=>x.id!==id));try{await Storage.save(State.db);logAudit('Excluiu feriado',`${item.name} • ${item.scope}`);renderPage();toast('Feriado excluído.')}catch(error){syncClassHolidaySettings(before);toast(friendlyError(error,'exclusão do feriado'))}}

function renderClasses(){if(window.PurpleTurmas?.render)return window.PurpleTurmas.render();if(!catalogCanView())return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;const all=catalogSortByName(State.db.classes||[]),query=State.catalogSearch?.classes||'',arr=all.filter(c=>catalogMatches(c,query,`${teacherLabelById(c.teacherId)} ${bookLabelById(c.bookId)}`));const stats=[metricCard('Turmas',fmtNumber(all.length),'▤',0,query?`${fmtNumber(arr.length)} encontrada(s)`:'Em operação'),metricCard('Capacidade',fmtNumber(all.reduce((s,x)=>s+Number(x.capacity||0),0)),'◫',0,'Total de vagas'),metricCard('Alunos matriculados',fmtNumber(all.reduce((s,x)=>s+Number(x.studentsCount||0),0)),'◎',0,'Base atual'),metricCard('Frequência média',`${fmtNumber(all.reduce((s,x)=>s+Number(x.frequency||0),0)/Math.max(1,all.length),1)}%`,'↻',0,'Consolidação')].join('');const tabs=[['cadastro','Cadastro'],['grade','Grade de horários'],['feriados','Feriados']];const rows=arr.map(c=>`<div class="list-card"><div class="list-card-head"><div><span class="eyebrow">${escapeHTML(classScheduleSummary(c))}</span><h4>${escapeHTML(c.name)}</h4><p>${escapeHTML(c.room||'SALA NÃO INFORMADA')}</p></div><span class="badge">${fmtNumber(Number(c.frequency||0),1)}%</span></div><div class="list-card-meta"><span><b>Professor:</b> ${escapeHTML(teacherLabelById(c.teacherId))}</span><span><b>Livro:</b> ${escapeHTML(bookLabelById(c.bookId))}</span><span><b>Alunos:</b> ${fmtNumber(c.studentsCount||0)}/${fmtNumber(c.capacity||0)}</span><span><b>Indicadores:</b> ${escapeHTML(c.indicators||'—')}</span></div><div class="section-actions" style="justify-content:flex-start;margin-top:10px">${catalogCanEdit()?`<button class="btn ghost small" onclick="App.editClass('${c.id}')">Editar</button><button class="btn soft small" onclick="App.deleteClass('${c.id}')">Excluir</button>`:''}<button class="btn ghost small" onclick="App.openClass('${c.id}')">Abrir</button></div></div>`).join('');const content=State.classTab==='grade'?renderClassScheduleGrid(arr):State.classTab==='feriados'?renderClassHolidaysTab():`<div class="grid cols-2">${rows||'<div class="empty"><div class="emoji">▤</div><h3>Nenhuma turma encontrada</h3></div>'}</div>`;return `<div class="page classes-page"><div class="section-title"><div><h2>Turmas</h2><p>Professor, sala, horário, livro e cronograma.</p></div>${catalogCanEdit()?'<button class="btn primary" onclick="App.editClass()">Nova turma</button>':''}</div><section class="grid cols-4" style="margin-bottom:12px">${stats}</section><div class="field" style="margin-bottom:8px"><input type="search" value="${escapeHTML(query)}" placeholder="Pesquisar por turma, professor, livro, sala, horário ou indicadores" oninput="App.setCatalogSearch('classes',this.value)"/></div><div class="student-erp-tabs" style="margin-top:8px">${tabs.map(([tab,label])=>`<button class="${State.classTab===tab?'active':''}" onclick="App.setClassTab('${tab}')">${label}</button>`).join('')}</div>${content}</div>`}
function renderSchedules(){if(window.PurpleTurmas?.render)return window.PurpleTurmas.render('templates');return `<div class="page"><div class="empty"><h3>Cronogramas indisponíveis</h3><p>Recarregue a aplicação.</p></div></div>`}
function openClass(id){const c=(State.db.classes||[]).find(x=>x.id===id);if(!c)return toast('Turma não encontrada.');const recessPeriods=Array.isArray(c.recessPeriods)?c.recessPeriods.filter(p=>p&&(p.start||p.end)):[];const blocks=classMeetingBlocks(c);const projectedEnd=classProjectEndFromRecord(c);modal(`<div class="modal-head"><div><span class="eyebrow">Turma</span><h3>${escapeHTML(c.name)}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="kpi-strip"><span><b>Tipo:</b> ${escapeHTML(classRecordType(c))}</span><span><b>Professor:</b> ${escapeHTML(teacherLabelById(c.teacherId))}</span><span><b>Horários:</b> ${escapeHTML(classScheduleSummary(c))}</span><span><b>Sala(s):</b> ${escapeHTML([...new Set(blocks.map(block=>block.room).filter(Boolean))].join(' • ')||c.room||'—')}</span><span><b>Alunos:</b> ${fmtNumber(c.studentsCount||0)}/${fmtNumber(c.capacity||0)}</span><span><b>Carga horária:</b> ${fmtNumber(Number(c.moduleHours||0),0)}h</span><span><b>Fim previsto:</b> ${projectedEnd?fmtDate(projectedEnd):'—'}</span></div><section class="form-card"><h3>Grade da turma</h3><div class="table-wrap"><table><thead><tr><th>Dia</th><th>Horário</th><th>Sala</th></tr></thead><tbody>${blocks.length?blocks.map(block=>`<tr><td><b>${escapeHTML(block.day||'—')}</b></td><td>${escapeHTML(block.time||'—')}</td><td>${escapeHTML(block.room||'—')}</td></tr>`).join(''):`<tr><td colspan="3">Nenhuma grade informada.</td></tr>`}</tbody></table></div></section>${recessPeriods.length?`<section class="form-card"><h3>Períodos de recesso</h3><div class="form-grid cols-2">${recessPeriods.map((period,index)=>`<div class="mini-card"><strong>${index+1}º período</strong><p>${escapeHTML([period.start?fmtDate(period.start):'—',period.end?fmtDate(period.end):'—'].join(' até '))}</p></div>`).join('')}</div></section>`:''}${catalogCanEdit()?`<div class="section-actions"><button class="btn soft" onclick="App.closeModal();App.editClass('${c.id}')">Editar</button></div>`:''}`)}
function editClass(id=null){const c=id?(State.db.classes||[]).find(x=>x.id===id):null;const classType=classRecordType(c),category=upperFormValue(c?.category||'ADULTO'),course=upperFormValue(c?.course||'CHANGE'),level=upperFormValue(c?.level||''),autoName=c?.name?c.name:classGenerateName(category,course,level,id||'');const recessPeriods=Array.isArray(c?.recessPeriods)&&c.recessPeriods.length?c.recessPeriods:[{start:'',end:''},{start:'',end:''}];const scheduleBlocks=classEditingBlocks(c);modal(`<div class="classes-editor"><div class="modal-head"><div><span class="eyebrow">${c?'Editar':'Nova'} turma</span><h3>Cadastro da turma</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3"><div class="field"><label>Categoria</label><select id="classCategory" onchange="App.updateClassCatalogFields()">${classCategoryOptions(category)}</select></div><div class="field"><label>Curso</label><select id="classCourse" onchange="App.updateClassCatalogFields()">${classCourseOptions(category,course)}</select></div><div class="field"><label>Nível</label><select id="classLevel" onchange="App.updateClassAutoName()">${classLevelOptions(category,course,level)}</select></div></div><div class="form-grid cols-2"><div class="field"><label>Nome</label><input id="className" data-record-id="${escapeHTML(id||'')}" data-auto-name="true" value="${escapeHTML(autoName)}" data-uppercase="true" readonly/></div><div class="field"><label>Status</label><select id="classStatus"><option value="Ativa" ${String(c?.status||'Ativa').toLowerCase()==='ativa'?'selected':''}>Ativa</option><option value="Inativa" ${String(c?.status||'').toLowerCase()==='inativa'?'selected':''}>Inativa</option></select></div><div class="field"><label>Tipo de turma</label><select id="classType" onchange="App.toggleClassLiveBlocks(this.value)">${classTypeOptions(classType)}</select></div><div class="field"><label>Professor</label><select id="classTeacher"><option value="">Selecione</option>${(State.db.teachers||[]).map(t=>`<option value="${t.id}" ${c?.teacherId===t.id?'selected':''}>${escapeHTML(t.name)}</option>`).join('')}</select></div><div class="field"><label>Livro</label><select id="classBook"><option value="">Selecione</option>${classCatalogBooks().map(b=>`<option value="${b.id}" ${c?.bookId===b.id?'selected':''}>${escapeHTML(b.name)}</option>`).join('')}</select></div><div class="field"><label>Data inicial</label><input id="classStartDate" type="date" value="${escapeHTML(c?.startDate||c?.initialDate||'')}" onchange="App.toggleClassLiveBlocks($('#classType')?.value||'PRESENCIAL')"/></div><div class="field"><label>Capacidade</label><input id="classCapacity" type="number" min="0" value="${Number(c?.capacity||0)}"/></div><div class="field"><label>Alunos matriculados</label><input id="classStudents" type="number" min="0" value="${Number(c?.studentsCount||0)}"/></div><div class="field"><label>Carga horária do módulo (horas)</label><input id="classModuleHours" type="number" min="1" value="${Number(c?.moduleHours||0)}" onchange="App.toggleClassLiveBlocks($('#classType')?.value||'PRESENCIAL')"/></div><div class="field"><label>Fim previsto</label><input id="classProjectedEnd" value="${escapeHTML(classProjectEndFromRecord(c)?fmtDate(classProjectEndFromRecord(c)):'')}" readonly placeholder="Preenchido automaticamente"/></div></div><section class="form-card"><h3>Horários da turma</h3><div class="form-grid cols-2">${[1,2].map(index=>{const block=scheduleBlocks[index-1]||{};const hidden=index===2&&classType!=='AO VIVO';return `<div class="mini-card" id="classBlock${index}Wrap" style="${hidden?'display:none;':''}"><strong>${index}º bloco</strong><div class="form-grid cols-3" style="margin-top:8px"><div class="field"><label>Dia</label><select id="classBlockDay${index}" onchange="App.toggleClassLiveBlocks($('#classType')?.value||'PRESENCIAL')">${classDayOptions(block.day||'')}</select></div><div class="field"><label>Horário</label><select id="classBlockTime${index}" onchange="App.toggleClassLiveBlocks($('#classType')?.value||'PRESENCIAL')">${classScheduleOptions(block.time||'',classType)}</select></div><div class="field"><label>Sala</label><select id="classBlockRoom${index}" onchange="App.toggleClassLiveBlocks($('#classType')?.value||'PRESENCIAL')">${classRoomOptions(block.room||c?.room||'')}</select></div></div></div>`}).join('')}</div><p class="muted" style="margin-top:8px">Use o primeiro bloco para a aula principal. O segundo bloco aparece apenas quando a turma for ao vivo.</p></section><section class="form-card"><h3>Períodos de recesso</h3><div class="form-grid cols-2">${recessPeriods.map((period,index)=>`<div class="mini-card"><div class="field"><label>${index+1}º período - Início</label><input type="date" id="classRecessStart${index+1}" value="${escapeHTML(period.start||'')}" onchange="App.syncClassRecessEnd(${index+1})"/></div><div class="field"><label>${index+1}º período - Fim</label><input type="date" id="classRecessEnd${index+1}" value="${escapeHTML(period.end||'')}" onchange="App.syncClassRecessEnd(${index+1})"/></div><small>Aulas pausam no início e retornam após o fim deste período.</small></div>`).join('')}</div></section><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveClass('${id||''}')">Salvar turma</button></div></div>`,true);setTimeout(()=>App.toggleClassLiveBlocks($('#classType')?.value||classType),0)}
async function saveClass(id){const category=upperFormValue($('#classCategory')?.value||'ADULTO'),course=upperFormValue($('#classCourse')?.value||'CHANGE'),level=upperFormValue($('#classLevel')?.value||''),classType=upperFormValue($('#classType')?.value||'PRESENCIAL')||'PRESENCIAL';let name=upperFormValue($('#className')?.value);const blockIndexes=classType==='AO VIVO'?[1,2]:[1];const blocks=blockIndexes.map(index=>{const day=upperFormValue($(`#classBlockDay${index}`)?.value||'');const time=upperFormValue($(`#classBlockTime${index}`)?.value||'');const room=upperFormValue($(`#classBlockRoom${index}`)?.value||'');return {day,time,room}}).filter(block=>block.day||block.time||block.room);if(!blocks.length)return toast('Informe ao menos um horário para a turma.');const recessPeriods=classReadRecessPeriods();const invalidRecess=recessPeriods.find(period=>(period.start&&!period.end)||(!period.start&&period.end)||(period.start&&period.end&&period.end<period.start));if(invalidRecess)return toast('Informe início e fim do recesso, com fim igual ou posterior ao início.');const startDate=$('#classStartDate')?.value||'';const arr=State.db.classes||[],existing=id?arr.find(x=>x.id===id):null,before=existing?cloneValue(existing):null;const typedClassNumber=classCurrentOrNextNumber(category,course,level,id||'');name=classGenerateName(category,course,level,id||'',typedClassNumber);if(arr.some(item=>item.id!==id&&upperFormValue(item.name)===name)){const nextNumber=classNextNumber(category,course,level,id||'');name=classGenerateName(category,course,level,id||'',nextNumber)}const finalClassNumber=Number(String(name).match(/(\d+)(?!.*\d)/)?.[1]||typedClassNumber||1);const payload={...(existing||{}),id:existing?.id||uid('class'),category,course,level,classNumber:finalClassNumber,name,classType,status:upperFormValue($('#classStatus')?.value||'Ativa'),teacherId:$('#classTeacher')?.value||'',bookId:$('#classBook')?.value||'',startDate,scheduleBlocks:blocks,schedule:blocks.map(block=>[block.day,block.time].filter(Boolean).join(' ')).join(' • '),room:blocks[0]?.room||'',capacity:Number($('#classCapacity')?.value||0),studentsCount:Number($('#classStudents')?.value||0),moduleHours:Number($('#classModuleHours')?.value||0),recessPeriods,projectedEndDate:classProjectedEndDate(startDate,Number($('#classModuleHours')?.value||0),blocks,recessPeriods),updatedAt:new Date().toISOString()};if(existing)Object.assign(existing,payload);else arr.unshift(payload);try{await saveClassRecord(payload);logAudit(existing?'Atualizou turma':'Criou turma',payload.name);closeModal();renderPage();toast(existing?'Turma atualizada.':'Turma salva.')}catch(error){if(existing)restoreRecord(existing,before);else State.db.classes=State.db.classes.filter(x=>x.id!==payload.id);toast(friendlyError(error,'salvamento da turma'))}}
async function deleteClass(id){const c=(State.db.classes||[]).find(x=>x.id===id);if(!c)return toast('Turma não encontrada.');if(!confirm('Excluir cadastro desta turma?'))return;const before=cloneValue(State.db.classes||[]);State.db.classes=State.db.classes.filter(x=>x.id!==id);try{if(hasSupabaseClient())await deleteClassRecord(c);else await Storage.save(State.db);logAudit('Excluiu turma',c.name);renderPage();toast('Turma excluída.')}catch(error){State.db.classes=before;toast(friendlyError(error,'exclusão da turma'))}}
function teacherFilterMatches(t,filter='active'){const status=String(t?.status||'Ativo').toLowerCase();if(filter==='inactive')return status==='inativo';return status!=='inativo'}
function renderTeachers(){if(!catalogCanView())return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;const all=catalogSortByName(State.db.teachers||[]),query=State.catalogSearch?.teachers||'',filter=State.teacherFilter||'active',inactiveCount=all.filter(t=>String(t.status||'Ativo').toLowerCase()==='inativo').length,arr=all.filter(t=>catalogMatches(t,query)).filter(t=>teacherFilterMatches(t,filter));const stats=[metricCard('Professores',fmtNumber(all.length),'♜',0,query?`${fmtNumber(arr.length)} encontrado(s)`:filter==='inactive'?'Inativos':'Equipe ativa'),metricCard('Score médio',fmtNumber(all.reduce((s,x)=>s+Number(x.score||0),0)/Math.max(1,all.length),0),'✦',0,'Saúde da equipe'),metricCard('Turmas atendidas',fmtNumber(all.reduce((s,x)=>s+Number(x.classesCount||0),0)),'▤',0,'Cobertura'),metricCard('Ocorrências',fmtNumber(all.filter(x=>String(x.occurrences||'').trim()).length),'!',0,'Demandas registradas')].join('');const rows=arr.map(t=>`<div class="list-card"><div class="list-card-head"><div><h4>${escapeHTML(t.name)}</h4><p>${escapeHTML(t.email||'')}</p></div><span class="badge teacher-score-badge">${fmtNumber(Number(t.score||0),0)}/100</span></div><div class="list-card-meta"><span><b>Carga horária:</b> ${escapeHTML(t.workload||'—')}</span><span><b>Turmas:</b> ${fmtNumber(t.classesCount||0)}</span><span><b>Telefone:</b> ${escapeHTML(t.phone||'—')}</span><span><b>Indicadores:</b> ${escapeHTML(t.indicators||'—')}</span></div><div class="section-actions" style="justify-content:flex-start;margin-top:12px">${catalogCanEdit()?`<button class="btn ghost small" onclick="App.editTeacher('${t.id}')">Editar</button><button class="btn danger small" onclick="App.deleteTeacher('${t.id}')">Excluir</button>`:''}<button class="btn ghost small" onclick="App.openTeacher('${t.id}')">Abrir</button></div></div>`).join('');return `<div class="page teacher-list-page"><div class="section-title"><div><h2>Professores</h2><p>Base limpa para cadastrar novamente. Use Salvar para gravar e Excluir para remover cadastros.</p></div>${catalogCanEdit()?'<div class="section-actions"><button class="btn danger" onclick="App.clearAllTeachers(this)">Limpar professores</button><button class="btn primary" onclick="App.editTeacher()">Novo professor</button></div>':''}</div><section class="grid cols-4" style="margin-bottom:16px">${stats}</section><div class="field"><input type="search" value="${escapeHTML(query)}" placeholder="Pesquisar por professor, e-mail, telefone, status, carga horária ou indicadores" oninput="App.setCatalogSearch('teachers',this.value)"/></div><div class="teacher-filter-chips"><button class="${filter==='active'?'active':''}" onclick="App.setTeacherFilter('active')">Ativos</button>${inactiveCount?`<button class="${filter==='inactive'?'active':''}" onclick="App.setTeacherFilter('inactive')">Inativos</button>`:''}</div><div class="grid cols-2">${rows||'<div class="empty"><div class="emoji">♜</div><h3>Nenhum professor cadastrado</h3><p>A base está limpa. Clique em Novo professor para começar.</p></div>'}</div></div>`}
function openTeacher(id){const t=(State.db.teachers||[]).find(x=>x.id===id);if(!t)return toast('Professor não encontrado.');modal(`<div class="modal-head"><div><span class="eyebrow">Professor</span><h3>${escapeHTML(t.name)}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="kpi-strip"><span><b>Score:</b> ${fmtNumber(Number(t.score||0),0)}/100</span><span><b>Turmas:</b> ${fmtNumber(t.classesCount||0)}</span><span><b>Carga horária:</b> ${escapeHTML(t.workload||'—')}</span><span><b>Status:</b> ${escapeHTML(t.status||'—')}</span></div><section class="form-card"><h3>Feedbacks</h3><p class="muted">${escapeHTML(t.feedbacks||'—')}</p></section><section class="form-card"><h3>Ocorrências</h3><p class="muted">${escapeHTML(t.occurrences||'—')}</p></section><section class="form-card"><h3>Histórico</h3>${catalogTimeline(t.history)}</section>${catalogCanEdit()?`<div class="section-actions"><button class="btn soft" onclick="App.closeModal();App.editTeacher('${t.id}')">Editar</button></div>`:''}`)}
function editTeacher(id=null){const t=id?(State.db.teachers||[]).find(x=>x.id===id):null;modal(`<div class="modal-head"><div><span class="eyebrow">${t?'Editar':'Novo'} professor</span><h3>Cadastro do professor</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-2"><div class="field"><label>Nome</label><input id="teacherName" value="${escapeHTML(t?.name||'')}" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)"/></div><div class="field"><label>E-mail</label><input id="teacherEmail" type="email" value="${escapeHTML(t?.email||'')}" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)"/></div><div class="field"><label>Telefone</label><input id="teacherPhone" value="${escapeHTML(formatPhoneBR(t?.phone||''))}" data-phone="true" oninput="this.value=App.formatPhoneBR(this.value)"/></div><div class="field"><label>Status</label><select id="teacherStatus"><option value="Ativo" ${String(t?.status||'Ativo').toUpperCase()==='ATIVO'?'selected':''}>Ativo</option><option value="Inativo" ${String(t?.status||'Ativo').toUpperCase()==='INATIVO'?'selected':''}>Inativo</option></select></div><div class="field"><label>Score</label><input id="teacherScore" type="number" min="0" max="100" value="${Number(t?.score||0)}" readonly title="Campo reservado para automação futura"/><small>Campo reservado para automação futura.</small></div><div class="field"><label>Turmas</label><input id="teacherClassesCount" type="number" min="0" value="${Number(t?.classesCount||0)}"/></div><div class="field"><label>Carga horária</label><input id="teacherWorkload" value="${escapeHTML(t?.workload||'')}" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)"/></div><div class="field"><label>Indicadores</label><input id="teacherIndicators" value="${escapeHTML(t?.indicators||'')}" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)" readonly title="Campo reservado para automação futura"/><small>Campo reservado para automação futura.</small></div></div><div class="field"><label>Feedbacks</label><textarea id="teacherFeedbacks" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)">${escapeHTML(t?.feedbacks||'')}</textarea></div><div class="field"><label>Ocorrências</label><textarea id="teacherOccurrences" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)">${escapeHTML(t?.occurrences||'')}</textarea></div><div class="field"><label>Histórico</label><textarea id="teacherHistory" data-uppercase="true" oninput="this.value=App.upperLiveValue(this.value)">${escapeHTML((t?.history||[]).map(h=>`${h.title} — ${h.detail}`).join('\n'))}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button>${id?`<button class="btn danger" onclick="App.deleteTeacher('${id}')">Excluir cadastro</button>`:''}<button class="btn primary" onclick="App.saveTeacher('${id||''}')">Salvar professor</button></div>`,true)}
async function saveTeacher(id){const name=upperFormValue($('#teacherName').value);if(!name)return toast('Informe o nome do professor.');State.db.teachers=Array.isArray(State.db.teachers)?State.db.teachers:[];const arr=State.db.teachers,existing=id?arr.find(x=>x.id===id):null,payload={id:existing?.id||uid('teach'),supabaseId:existing?.supabaseId||'',legacyId:existing?.legacyId||existing?.id||'',name,email:upperFormValue($('#teacherEmail').value),phone:upperFormValue($('#teacherPhone').value),status:upperFormValue($('#teacherStatus').value),score:Number($('#teacherScore').value||0),classesCount:Number($('#teacherClassesCount').value||0),workload:upperFormValue($('#teacherWorkload').value),indicators:upperFormValue($('#teacherIndicators').value),feedbacks:upperFormValue($('#teacherFeedbacks').value),occurrences:upperFormValue($('#teacherOccurrences').value),history:String($('#teacherHistory').value||'').split('\n').filter(Boolean).map(line=>({at:new Date().toISOString(),title:upperFormValue(line.split('—')[0]),detail:upperFormValue(line.split('—').slice(1).join('—'))})),updatedAt:new Date().toISOString()};if(existing)Object.assign(existing,payload);else arr.unshift(payload);writeLocalTeacherCache();try{await saveTeacherRecord(payload);logAudit(existing?'Atualizou professor':'Criou professor',payload.name)}catch(error){console.warn('Purple Gestão — professor mantido no cache local após falha remota:',error)}closeModal();toast(existing?'Professor atualizado.':'Professor salvo.');renderPage()}
async function deleteTeacher(id){const t=(State.db.teachers||[]).find(x=>x.id===id);if(!t)return toast('Professor não encontrado.');if(!confirm('Excluir cadastro deste professor?'))return;State.db.teachers=State.db.teachers.filter(x=>x.id!==id);writeLocalTeacherCache([t.id,t.supabaseId]);try{await deleteTeacherRecord(t);logAudit('Excluiu professor',t.name)}catch(error){console.warn('Purple Gestão — professor removido localmente após falha remota:',error)}closeModal();renderPage();toast('Professor excluído.')}
async function clearAllTeachers(button=null){
  if(!catalogCanEdit())return toast('Operação não autorizada.');
  if(!confirm('Apagar todos os professores cadastrados? Esta ação limpa a base para recadastrar do zero.'))return;
  const before=cloneValue(State.db.teachers||[]);
  State.db.teachers=[];
  State.db.teacherCleanupVersion=TEACHERS_CLEAN_VERSION;
  State.db.teacherCleanupAppliedAt=new Date().toISOString();
  writeLocalTeacherCache(before.flatMap(teacher=>[teacher.id,teacher.supabaseId]).filter(Boolean));
  if(button){button.disabled=true;button.classList.add('loading')}
  try{
    if(hasSupabaseClient()){
      const appDelete=await Supabase.from('app_records').delete().eq('kind','teacher');
      if(appDelete.error)throw appDelete.error;
      if(useTypedAcademicWrites()){
        const typedDelete=await Supabase.from('teachers').delete().neq('id','00000000-0000-0000-0000-000000000000');
        if(typedDelete.error&&!typedTableMissing(typedDelete.error))throw typedDelete.error;
      }
      Storage.baseline=[...Storage.baseline].filter(([id])=>!before.some(teacher=>teacher.id===id)).reduce((map,[id,value])=>map.set(id,value),new Map());
      Storage.metadata=[...Storage.metadata].filter(([id])=>!before.some(teacher=>teacher.id===id)).reduce((map,[id,value])=>map.set(id,value),new Map());
      await Storage.save(State.db);
    }else await Storage.save(State.db);
    logAudit('Limpou professores','Todos os cadastros de professores foram removidos para recadastro.');
    renderPage();
    toast('Base de professores limpa.');
  }catch(error){
    console.warn('Purple Gestão — professores limpos localmente após falha remota:',error);
    renderPage();
    toast('Base de professores limpa.');
  }finally{
    if(button){button.disabled=false;button.classList.remove('loading')}
  }
}
async function applyTeacherDirectoryReset(){
  if(!hasSupabaseClient())return;
  State.db.teachers=[];
  State.db.teacherCleanupVersion=TEACHERS_CLEAN_VERSION;
  State.db.teacherCleanupAppliedAt=new Date().toISOString();
  const appDelete=await Supabase.from('app_records').delete().eq('kind','teacher');
  if(appDelete.error)throw appDelete.error;
  if(useTypedAcademicWrites()){
    const typedDelete=await Supabase.from('teachers').delete().neq('id','00000000-0000-0000-0000-000000000000');
    if(typedDelete.error&&!typedTableMissing(typedDelete.error))throw typedDelete.error;
  }
  [...Storage.baseline.keys()].filter(id=>String(id).startsWith('teach')).forEach(id=>{Storage.baseline.delete(id);Storage.metadata.delete(id)});
  await Storage.save(State.db);
}
window.PurpleApplyTeacherDirectoryReset=applyTeacherDirectoryReset;

function meetingVisibleLegacy1(m){return State.user.role==='direction'||State.user.role==='viewer'||m.sector===State.user.sector||m.participant===State.user.name}
function renderMeetings(){const items=commitmentRows(),editable=can('meetings.edit'),filter=State.meetingFilter||'future',filtered=items.filter(item=>filter==='all'?true:filter==='today'?item.status==='today':filter==='week'?item.status==='week':filter==='month'?item.status==='month':filter==='overdue'?item.status==='overdue':filter==='done'?item.status==='done':['future','today','week'].includes(item.status)),cards=filtered.map(item=>`<div class="list-card coffee-card" data-meeting-search="${escapeHTML(`${item.title} ${item.meta} ${item.source}`.toLowerCase())}"><div class="list-card-head"><div><span class="eyebrow">${item.source}</span><h4>${escapeHTML(item.title)}</h4></div><span class="status ${item.status==='done'?'approved':item.status==='overdue'?'rejected':item.status==='today'?'sent':'draft'}">${item.status==='done'?'Concluída':item.status==='overdue'?'Atrasada':item.status==='today'?'Hoje':item.status==='week'?'7 dias':'30 dias'}</span></div><p>${escapeHTML(item.meta)}</p><div class="list-card-meta"><span><b>Data:</b> ${fmtDate(item.date)}</span><span><b>Prioridade:</b> ${item.priority}</span><span><b>Status:</b> ${item.status}</span></div><div class="section-actions" style="justify-content:flex-start;margin-top:12px">${item.kind==='meeting'&&editable?`<button class="btn ghost small" onclick="App.editMeeting('${item.id}')">Abrir reunião</button><button class="btn soft small" onclick="App.toggleMeetingStatus('${item.id}')">${item.status==='done'?'Reabrir':'Concluir'}</button><button class="btn danger small" onclick="App.deleteMeeting('${item.id}')">Excluir</button>`:''}${item.kind==='action'?`<button class="btn ghost small" onclick="App.openAction('${item.id}')">Abrir ação</button>`:''}${item.kind==='report'?`<button class="btn ghost small" onclick="App.openReport('${item.id}')">Abrir relatório</button>`:''}</div></div>`).join('');return `<div class="page"><div class="section-title"><div><h2>Próximos compromissos</h2><p>Centro operacional com origem, prioridade e prazos.</p></div>${editable?`<button class="btn primary" onclick="App.editMeeting()">Nova reunião</button>`:''}</div><div class="commitment-tabs">${[['future','Próximos 30 dias'],['today','Hoje'],['week','Esta semana'],['month','30 dias'],['overdue','Atrasados'],['done','Concluídos']].map(([key,label])=>`<button class="${filter===key?'active':''}" onclick="App.setMeetingFilter('${key}')">${label}</button>`).join('')}</div><div class="field"><input type="search" placeholder="Pesquisar compromissos" oninput="App.filterMeetings(this.value)"/></div><section class="grid cols-4" style="margin-bottom:16px">${metricCard('Hoje',fmtNumber(items.filter(m=>m.status==='today').length),'◷',0,'Demandas do dia')}${metricCard('Esta semana',fmtNumber(items.filter(m=>m.status==='week').length),'▣',0,'Em até 7 dias')}${metricCard('30 dias',fmtNumber(items.filter(m=>m.status==='month').length),'⌛',0,'Em até 30 dias')}${metricCard('Atrasados',fmtNumber(items.filter(m=>m.status==='overdue').length),'!',0,'Precisam de reação')}</section><div class="grid cols-2">${cards||`<div class="empty"><div class="emoji">◷</div><h3>Nenhum compromisso nesta visão</h3></div>`}</div></div>`}
function filterMeetings(value){const q=value.trim().toLowerCase();$$('[data-meeting-search]').forEach(item=>item.classList.toggle('hidden',!item.dataset.meetingSearch.includes(q)))}
function setMeetingFilter(filter){State.meetingFilter=filter;renderPage()}
function editMeeting(id=null){const m=id?State.db.meetings.find(x=>x.id===id):null;const sectors=availableSectors();modal(`<div class="modal-head"><div><span class="eyebrow">${m?'Editar':'Nova'} reunião</span><h3>Agenda de apresentação</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-2"><div class="field"><label>Título</label><input id="meetingTitle" value="${escapeHTML(m?.title||'Reunião individual — Relatório')}"/></div><div class="field"><label>Setor</label><select id="meetingSector">${sectors.map(s=>`<option value="${s}" ${m?.sector===s?'selected':''}>${SECTOR_LABELS[s]}</option>`).join('')}</select></div></div><div class="form-grid cols-3"><div class="field"><label>Data</label><input id="meetingDate" type="date" value="${m?.date||''}"/></div><div class="field"><label>Horário</label><input id="meetingTime" type="time" value="${m?.time||'09:00'}"/></div><div class="field"><label>Participante</label><input id="meetingParticipant" value="${escapeHTML(m?.participant||'')}"/></div></div><div class="field"><label>Pauta / observações</label><textarea id="meetingNotes" class="large">${escapeHTML(m?.notes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveMeeting('${id||''}')">Salvar reunião</button></div>`,true)}
async function saveMeeting(id){const values={title:upperFormValue($('#meetingTitle').value),sector:$('#meetingSector').value,date:$('#meetingDate').value,time:$('#meetingTime').value,participant:upperFormValue($('#meetingParticipant').value),notes:upperFormValue($('#meetingNotes').value)};if(!values.title||!values.date)return toast('Informe o título e a data.');let m=id?State.db.meetings.find(x=>x.id===id):null;const created=!m,before=m?cloneValue(m):null;if(!m){m={id:uid('meet'),owner:State.user.name,status:'scheduled'};State.db.meetings.push(m)}Object.assign(m,values);try{await Storage.save(State.db);logAudit(id?'Atualizou reunião':'Agendou reunião',`${m.title} • ${fmtDate(m.date)} ${m.time}`);closeModal();toast('Reunião salva.');renderPage()}catch(error){if(created)State.db.meetings=State.db.meetings.filter(item=>item.id!==m.id);else restoreRecord(m,before);toast(friendlyError(error,'salvamento da reunião'))}}
async function toggleMeetingStatus(id){const m=State.db.meetings.find(x=>x.id===id);if(!m)return toast('Reunião não encontrada.');const before=cloneValue(m);m.status=m.status==='done'?'scheduled':'done';try{await Storage.save(State.db);logAudit('Alterou status da reunião',`${m.title} • ${m.status==='done'?'Concluída':'Agendada'}`);renderPage();toast('Status da reunião atualizado.')}catch(error){restoreRecord(m,before);toast(friendlyError(error,'alteração da reunião'))}}
async function deleteMeeting(id){const m=State.db.meetings.find(x=>x.id===id);if(!m||!can('meetings.edit'))return toast('Exclusão não autorizada.');if(!confirm('Excluir esta reunião?'))return;try{await Storage.remove(id)}catch(e){return toast(friendlyError(e,'exclusão de reunião'))}State.db.meetings=State.db.meetings.filter(x=>x.id!==id);logAudit('Excluiu reunião',`${m.title} • ${fmtDate(m.date)}`);toast('Reunião excluída.');renderPage()}

function generateNotifications(){if(State.db.settings.notifications===false)return [];const list=[];State.db.reports.filter(r=>sectorAllowed(r.sector)).forEach(r=>{if(r.status==='sent')list.push({id:`rep-sent-${r.id}`,icon:'▦',title:'Relatório aguardando análise',text:`${SECTOR_LABELS[r.sector]} • ${r.period}`,date:r.createdAt||r.presentation,level:'yellow'});if(r.status==='adjust'&&(State.user.role==='direction'||r.ownerId===State.user.id))list.push({id:`rep-adjust-${r.id}`,icon:'!',title:'Ajuste solicitado',text:`${SECTOR_LABELS[r.sector]} • ${r.adjustmentNote||r.period}`,date:r.updatedAt||r.presentation,level:'red'})});State.db.actions.filter(actionVisible).forEach(a=>{const d=daysUntil(a.deadline);if(!['done','cancelled'].includes(a.status)&&d<0)list.push({id:`act-over-${a.id}`,icon:'◷',title:'Plano de ação atrasado',text:`${a.title} • prazo ${fmtDate(a.deadline)}`,date:a.deadline,level:'red'});else if(!['done','cancelled'].includes(a.status)&&d>=0&&d<=3)list.push({id:`act-soon-${a.id}`,icon:'✓',title:'Prazo de ação próximo',text:`${a.title} • ${d===0?'vence hoje':`vence em ${d} dia(s)`}`,date:a.deadline,level:'yellow'})});State.db.meetings.filter(meetingVisible).forEach(m=>{const d=daysUntil(m.date);if(m.status!=='done'&&d>=0&&d<=2)list.push({id:`meet-${m.id}`,icon:'◷',title:'Reunião próxima',text:`${m.title} • ${fmtDate(m.date)} às ${m.time}`,date:m.date,level:'blue'})});operationalDiaryVisibleSectors().forEach(sector=>{const diary=operationalDiaryEntries().find(entry=>entry.sector===sector&&entry.entryDate===todayISO());if(!diary)list.push({id:`diary-missing-${sector}-${todayISO()}`,icon:'◨',title:'Diário operacional pendente',text:`${SECTOR_LABELS[sector]} ainda não registrou o diário de ${fmtDate(todayISO())}.`,date:todayISO(),level:'yellow'});const snapshot=todayOperationalDiarySnapshot(sector);if(snapshot&&sector==='financeiro'&&Math.abs(intelligenceMetric(snapshot,'divergenciaFinanceira','derivedMetrics'))>0.01)list.push({id:`diary-divergence-${snapshot.sourceId}`,icon:'R$',title:'Divergência financeira diária',text:`O diário financeiro apresenta divergência de ${fmtMoney(intelligenceMetric(snapshot,'divergenciaFinanceira','derivedMetrics'))}.`,date:snapshot.periodEnd||snapshot.sourceUpdatedAt,level:'red'});const criticalGoals=Object.values(snapshot?.goalStatus||{}).filter(goal=>goal?.status==='critical');if(snapshot&&criticalGoals.length)list.push({id:`diary-critical-${snapshot.sourceId}`,icon:'!',title:'Indicador diário crítico',text:`${SECTOR_LABELS[sector]}: ${criticalGoals[0].label} fora do limite esperado.`,date:snapshot.periodEnd||snapshot.sourceUpdatedAt,level:'red'})});if(State.user.role==='direction'){const fin=latestIntelligenceSnapshot('financeiro','semanal');if(fin&&intelligenceMetric(fin,'inadimplencia')>=State.db.settings.delinquencyAlert)list.push({id:`threshold-delinquency-${fin.sourceId||fin.periodEnd}`,icon:'R$',title:'Alerta de inadimplência',text:`O valor consolidado (${fmtMoney(intelligenceMetric(fin,'inadimplencia'))}) ultrapassou o limite configurado.`,date:fin.presentationDate||fin.periodEnd,level:'red'});const ret=latestIntelligenceSnapshot('retencao','semanal');if(ret&&intelligenceMetric(ret,'alunosRisco')>=State.db.settings.retentionRisk)list.push({id:`threshold-retention-${ret.sourceId||ret.periodEnd}`,icon:'!',title:'Alerta de retenção',text:`${fmtNumber(intelligenceMetric(ret,'alunosRisco'))} alunos em risco, acima do limite configurado.`,date:ret.presentationDate||ret.periodEnd,level:'yellow'})}return list.sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function updateNotificationBadge(){const n=generateNotifications().filter(x=>!State.db.readNotifications.includes(x.id)).length;const b=$('#notificationCount');if(b)b.textContent=n}
function renderNotifications(){const arr=generateNotifications();return `<div class="page"><div class="section-title"><div><h2>Notificações</h2><p>Alertas automáticos de relatórios, prazos, reuniões e indicadores críticos.</p></div><button class="btn ghost" onclick="App.markAllNotificationsRead()">Marcar todas como lidas</button></div><div class="notification-list">${arr.map(n=>`<div class="notification ${State.db.readNotifications.includes(n.id)?'':'unread'}"><div class="notification-icon">${n.icon}</div><div style="flex:1"><h4>${escapeHTML(n.title)}</h4><p>${escapeHTML(n.text)}</p><time>${fmtDateTime(n.date)}</time></div>${!State.db.readNotifications.includes(n.id)?`<button class="btn ghost small" onclick="App.markNotificationRead('${n.id}')">Marcar lida</button>`:''}</div>`).join('')||`<div class="empty"><div class="emoji">🔔</div><h3>Nenhuma notificação</h3><p>Está tudo em dia.</p></div>`}</div></div>`}
async function markNotificationRead(id){const before=[...State.db.readNotifications];if(!State.db.readNotifications.includes(id))State.db.readNotifications.push(id);try{await Storage.save(State.db);renderPage()}catch(error){State.db.readNotifications=before;toast(friendlyError(error,'leitura da notificação'))}}
async function markAllNotificationsRead(){const before=[...State.db.readNotifications];State.db.readNotifications=[...new Set([...State.db.readNotifications,...generateNotifications().map(x=>x.id)])];try{await Storage.save(State.db);renderPage();toast('Notificações marcadas como lidas.')}catch(error){State.db.readNotifications=before;toast(friendlyError(error,'leitura das notificações'))}}

function whatsappTabs(){return [['connections','☏','Conexões'],['conversations','◌','Conversas'],['crm','▤','CRM'],['campaigns','↗','Campanhas'],['templates','▦','Mensagens Rápidas'],['automations','⚙','Automações'],['labels','◇','Etiquetas'],['reports','◫','Relatórios'],['settings','☷','Configurações']]}
function legacySetWhatsAppTab(tab){if(!whatsappTabs().some(x=>x[0]===tab))return;State.whatsappTab=tab;renderPage()}
function setWhatsAppSearch(value){State.whatsappSearch=value||'';renderPage()}
function whatsappState(){const scope=State.user?.accessScope==='all_sectors'?'Todas as unidades':'Unidade do usuário';return {...State.whatsappConnection,unit:scope,provider:State.whatsappConnection?.provider||'WhatsApp Cloud API'}}
async function evolutionRequest(action,payload={},method='POST'){
  const options={method,headers:{'Content-Type':'application/json'}};
  if(method!=='GET')options.body=JSON.stringify({action,...payload});
  const url=method==='GET'?`/api/evolution?action=${encodeURIComponent(action)}`:'/api/evolution';
  const response=await fetch(url,options);
  const data=await response.json().catch(()=>({}));
  if(!response.ok||data.error)throw Object.assign(new Error(data.error||'Falha na integração com WhatsApp Cloud API.'),{response,data,status:response.status});
  return data;
}
function normalizeWhatsAppConnection(data={}){
  return {...State.whatsappConnection,configured:data.configured!==false,provider:data.provider||State.whatsappConnection?.provider||'WhatsApp Cloud API',missing:data.missing||[],status:data.status||State.whatsappConnection?.status||'Desconhecido',connected:Boolean(data.connected),device:data.device||State.whatsappConnection?.device||'WhatsApp Business Platform',number:formatPhoneBR(data.number||data.phoneNumberId||State.whatsappConnection?.number||''),businessAccountId:data.businessAccountId||State.whatsappConnection?.businessAccountId||'',phoneNumberId:data.phoneNumberId||State.whatsappConnection?.phoneNumberId||'',lastSync:data.lastSync?fmtDateTime(data.lastSync):new Date().toLocaleString('pt-BR'),qrcode:null}
}
async function refreshWhatsAppConnection({quiet=false}={}){
  if(State.whatsappRuntimeLoading)return;
  State.whatsappRuntimeLoading=true;
  try{
    const config=await evolutionRequest('config',{},'GET');
    if(!config.configured){
      State.whatsappConnection={...State.whatsappConnection,configured:false,provider:config.provider||'WhatsApp Cloud API',status:'WhatsApp Cloud API não configurada',missing:config.missing||[],lastSync:new Date().toLocaleString('pt-BR')};
      if(!quiet)toast(`Configure na Vercel: ${(config.missing||[]).join(', ')}`);
      return;
    }
    const status=await evolutionRequest('status',{},'GET');
    State.whatsappConnection=normalizeWhatsAppConnection(status);
    if(!quiet)toast('Status do WhatsApp atualizado.');
  }catch(error){
    console.error('[Purple Gestão] WhatsApp Cloud API',error);
    State.whatsappConnection={...State.whatsappConnection,status:'Desconectado',connected:false,lastSync:new Date().toLocaleString('pt-BR'),error:error.message};
    if(!quiet)toast('Não foi possível consultar a WhatsApp Cloud API.');
  }finally{
    State.whatsappRuntimeLoading=false;
    if(State.page==='whatsapp')renderPage();
  }
}
function scheduleWhatsAppRuntimeRefresh(){if(State.whatsappRuntimeLoading||State.whatsappRuntimeLoaded)return;State.whatsappRuntimeLoaded=true;setTimeout(()=>refreshWhatsAppConnection({quiet:true}),0)}
function whatsappExtraMessages(id){return (State.whatsappMessages||[]).filter(msg=>msg.conversationId===id).map(msg=>({from:'agent',at:msg.at,text:msg.text}))}
function whatsappConversationSeed(){
  const students=(State.db.students||[]).slice(0,8).map((student,index)=>{const id=`student-${student.id}`,baseMessages=[{from:'contact',at:'09:12',text:`Olá, gostaria de confirmar informações sobre ${student.name||'o aluno'}.`},{from:'agent',at:'09:18',text:'Olá! Vou verificar os dados no Purple Gestão e retorno por aqui.'}];return {id,name:student.name||'Aluno Purple',phone:formatPhoneBR(student.whatsapp||student.phone||student.guardianPhone||'(27)99205-2581'),type:'Aluno',tag:index%2?'Aluno':'Responsável',unread:index===0?2:0,favorite:index===1,pending:index<3,stage:index<2?'Em Atendimento':index<4?'Aguardando Resposta':'Aluno Ativo',sentiment:index===0?'atenção':'estável',linkedStudent:student.name||'',className:classLabelById(student.classId),teacher:teacherLabelById(student.teacherId),financial:student.financialStatus||'—',frequency:`${fmtNumber(student.frequency||0,1)}%`,lastPayment:student.financialStatus==='Em dia'?'Mensalidade regular':'Verificar pendência',occurrences:student.occurrences||'Sem ocorrência crítica',nextClass:'Próxima aula conforme TWR',lastService:student.timeline?.[0]?.title||'Atendimento inicial',tags:[student.situation||'Ativo',student.financialStatus||'Financeiro'],last:`${student.guardian||'Responsável'} • ${student.situation||'Acompanhamento ativo'}`,messages:[...baseMessages,...whatsappExtraMessages(id)]}});
  const fallback=[{id:'lead-1',name:'Lead novo — Conversation',phone:'(27)99205-2581',type:'Lead',tag:'Lead',unread:1,favorite:false,pending:true,stage:'Novo Lead',sentiment:'quente',linkedStudent:'Ainda não vinculado',className:'Interesse em inglês',teacher:'—',financial:'Sem contrato',frequency:'—',lastPayment:'—',occurrences:'Solicitou valores e horários',nextClass:'Aguardando agendamento',lastService:'Primeiro contato comercial',tags:['Lead','Comercial'],last:'Pediu valores e horários disponíveis.',messages:[{from:'contact',at:'10:05',text:'Bom dia! Gostaria de saber os horários de inglês.'},{from:'agent',at:'10:08',text:'Bom dia! Posso te ajudar com as opções da Purple.'},...whatsappExtraMessages('lead-1')]},{id:'teacher-1',name:'Professor — alinhamento',phone:'Interno',type:'Professor',tag:'Professor',unread:0,favorite:true,pending:false,stage:'Finalizadas',sentiment:'estável',linkedStudent:'—',className:'Turmas da semana',teacher:(State.db.teachers||[])[0]?.name||'Equipe pedagógica',financial:'—',frequency:'—',lastPayment:'—',occurrences:'Alinhamento pedagógico',nextClass:'Ver TWR',lastService:'Planejamento semanal',tags:['Professor','Pedagógico'],last:'Alinhamento sobre planejamento semanal.',messages:[{from:'contact',at:'08:40',text:'Preciso confirmar o material da aula de hoje.'},{from:'agent',at:'08:46',text:'Perfeito. Acesse o TWR e confira a preparação inteligente da aula.'},...whatsappExtraMessages('teacher-1')]}];
  return students.length?students.concat(fallback):fallback
}
function whatsappConversations(){const list=whatsappConversationSeed(),filter=State.whatsappFilter||'all',query=String(State.whatsappSearch||'').toLowerCase().trim();return list.filter(item=>(!query||`${item.name} ${item.phone} ${item.last} ${item.linkedStudent} ${item.tags?.join(' ')}`.toLowerCase().includes(query))&&(filter==='all'||(filter==='unread'&&item.unread>0)||(filter==='today'&&item.pending)||(filter==='yesterday'&&item.favorite)||(filter==='week'&&item.type!=='Professor')||(filter==='favorite'&&item.favorite)||(filter==='ai'&&item.sentiment==='atenção')||(filter==='noresponse'&&item.pending)||(filter==='closed'&&item.stage==='Finalizadas')||(filter==='lead'&&item.type==='Lead')||(filter==='students'&&item.type==='Aluno')||(filter==='teachers'&&item.type==='Professor')))}
function whatsappActiveConversation(){const all=whatsappConversationSeed();return all.find(item=>item.id===State.whatsappConversationId)||whatsappConversations()[0]||all[0]}
function setWhatsAppConversation(id){State.whatsappConversationId=id;State.whatsappTab='conversations';renderPage()}
function setWhatsAppFilter(filter){State.whatsappFilter=filter;State.whatsappConversationId='';renderPage()}
async function whatsappConnectionAction(action){
  if(!can('whatsapp.manage'))return toast('Somente usuários autorizados podem gerenciar a conexão.');
  try{
    if(action==='refresh')return refreshWhatsAppConnection();
    const result=await evolutionRequest(action,{});
    if(action==='disconnect'){
      State.whatsappConnection={...State.whatsappConnection,connected:false,status:'Desconectado',qrcode:null,lastSync:new Date().toLocaleString('pt-BR')};
      toast('WhatsApp desconectado.');
      return renderPage();
    }
    State.whatsappConnection=normalizeWhatsAppConnection(result);
    State.whatsappConnection.status=result.status||'Cloud API configurada';
    toast(action==='reconnect'?'Configuração revalidada.':'Configuração da Cloud API validada.');
    renderPage();
  }catch(error){
    console.error('[Purple Gestão] Falha na ação do WhatsApp',error);
    const missing=error.data?.missing?.join(', ');
    State.whatsappConnection={...State.whatsappConnection,status:'Erro de conexão',error:error.message,lastSync:new Date().toLocaleString('pt-BR'),missing:error.data?.missing||State.whatsappConnection.missing};
    toast(missing?`Configure na Vercel: ${missing}`:'Não foi possível concluir a ação no WhatsApp.');
    renderPage();
  }
}
function whatsappTemplateText(template){return ({welcome:'Olá, {{nome}}! Seja bem-vindo(a) à Purple Idiomas. Como posso te ajudar hoje?',followup:'Oi, {{nome}}! Passando para acompanhar seu atendimento e saber se ficou alguma dúvida.',billing:'Olá, {{nome}}! Identificamos uma pendência de {{valor}} com vencimento em {{vencimento}}. Podemos te ajudar a regularizar?',rematricula:'Olá, {{nome}}! Já estamos organizando a rematrícula da turma {{turma}} e queremos garantir sua vaga para o próximo ciclo.',classConfirm:'Olá, {{nome}}! Confirmando sua aula/reposição com {{professor}}. Qualquer ajuste, fale com a equipe Purple.'})[template]||''}
function openWhatsAppTemplate(template){const field=$('#whatsappComposer');if(field){const active=whatsappActiveConversation();field.value=whatsappTemplateText(template).replaceAll('{{nome}}',active?.name?.split(' ')[0]||'').replaceAll('{{turma}}',active?.className||'sua turma').replaceAll('{{professor}}',active?.teacher||'seu professor').replaceAll('{{valor}}','o valor informado').replaceAll('{{vencimento}}','a data combinada');field.focus?.()}else{State.whatsappTab='conversations';renderPage();toast('Abra uma conversa para usar mensagens rápidas.')}}
function writeWhatsAppWithAI(mode='reply'){const active=whatsappActiveConversation(),field=$('#whatsappComposer');const texts={reply:`Olá, ${active?.name?.split(' ')[0]||'tudo bem'}! Revisei seu histórico aqui na Purple e quero te ajudar da forma mais simples possível. Pode me confirmar o melhor horário para conversarmos?`,summary:`Resumo: ${active?.name||'Contato'} está em ${active?.stage||'atendimento'}, financeiro ${active?.financial||'—'} e última demanda: ${active?.last||'—'}.`,risk:`Atenção: este contato merece acompanhamento porque há pendência de resposta, situação financeira ou risco operacional. Sugestão: registrar follow-up ainda hoje.`};if(field){field.value=texts[mode]||texts.reply;field.focus?.();toast('Sugestão preparada pela Purple IA. Revise antes de enviar.')}else modal(`<div class="modal-head"><div><span class="eyebrow">Assistente Purple</span><h3>Análise da conversa</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><p class="muted">${escapeHTML(texts[mode]||texts.summary)}</p><div class="section-actions"><button class="btn primary" onclick="App.closeModal()">Fechar</button></div>`,true)}
function openWhatsAppAiAction(action){writeWhatsAppWithAI(action)}
function openWhatsAppAttachment(type){const input=$('#whatsappFileInput');if(input){input.dataset.kind=type||'document';input.click();return}toast('Abra uma conversa para anexar arquivos.')}
function appendWhatsAppTimeline(active,title,detail){const student=serviceCenterActiveStudent(active);if(!student)return;student.timeline=student.timeline||[];student.timeline.unshift({id:uid(),date:todayISO(),type:'whatsapp',title,detail,by:State.user?.name||'Purple'});Storage.save(State.db)}
async function sendWhatsAppFile(file){const active=whatsappActiveConversation();if(!file||!active)return;toast('Envio de mídia pela Cloud API exige upload/ID de mídia no backend. O drawer já está preparado, mas esta ação ainda não envia arquivo real.')}
async function sendWhatsAppMessage(){const field=$('#whatsappComposer'),text=field?.value.trim(),active=whatsappActiveConversation();if(!text)return toast('Escreva uma mensagem antes de enviar.');const number=String(active?.phone||'').replace(/\D/g,'');State.whatsappMessages=State.whatsappMessages||[];const message={conversationId:active.id,text,at:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),createdAt:new Date().toISOString(),user:State.user?.name||'Purple',status:'enviando'};State.whatsappMessages.push(message);field.value='';renderPage();if(!number){message.status='falhou';message.error='Telefone inválido';renderPage();return toast('Não enviei: esta conversa não possui telefone válido.')}try{const result=await evolutionRequest('sendText',{number,text});message.status=result.status||'enviado';message.externalId=result.externalId||'';appendWhatsAppTimeline(active,'Mensagem enviada pelo WhatsApp',text);toast('Mensagem enviada pelo WhatsApp Cloud API.')}catch(error){console.error('[Purple Gestão] Envio WhatsApp',error);message.status='falhou';message.error=error.message;toast('Mensagem não enviada. Verifique a configuração da WhatsApp Cloud API.')}finally{renderPage()}}
function openWhatsAppCrmCard(stage){modal(`<div class="modal-head"><div><span class="eyebrow">CRM WhatsApp</span><h3>${escapeHTML(stage)}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><p class="muted">Etapa operacional do pipeline. O drag-and-drop real será ligado quando o serviço de conversas estiver persistindo dados no backend.</p><div class="section-actions"><button class="btn primary" onclick="App.closeModal()">Fechar</button></div>`,true)}
function openWhatsAppCampaignPreview(){modal(`<div class="modal-head"><div><span class="eyebrow">Campanhas</span><h3>Prévia de disparo controlado</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="grid cols-3">${metricCard('Público estimado',fmtNumber((State.db.students||[]).length),'◉',0,'Alunos filtrados')}${metricCard('Com WhatsApp',fmtNumber((State.db.students||[]).filter(s=>s.whatsapp||s.phone).length),'☏',0,'Contatos válidos')}${metricCard('Envio real','Pendente','!',0,'Exige API oficial')}</div><p class="muted" style="margin-top:12px">Nenhuma mensagem em massa foi enviada. Esta etapa apenas valida filtros e volume antes da integração oficial.</p><div class="section-actions"><button class="btn primary" onclick="App.closeModal()">Fechar prévia</button></div>`,true)}
function openWhatsAppAutomation(name){toast(`${name} preparado para automação futura. Nenhum disparo automático foi ativado.`)}
async function saveServiceFollowUp(){const active=whatsappActiveConversation(),note=$('#centralFollowUpNote')?.value.trim(),kind=$('#centralFollowUpType')?.value||'Contato realizado',next=$('#centralFollowUpDate')?.value||todayISO();if(!active)return toast('Selecione uma conversa.');if(!note)return toast('Informe o resumo do follow-up.');State.whatsappMessages=State.whatsappMessages||[];const message={conversationId:active.id,text:`Follow-up registrado: ${kind} • ${note}`,at:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),createdAt:new Date().toISOString(),user:State.user?.name||'Purple'};State.whatsappMessages.push(message);const student=serviceCenterActiveStudent(active),before=student?cloneValue(student):null;if(student){student.followUpEntries=student.followUpEntries||[];student.followUpEntries.unshift({id:uid(),date:todayISO(),time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),employee:State.user?.name||'Purple',type:kind,nextDate:next,subject:note,done:true});student.timeline=student.timeline||[];student.timeline.unshift({id:uid(),date:todayISO(),type:'followup',title:`Follow-up: ${kind}`,detail:note,by:State.user?.name||'Purple'});}try{if(student)await saveStudentRecord(student);toast('Follow-up salvo na conversa e na timeline do aluno.');renderPage()}catch(error){State.whatsappMessages=State.whatsappMessages.filter(item=>item!==message);if(student)restoreRecord(student,before);toast(friendlyError(error,'salvamento do follow-up'))}}
