function renderWhatsAppModuleMenu(){return `<aside class="whatsapp-module-menu">${whatsappTabs().map(([key,icon,label])=>`<button class="${State.whatsappTab===key?'active':''}" onclick="App.setWhatsAppTab('${key}')"><span>${appIcon(icon)}</span><b>${label}</b></button>`).join('')}</aside>`}
function renderWhatsAppConnection(){const info=whatsappState(),canManage=can('whatsapp.manage'),missing=(info.missing||[]).join(', ');return `<section class="panel whatsapp-connection-full"><div class="panel-head"><div><span class="eyebrow">Conexões</span><h3>WhatsApp Business da Purple</h3><small>${escapeHTML(info.unit)} • ${escapeHTML(info.provider)}</small></div><span class="status ${info.connected?'success':'warning'}">${escapeHTML(info.status)}</span></div>${missing?`<div class="alert warning"><div class="alert-icon">!</div><div><b>WhatsApp Cloud API não configurada</b><span>Configure estes secrets no backend: ${escapeHTML(missing)}. A interface permanece disponível, mas envio e webhook reais dependem dessas variáveis.</span></div></div>`:''}<div class="whatsapp-connection-grid"><div class="whatsapp-qr large" aria-label="WhatsApp Cloud API"><div></div><span>Cloud API oficial</span><small>Sem WhatsApp Web e sem sessão de navegador. Use o painel da Meta para vincular número, token e webhook.</small></div><div class="contact-facts"><span><b>Status</b>${escapeHTML(info.status)}</span><span><b>Produto</b>${escapeHTML(info.device)}</span><span><b>Número / Phone ID</b>${escapeHTML(info.number)}</span><span><b>Conta Business</b>${escapeHTML(info.businessAccountId||'Configurar META_WHATSAPP_BUSINESS_ACCOUNT_ID')}</span><span><b>Última sincronização</b>${escapeHTML(info.lastSync)}</span></div></div><div class="section-actions">${canManage?`<button class="btn primary small" onclick="App.whatsappConnectionAction('connect')">Validar configuração</button><button class="btn ghost small" onclick="App.whatsappConnectionAction('reconnect')">Revalidar</button><button class="btn soft small" onclick="App.whatsappConnectionAction('refresh')">Atualizar</button>`:'<span class="muted">Somente Direção pode gerenciar a conexão.</span>'}</div></section>`}
function renderWhatsAppConversationList(){const filters=[['all','Todas'],['unread','Não lidas'],['today','Hoje'],['yesterday','Ontem'],['week','Esta semana'],['favorite','Favoritas'],['ai','Com IA'],['noresponse','Sem resposta'],['closed','Finalizadas']],list=whatsappConversations(),active=whatsappActiveConversation();return `<aside class="whatsapp-list"><div class="field"><input type="search" value="${escapeHTML(State.whatsappSearch||'')}" placeholder="Pesquisar conversas, alunos, pais ou telefone" oninput="App.setWhatsAppSearch(this.value)" /></div><div class="whatsapp-filters">${filters.map(([key,label])=>`<button class="${State.whatsappFilter===key?'active':''}" onclick="App.setWhatsAppFilter('${key}')">${label}</button>`).join('')}</div><div class="whatsapp-conversations">${list.map(item=>`<button class="whatsapp-conversation ${active?.id===item.id?'active':''}" onclick="App.setWhatsAppConversation('${item.id}')"><span class="whatsapp-avatar">${escapeHTML(item.name.charAt(0))}</span><span><b>${escapeHTML(item.name)}</b><small>${escapeHTML(item.last)}</small></span>${item.unread?`<i>${item.unread}</i>`:''}</button>`).join('')||'<div class="empty"><h3>Nenhuma conversa neste filtro</h3></div>'}</div></aside>`}
function renderWhatsAppThread(){const active=whatsappActiveConversation();if(!active)return `<section class="whatsapp-chat empty"><h3>Nenhuma conversa selecionada</h3></section>`;const canReply=can('whatsapp.reply');return `<section class="whatsapp-chat"><header><div><span class="eyebrow">${escapeHTML(active.tag)} • ${escapeHTML(active.stage)}</span><h3>${escapeHTML(active.name)}</h3><small>${escapeHTML(active.phone)}</small></div><span class="badge">${escapeHTML(active.type)}</span></header><div class="whatsapp-messages">${active.messages.map(msg=>`<div class="whatsapp-message ${msg.from==='agent'?'agent':'contact'}"><p>${escapeHTML(msg.text)}</p><time>${escapeHTML(msg.at)}${msg.status?` • ${escapeHTML(msg.status)}`:''}</time></div>`).join('')}</div><div class="whatsapp-templates"><button onclick="App.openWhatsAppTemplate('welcome')">Boas-vindas</button><button onclick="App.openWhatsAppTemplate('followup')">Follow-up</button><button onclick="App.openWhatsAppTemplate('billing')">Cobrança</button><button onclick="App.openWhatsAppTemplate('rematricula')">Rematrícula</button><button onclick="App.openWhatsAppTemplate('classConfirm')">Confirmação</button></div><div class="whatsapp-composer"><div class="section-actions"><button class="btn ghost small" onclick="App.openWhatsAppAttachment('Imagem')">Imagem</button><button class="btn ghost small" onclick="App.openWhatsAppAttachment('PDF')">PDF</button><button class="btn ghost small" onclick="App.openWhatsAppAttachment('Documento')">Documento</button><button class="btn ghost small" onclick="App.openWhatsAppAttachment('Áudio')">Áudio</button><button class="btn ghost small" onclick="App.openWhatsAppAttachment('Vídeo')">Vídeo</button><button class="btn ghost small" onclick="App.openWhatsAppAttachment('Emoji')">Emoji</button></div><textarea id="whatsappComposer" ${canReply?'':'disabled'} placeholder="${canReply?'Escreva uma mensagem...':'Seu perfil não possui permissão para responder.'}"></textarea><div class="section-actions"><button class="btn ghost small" onclick="App.openWhatsAppAiAction('reply')" ${canReply?'':'disabled'}>✨ Sugerir resposta</button><button class="btn soft small" onclick="App.openWhatsAppAiAction('summary')">Resumir</button><button class="btn soft small" onclick="App.openWhatsAppAiAction('risk')">Risco</button><button class="btn primary small" onclick="App.sendWhatsAppMessage()" ${canReply?'':'disabled'}>Enviar</button></div></div></section>`}
function renderWhatsAppContactPanel(){const active=whatsappActiveConversation();if(!active)return '';return `<aside class="whatsapp-contact"><div class="panel-head"><div><span class="eyebrow">Painel inteligente</span><h3>${escapeHTML(active.name)}</h3><small>${escapeHTML(active.phone)}</small></div></div><div class="contact-facts"><span><b>Aluno vinculado</b>${escapeHTML(active.linkedStudent||'—')}</span><span><b>Responsável</b>${escapeHTML(active.tag||'—')}</span><span><b>Turma</b>${escapeHTML(active.className||'—')}</span><span><b>Professor</b>${escapeHTML(active.teacher||'—')}</span><span><b>Financeiro</b>${escapeHTML(active.financial||'—')}</span><span><b>Frequência</b>${escapeHTML(active.frequency||'—')}</span><span><b>Último pagamento</b>${escapeHTML(active.lastPayment||'—')}</span><span><b>Ocorrências</b>${escapeHTML(active.occurrences||'—')}</span><span><b>Próxima aula</b>${escapeHTML(active.nextClass||'—')}</span><span><b>Último atendimento</b>${escapeHTML(active.lastService||'—')}</span></div><div class="whatsapp-tag-list">${(active.tags||[]).map(tag=>`<span>${escapeHTML(tag)}</span>`).join('')}</div><div class="form-card"><h3>Linha do tempo</h3><p class="muted">Mensagens futuras serão vinculadas automaticamente à Timeline do aluno, follow-up e auditoria.</p></div></aside>`}
function renderWhatsAppConversations(){return `<div class="whatsapp-layout">${renderWhatsAppConversationList()}${renderWhatsAppThread()}${renderWhatsAppContactPanel()}</div>`}
function renderWhatsAppCRM(){const stages=['Novo Lead','Primeiro Contato','Em Atendimento','Aguardando Resposta','Visita Agendada','Aula Experimental','Negociação','Documentação','Matrícula Confirmada','Aluno Ativo','Rematrícula','Perdido','Cancelado'];const conversations=whatsappConversationSeed();return `<section class="whatsapp-kanban">${stages.map(stage=>{const cards=conversations.filter(c=>c.stage===stage||(stage==='Novo Lead'&&c.type==='Lead')||(stage==='Aluno Ativo'&&c.type==='Aluno'&&!c.pending)).slice(0,4);return `<div class="kanban-column"><h3>${escapeHTML(stage)} <small>${fmtNumber(cards.length)}</small></h3>${cards.map(card=>`<button class="kanban-card" onclick="App.openWhatsAppCrmCard('${escapeHTML(stage)}')"><b>${escapeHTML(card.name)}</b><span>${escapeHTML(card.last)}</span></button>`).join('')||'<p class="muted">Sem contatos nesta etapa.</p>'}</div>`}).join('')}</section>`}
function renderWhatsAppTemplates(){const cats=['Comercial','Financeiro','Pedagógico','Secretaria','Rematrícula','Cobrança','Reposição','Boas-vindas','Aniversário','Documentos','Professor'];return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">Mensagens rápidas</span><h3>Biblioteca com variáveis</h3><small>Use {{nome}}, {{turma}}, {{professor}}, {{valor}} e {{vencimento}}</small></div><button class="btn primary small" onclick="App.saveWhatsAppTemplate()">Salvar modelo</button></div><div class="grid cols-3">${cats.map(cat=>`<div class="form-card"><h3>${escapeHTML(cat)}</h3><p class="muted">${escapeHTML(whatsappTemplateText(cat==='Financeiro'?'billing':cat==='Rematrícula'?'rematricula':cat==='Boas-vindas'?'welcome':'followup'))}</p></div>`).join('')}</div></section>`}
function renderWhatsAppCampaigns(){return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">Campanhas</span><h3>Disparos controlados</h3><small>Selecione público antes de qualquer envio.</small></div><button class="btn primary small" onclick="App.openWhatsAppCampaignPreview()">Visualizar quantidade</button></div><div class="form-grid cols-3"><div class="field"><label>Turma</label><select><option>Todas</option>${(State.db.classes||[]).map(c=>`<option>${escapeHTML(c.name)}</option>`).join('')}</select></div><div class="field"><label>Professor</label><select><option>Todos</option>${(State.db.teachers||[]).map(t=>`<option>${escapeHTML(t.name)}</option>`).join('')}</select></div><div class="field"><label>Situação</label><select><option>Todos</option><option>Ativo</option><option>Rematrícula</option><option>Inadimplente</option><option>Prospect</option></select></div><div class="field"><label>Curso</label><input placeholder="Ex.: Inglês, Espanhol"/></div><div class="field"><label>Data de envio</label><input type="date" value="${todayISO()}"/></div><div class="field"><label>Status</label><select><option>Rascunho</option><option>Aguardando aprovação</option></select></div></div></section>`}
function renderWhatsAppAutomations(){const items=['Boas-vindas','Confirmação de matrícula','Lembrete de aula','Cobrança','Aniversário','Reposição','Reunião','Rematrícula','Pesquisa de satisfação'];return `<section class="grid cols-3">${items.map(name=>`<div class="panel"><div class="panel-head"><div><span class="eyebrow">Automação</span><h3>${escapeHTML(name)}</h3><small>Preparada para integração futura</small></div></div><button class="btn ghost small" onclick="App.openWhatsAppAutomation('${escapeHTML(name)}')">Configurar</button></div>`).join('')}</section>`}
function renderWhatsAppLabels(){const labels=['Lead quente','Cobrança','Rematrícula','Reposição','Pedagógico','Documentos','Aguardando resposta','Risco de evasão'];return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">Etiquetas</span><h3>Organização dos atendimentos</h3></div><button class="btn primary small" onclick="App.saveWhatsAppLabel()">Nova etiqueta</button></div><div class="whatsapp-tag-list large">${labels.map(label=>`<span>${escapeHTML(label)}</span>`).join('')}</div></section>`}
function renderWhatsAppReports(){const total=whatsappConversationSeed().length,unread=whatsappConversationSeed().filter(x=>x.unread).length,pending=whatsappConversationSeed().filter(x=>x.pending).length,leads=whatsappConversationSeed().filter(x=>x.type==='Lead').length;return `<section class="grid cols-4">${metricCard('Conversas',fmtNumber(total),'☏',0,'Base atual')}${metricCard('Não lidas',fmtNumber(unread),'!',0,'Exigem resposta')}${metricCard('Pendentes',fmtNumber(pending),'◷',0,'Sem finalização')}${metricCard('Leads',fmtNumber(leads),'↗',0,'Origem comercial')}</section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Indicadores de atendimento</h3><small>Tempo médio, conversões e origem de matrícula serão calculados pela API real.</small></div></div><div class="kpi-strip"><span><b>Tempo médio:</b> Aguardando sincronização</span><span><b>Atendimentos por colaborador:</b> Estrutura pronta</span><span><b>Matrículas originadas:</b> Estrutura pronta</span></div></section>`}
function renderWhatsAppSettings(){return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">Configurações</span><h3>WhatsApp e canais</h3><small>Área administrativa. A secretária trabalha na Central; conexão fica aqui.</small></div></div><div class="contact-facts"><span><b>Modelo</b>Um número por unidade ou departamento.</span><span><b>Integração</b>WhatsApp Cloud API oficial, webhook e persistência Supabase.</span><span><b>Segurança</b>Responder somente com permissão whatsapp.reply.</span><span><b>Auditoria</b>Registrar usuário, data, hora e mensagem enviada.</span></div><div class="section-actions" style="justify-content:flex-start;margin-top:12px"><button class="btn primary small" onclick="App.openWhatsAppDrawer('connections')">Gerenciar conexão</button></div></section>`}
function renderWhatsAppMain(){if(State.whatsappTab==='connections')return renderWhatsAppConnection();if(State.whatsappTab==='crm')return renderWhatsAppCRM();if(State.whatsappTab==='campaigns')return renderWhatsAppCampaigns();if(State.whatsappTab==='templates')return renderWhatsAppTemplates();if(State.whatsappTab==='automations')return renderWhatsAppAutomations();if(State.whatsappTab==='labels')return renderWhatsAppLabels();if(State.whatsappTab==='reports')return renderWhatsAppReports();if(State.whatsappTab==='settings')return renderWhatsAppSettings();return renderWhatsAppConversations()}
function legacyRenderWhatsApp(){if(!canOpenWhatsApp())return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;return `<div class="page whatsapp-page"><section class="hero whatsapp-hero"><div class="hero-content"><div><span class="eyebrow light">Central de comunicação</span><h2>WhatsApp como CRM de atendimento da Purple.</h2><p>Conversas, pipeline, campanhas, mensagens rápidas, automações, relatórios e contexto do aluno em um módulo nativo. Sem iframe.</p></div><div class="hero-badge">Preparado para API oficial</div></div></section><div class="whatsapp-module-shell">${renderWhatsAppModuleMenu()}<main class="whatsapp-module-main">${renderWhatsAppMain()}</main></div></div>`}

function serviceCenterDrawers(){return {connections:'Conexão do WhatsApp',details:'Dados do aluno',financial:'Financeiro',frequency:'Frequência',occurrences:'Ocorrências',documents:'Documentos',followup:'Follow-up',templates:'Mensagens rápidas'}}
function serviceCenterStages(){return ['Nova','Em atendimento','Aguardando resposta','Resolvida','Arquivada']}
function openWhatsAppDrawer(type){State.whatsappDrawer=type||'';renderPage()}
function closeWhatsAppDrawer(){State.whatsappDrawer='';renderPage()}
function setWhatsAppTab(tab){const map={connections:'connections',conversations:'',crm:'crm',campaigns:'campaigns',templates:'templates',automations:'automations',labels:'crm',reports:'reports',settings:'settings'};State.whatsappDrawer=map[tab]||'';renderPage()}
function setWhatsAppCrmStatus(id,stage){if(!id||!stage)return;State.whatsappStages=State.whatsappStages||{};State.whatsappStages[id]=stage;appendWhatsAppTimeline(whatsappConversationSeed().find(item=>item.id===id),`Status do CRM alterado para ${stage}`,'Central de Atendimento');toast(`Status do atendimento alterado para ${stage}.`);renderPage()}
function serviceCenterActiveStudent(active){if(!active?.id?.startsWith('student-'))return null;const studentId=active.id.replace(/^student-/,'');return (State.db.students||[]).find(s=>s.id===studentId)||null}
function serviceCenterFilters(){return [['all','Todas'],['unread','Não lidas'],['today','Hoje'],['week','Semana'],['noresponse','Sem resposta'],['students','Alunos'],['lead','Leads']]}
function renderServiceConversationList(){const list=whatsappConversations(),active=whatsappActiveConversation();return `<aside class="service-conversations"><div class="service-panel-title"><div><span class="eyebrow">Entrada</span><h2>Conversas</h2></div><span class="service-status-dot ${State.whatsappConnection?.connected?'online':''}" title="${escapeHTML(State.whatsappConnection?.status||'')}"></span></div><div class="field service-search"><input type="search" value="${escapeHTML(State.whatsappSearch||'')}" placeholder="Buscar por nome ou telefone" oninput="App.setWhatsAppSearch(this.value)"/></div><div class="whatsapp-filters compact">${serviceCenterFilters().map(([key,label])=>`<button class="${State.whatsappFilter===key?'active':''}" onclick="App.setWhatsAppFilter('${key}')">${label}</button>`).join('')}</div><div class="service-conversation-list">${list.map(item=>`<button class="service-conversation ${active?.id===item.id?'active':''}" onclick="App.setWhatsAppConversation('${item.id}')"><span class="whatsapp-avatar">${escapeHTML(item.name.charAt(0))}</span><span><b>${escapeHTML(item.name)}</b><small>${escapeHTML(item.last)}</small><em>${escapeHTML(item.phone)}</em></span>${item.unread?`<i>${item.unread}</i>`:''}</button>`).join('')||'<div class="empty"><h3>Nenhuma conversa</h3><p>Ajuste a busca ou os filtros.</p></div>'}</div></aside>`}
function renderServiceChat(active){if(!active)return `<section class="service-chat empty"><h3>Selecione uma conversa</h3></section>`;const canReply=can('whatsapp.reply'),currentStage=State.whatsappStages?.[active.id]||active.stage,stages=serviceCenterStages();return `<section class="service-chat"><header class="service-chat-head"><div><h2>${escapeHTML(active.name)}</h2><small><span class="service-online">● WhatsApp</span> ${escapeHTML(active.phone||'—')} • ${escapeHTML(active.className||'—')}</small></div><div class="service-chat-controls"><label>Atendimento<select onchange="App.setWhatsAppCrmStatus('${active.id}',this.value)"><option value="${escapeHTML(currentStage)}">${escapeHTML(currentStage||'Em atendimento')}</option>${stages.filter(stage=>stage!==currentStage).map(stage=>`<option value="${escapeHTML(stage)}">${escapeHTML(stage)}</option>`).join('')}</select></label></div></header><div class="whatsapp-messages service-messages">${active.messages.map(msg=>`<div class="whatsapp-message ${msg.from==='agent'?'agent':'contact'}"><p>${escapeHTML(msg.text)}</p><time>${escapeHTML(msg.at)}${msg.status?` • ${escapeHTML(msg.status)}`:''}</time></div>`).join('')}</div><div class="service-composer"><input id="whatsappFileInput" type="file" hidden onchange="App.sendWhatsAppFile(this.files&&this.files[0])" /><textarea id="whatsappComposer" ${canReply?'':'disabled'} placeholder="${canReply?'Digite sua resposta...':'Seu perfil não possui permissão para responder.'}"></textarea><div class="service-composer-actions"><button title="Anexo" onclick="App.openWhatsAppAttachment('Anexo')" ${canReply?'':'disabled'}>📎 Anexo</button><button title="Imagem" onclick="App.openWhatsAppAttachment('Imagem')" ${canReply?'':'disabled'}>📷 Imagem</button><button title="PDF" onclick="App.openWhatsAppAttachment('PDF')" ${canReply?'':'disabled'}>📄 PDF</button><button title="Áudio" onclick="App.openWhatsAppAttachment('Áudio')" ${canReply?'':'disabled'}>🎤 Áudio</button><button onclick="App.openWhatsAppDrawer('templates')" ${canReply?'':'disabled'}>Modelo</button><button onclick="App.openWhatsAppDrawer('followup')">Follow-up</button><button onclick="App.openWhatsAppDrawer('financial')">Financeiro</button><button class="primary" onclick="App.sendWhatsAppMessage()" ${canReply?'':'disabled'}>Enviar</button></div></div></section>`}
function renderServiceSmartPanel(active){if(!active)return '';const rows=[['Dados','details',active.linkedStudent],['Financeiro','financial',active.financial],['Frequência','frequency',active.frequency],['Ocorrências','occurrences',active.occurrences],['Documentos','documents','Arquivos do aluno'],['Follow-up','followup','Registrar contato']];return `<aside class="service-smart-panel"><div class="service-person-head"><span class="eyebrow">Aluno / contato</span><h3>${escapeHTML(active.name)}</h3><small>${escapeHTML(active.phone)}</small></div><div class="service-person-list">${rows.map(([label,type,value])=>`<button onclick="App.openWhatsAppDrawer('${type}')"><b>${escapeHTML(label)}</b><span>${escapeHTML(value||'—')}</span></button>`).join('')}</div></aside>`}
function renderServiceDrawerContent(type,active){
  const student=serviceCenterActiveStudent(active),label=serviceCenterDrawers()[type]||'Detalhes';
  if(type==='connections')return renderWhatsAppConnection();
  if(type==='details')return `<div class="service-drawer-section"><h3>Dados do aluno</h3><div class="contact-facts"><span><b>Aluno</b>${escapeHTML(active?.linkedStudent||active?.name||'—')}</span><span><b>Telefone</b>${escapeHTML(active?.phone||'—')}</span><span><b>Responsável</b>${escapeHTML(active?.tag||'—')}</span><span><b>Turma</b>${escapeHTML(active?.className||'—')}</span><span><b>Professor</b>${escapeHTML(active?.teacher||'—')}</span><span><b>Próxima aula</b>${escapeHTML(active?.nextClass||'—')}</span></div></div>`;
  if(type==='financial')return `<div class="service-drawer-section"><h3>Financeiro do contato</h3><div class="grid cols-3">${metricCard('Situação',active?.financial||'—','R$',0,'Cadastro do aluno')}${metricCard('Último pagamento',active?.lastPayment||'—','✓',0,'Resumo operacional')}${metricCard('Ação','Cobrança','☎',0,'Próximo contato')}</div><p class="muted">Para recebimento completo, use a aba Financeiro do aluno. Aqui a secretária enxerga o contexto sem sair do atendimento.</p></div>`;
  if(type==='enrollment')return `<div class="service-drawer-section"><h3>Matrícula</h3><div class="contact-facts"><span><b>Aluno</b>${escapeHTML(active?.linkedStudent||'Ainda não vinculado')}</span><span><b>Turma</b>${escapeHTML(active?.className||'—')}</span><span><b>Professor</b>${escapeHTML(active?.teacher||'—')}</span><span><b>Status CRM</b>${escapeHTML(active?.stage||'—')}</span></div><button class="btn primary small" onclick="App.go('students')">Abrir prontuário completo</button></div>`;
  if(type==='frequency')return `<div class="service-drawer-section"><h3>Frequência</h3><div class="service-big-number">${escapeHTML(active?.frequency||'—')}</div><p class="muted">Resumo para atendimento rápido. Histórico detalhado permanece no prontuário do aluno.</p></div>`;
  if(type==='occurrences')return `<div class="service-drawer-section"><h3>Ocorrências</h3><p class="muted">${escapeHTML(active?.occurrences||student?.occurrences||'Sem ocorrências registradas.')}</p><button class="btn ghost small" onclick="App.openWhatsAppDrawer('followup')">Transformar em follow-up</button></div>`;
  if(type==='documents')return `<div class="service-drawer-section"><h3>Documentos</h3><div class="service-doc-list"><span>Contrato</span><span>Declaração</span><span>Comprovantes</span><span>Material didático</span></div><p class="muted">Uploads reais serão vinculados ao cadastro/documentos do aluno.</p></div>`;
  if(type==='followup')return `<div class="service-drawer-section"><h3>Follow-up</h3><div class="form-grid cols-2"><div class="field"><label>Tipo</label><select id="centralFollowUpType"><option>Contato realizado</option><option>Cobrança</option><option>Pedagógico</option><option>Rematrícula</option></select></div><div class="field"><label>Próximo contato</label><input id="centralFollowUpDate" type="date" value="${todayISO()}"/></div></div><div class="field"><label>Resumo</label><textarea id="centralFollowUpNote" placeholder="Registre o que foi combinado no atendimento."></textarea></div><button class="btn primary small" onclick="App.saveServiceFollowUp()">Salvar follow-up</button></div>`;
  if(type==='templates')return renderWhatsAppTemplates();
  return `<div class="service-drawer-section"><h3>${escapeHTML(label)}</h3><p class="muted">Painel preparado para uso dentro da Central de Atendimento.</p></div>`
}
function renderServiceDrawer(active){const type=State.whatsappDrawer;if(!type)return '';const label=serviceCenterDrawers()[type]||'Painel';return `<aside class="service-drawer"><div class="modal-head"><div><span class="eyebrow">Central de Atendimento</span><h3>${escapeHTML(label)}</h3></div><button class="modal-close" onclick="App.closeWhatsAppDrawer()">×</button></div>${renderServiceDrawerContent(type,active)}</aside>`}
function renderWhatsApp(){if(!canOpenWhatsApp())return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;const active=whatsappActiveConversation(),info=whatsappState();return `<div class="page service-center-page"><div class="service-center-top"><div><span class="eyebrow">Central de Atendimento</span><h1>WhatsApp da Purple</h1></div><div class="service-top-tabs"><button class="active" onclick="App.closeWhatsAppDrawer()">Conversas</button><button class="${State.whatsappDrawer==='connections'?'active':''}" onclick="App.openWhatsAppDrawer('connections')">${info.connected?'Conectado':'Conectar WhatsApp'}</button></div></div><div class="service-workspace ${State.whatsappDrawer?'drawer-open':''}">${renderServiceConversationList()}${renderServiceChat(active)}${renderServiceSmartPanel(active)}${renderServiceDrawer(active)}</div></div>`}

function editTask(id=null){const t=id?(State.db.tasks||[]).find(x=>x.id===id):null;modal(`<div class="modal-head"><div><span class="eyebrow">Meu Dia</span><h3>${t?'Editar':'Nova'} tarefa</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="field"><label>Título</label><input id="taskTitle" value="${escapeHTML(t?.title||'')}"/></div><div class="field"><label>Descrição</label><textarea id="taskDescription">${escapeHTML(t?.description||'')}</textarea></div><div class="form-grid cols-2"><div class="field"><label>Prioridade</label><select id="taskPriority"><option value="alta" ${t?.priority==='alta'?'selected':''}>Alta</option><option value="media" ${!t||t?.priority==='media'?'selected':''}>Média</option><option value="baixa" ${t?.priority==='baixa'?'selected':''}>Baixa</option></select></div><div class="field"><label>Prazo</label><input id="taskDue" type="date" value="${t?.due_date||todayISO()}"/></div></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveTask('${id||''}')">Salvar tarefa</button></div>`,true)}
async function saveTask(id){const title=upperFormValue($('#taskTitle').value);if(!title)return toast('Informe o título da tarefa.');const existing=id?State.db.tasks.find(x=>x.id===id):null,payload={user_id:existing?.user_id||State.user.id,title,description:upperFormValue($('#taskDescription').value),priority:$('#taskPriority').value,due_date:$('#taskDue').value||null,sector:existing?.sector||State.user.sector,source_type:existing?.source_type||'manual',source_id:existing?.source_id||null};const result=id?await Supabase.from('tasks').update(payload).eq('id',id).select().single():await Supabase.from('tasks').insert(payload).select().single();if(result.error)return toast(friendlyError(result.error,'salvamento da tarefa'));if(id)Object.assign(existing,result.data);else State.db.tasks.unshift(result.data);closeModal();renderPage();premiumToast('Tarefa salva. Mais um passo organizado.')}
async function createPurpleIaTask(index){const item=purpleIaRecommendations()[index];if(!item)return toast('Recomendação não encontrada.');const payload={user_id:State.user.id,title:item.title,description:[item.problem,item.actions[0]||'',item.impact].filter(Boolean).join(' '),priority:item.priority,due_date:item.dueDate||todayISO(),sector:item.sector==='integrado'?State.user.sector:item.sector,source_type:'manual',source_id:null};const {data,error}=await Supabase.from('tasks').insert(payload).select().single();if(error)return toast(friendlyError(error,'criação da tarefa sugerida'));State.db.tasks.unshift(data);await logAudit('Criou tarefa a partir do Purple IA',`${item.title} • ${SECTOR_LABELS[item.sector]||'Geral'}`);renderPage();premiumToast('Tarefa criada a partir da recomendação do Purple IA.')}
async function toggleTask(id,completed){const {data,error}=await Supabase.from('tasks').update({completed,completed_at:completed?new Date().toISOString():null,archived_at:completed?new Date().toISOString():null,completed_by:completed?State.user.name:null,completed_by_id:completed?State.user.id:null}).eq('id',id).select().single();if(error)return toast(friendlyError(error));Object.assign(State.db.tasks.find(x=>x.id===id),data);renderPage();if(completed)premiumToast('Excelente! Tarefa concluída e arquivada.')}
async function deleteTask(id){if(!confirm('Excluir esta tarefa?'))return;const {error}=await Supabase.from('tasks').delete().eq('id',id);if(error)return toast(friendlyError(error));State.db.tasks=State.db.tasks.filter(x=>x.id!==id);renderPage()}
function answerPulse(feeling){const allowed=['excelente','bem','normal','dificil','muito_dificil'];if(!can('pulse.answer'))return toast('Você não possui permissão para responder ao Pulse.');if(!allowed.includes(feeling))return toast('Resposta do Pulse inválida.');if(['dificil','muito_dificil'].includes(feeling))return modal(`<div class="modal-head"><div><span class="eyebrow">Pulse</span><h3>Quer contar um pouco mais?</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><p class="muted">O comentário é opcional e será visível somente para você e para a Direção.</p><div class="field"><label>Comentário opcional</label><textarea id="pulseComment"></textarea></div><div class="section-actions"><button class="btn primary" onclick="App.savePulse('${feeling}')">Registrar</button></div>`,true);savePulse(feeling)}
async function savePulse(feeling){
  const allowed=['excelente','bem','normal','dificil','muito_dificil'];
  if(!can('pulse.answer'))return toast('Você não possui permissão para responder ao Pulse.');
  if(!allowed.includes(feeling))return toast('Resposta do Pulse inválida.');
  try{
    const payload={user_id:State.user.id,sector:State.user.sector,feeling,comment:$('#pulseComment')?.value.trim()||'',entry_date:todayISO()},{data,error}=await Supabase.from('pulse_entries').insert(payload).select().single();
    if(error){if(error.code==='23505')return toast('Você já respondeu ao Pulse hoje.');throw error}
    State.db.pulse.unshift(data);closeModal();renderPage();premiumToast('Obrigado por compartilhar como você está.');
  }catch(error){toast(friendlyError(error,'registro do Pulse'))}
}
async function syncAutomaticTasks(){if(State.user.role==='viewer')return;const existing=new Set((State.db.tasks||[]).filter(t=>t.user_id===State.user.id&&t.source_type!=='manual').map(t=>`${t.source_type}:${t.source_id}`)),items=[];State.db.reports.filter(r=>sectorAllowed(r.sector)).forEach(r=>{if(r.status==='adjust'&&State.user.role!=='direction')items.push({source_type:'report_adjust',source_id:r.id,title:`Ajustar relatório — ${SECTOR_LABELS[r.sector]}`,due_date:r.presentation,priority:'alta',sector:r.sector});if(['sent','review'].includes(r.status)&&State.user.role==='direction')items.push({source_type:'report_approval',source_id:r.id,title:`Analisar relatório — ${SECTOR_LABELS[r.sector]}`,due_date:r.presentation,priority:'alta',sector:r.sector})});State.db.actions.filter(actionVisible).filter(a=>!['done','cancelled'].includes(a.status)).forEach(a=>items.push({source_type:'action',source_id:a.id,title:a.title,due_date:a.deadline,priority:a.priority||'media',sector:a.sector}));State.db.meetings.filter(meetingVisible).filter(m=>m.status!=='done').forEach(m=>items.push({source_type:'meeting',source_id:m.id,title:`Café com Raphael — ${m.participant}`,due_date:m.date,priority:'media',sector:m.sector}));purpleIaRecommendations().slice(0,2).forEach(item=>items.push({source_type:'purple_ia',source_id:item.id,title:`Purple IA: ${item.title}`,due_date:item.dueDate||todayISO(),priority:item.priority,sector:item.sector==='integrado'?State.user.sector:item.sector}));for(const item of items.filter(x=>!existing.has(`${x.source_type}:${x.source_id}`))){const {data,error}=await Supabase.from('tasks').insert({...item,user_id:State.user.id,description:'Tarefa gerada automaticamente pelo Purple Gestão.'}).select().single();if(!error)State.db.tasks.unshift(data)}}
async function unlockAchievements(){if(State.user.role==='viewer')return;const own=State.db.reports.filter(r=>r.ownerId===State.user.id||r.owner===State.user.name),existing=new Set((State.db.achievements||[]).filter(a=>a.user_id===State.user.id).map(a=>a.code)),candidates=[];if(own.some(r=>r.status!=='draft'))candidates.push(['first_report','Primeiro relatório enviado']);if(own.some(r=>r.status==='approved'))candidates.push(['first_approved','Primeiro relatório aprovado']);const ontime=own.filter(r=>r.status==='approved'&&!r.adjustmentNote).length;if(ontime>=5)candidates.push(['five_ontime','Cinco relatórios sem atraso']);if(ontime>=10)candidates.push(['ten_ontime','Dez relatórios sem atraso']);const visibleActions=State.db.actions.filter(actionVisible),visibleMeetings=State.db.meetings.filter(meetingVisible);if(visibleActions.length&&!visibleActions.some(a=>!['done','cancelled'].includes(a.status)&&daysUntil(a.deadline)<0))candidates.push(['thirty_clear','30 dias sem pendências vencidas']);if(visibleMeetings.length&&visibleMeetings.every(m=>m.status==='done'))candidates.push(['meetings_complete','100% das reuniões realizadas']);if(visibleActions.length&&visibleActions.every(a=>a.status==='done'&&(!a.updatedAt||a.updatedAt.slice(0,10)<=a.deadline)))candidates.push(['actions_ontime','100% dos planos concluídos no prazo']);for(const [code,title] of candidates.filter(x=>!existing.has(x[0]))){const {data,error}=await Supabase.from('achievements').insert({user_id:State.user.id,code,title}).select().single();if(!error){State.db.achievements.unshift(data);setTimeout(()=>premiumToast(`Conquista desbloqueada: ${title}`),500)}}}
function premiumToast(message){toast(message);const t=$('#toast');t.classList.add('premium');setTimeout(()=>t.classList.remove('premium'),2600)}

function renderMural(){const list=(State.db.announcements||[]).filter(a=>!a.valid_until||a.valid_until>=todayISO()),mayCreate=can('mural.create'),mayEdit=can('mural.edit'),mayDelete=can('mural.delete');return `<div class="page"><div class="section-title"><div><h2>Mural Purple</h2><p>Comunicados importantes para manter todos na mesma direção.</p></div>${mayCreate?'<button class="btn primary" onclick="App.editAnnouncement()">Novo comunicado</button>':''}</div><div class="mural-grid">${list.map(a=>`<article class="announcement ${a.pinned?'pinned':''}"><div class="announcement-head"><span class="eyebrow">${a.pinned?'Fixado • ':''}${a.priority}</span><span>${fmtDate(a.published_at)}</span></div><h3>${escapeHTML(a.title)}</h3><p>${escapeHTML(a.message)}</p><footer>${a.sector==='all'?'Toda a Purple':SECTOR_LABELS[a.sector]}${mayEdit||mayDelete?`<div>${mayEdit?`<button class="btn ghost small" onclick="App.editAnnouncement('${a.id}')">Editar</button>`:''}${mayDelete?`<button class="btn danger small" onclick="App.deleteAnnouncement('${a.id}')">Remover</button>`:''}</div>`:''}</footer></article>`).join('')||'<div class="empty"><h3>Nenhum comunicado ativo</h3></div>'}</div></div>`}
function editAnnouncement(id=null){const a=id?(State.db.announcements||[]).find(x=>x.id===id):null;modal(`<div class="modal-head"><div><span class="eyebrow">Mural Purple</span><h3>${a?'Editar':'Novo'} comunicado</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="field"><label>Título</label><input id="announcementTitle" value="${escapeHTML(a?.title||'')}"/></div><div class="field"><label>Mensagem</label><textarea id="announcementMessage" class="large">${escapeHTML(a?.message||'')}</textarea></div><div class="form-grid cols-4"><div class="field"><label>Validade</label><input id="announcementUntil" type="date" value="${a?.valid_until||''}"/></div><div class="field"><label>Prioridade</label><select id="announcementPriority"><option value="alta" ${a?.priority==='alta'?'selected':''}>Alta</option><option value="normal" ${!a||a?.priority==='normal'?'selected':''}>Normal</option><option value="baixa" ${a?.priority==='baixa'?'selected':''}>Baixa</option></select></div><div class="field"><label>Público</label><select id="announcementAudience"><option value="all" ${!a||a?.audience==='all'?'selected':''}>Todos</option><option value="leaders" ${a?.audience==='leaders'?'selected':''}>Líderes</option><option value="direction" ${a?.audience==='direction'?'selected':''}>Direção</option></select></div><div class="field"><label>Setor</label><select id="announcementSector"><option value="all">Todos</option>${['retencao','pedagogico','financeiro'].map(s=>`<option value="${s}" ${a?.sector===s?'selected':''}>${SECTOR_LABELS[s]}</option>`).join('')}</select></div></div><label class="check-chip"><input id="announcementPinned" type="checkbox" ${a?.pinned?'checked':''}/> Fixar comunicado</label><div class="section-actions"><button class="btn primary" onclick="App.saveAnnouncement('${id||''}')">Salvar comunicado</button></div>`,true)}
async function saveAnnouncement(id){const permission=id?'mural.edit':'mural.create';if(!can(permission))return toast('Operação não autorizada.');const title=$('#announcementTitle').value.trim(),message=$('#announcementMessage').value.trim();if(!title||!message)return toast('Informe título e mensagem.');const payload={title,message,valid_until:$('#announcementUntil').value||null,priority:$('#announcementPriority').value,sector:$('#announcementSector').value,audience:$('#announcementAudience').value,pinned:$('#announcementPinned').checked};if(!id)Object.assign(payload,{created_by:State.user.id,published_at:todayISO()});const result=id?await Supabase.from('announcements').update(payload).eq('id',id).select().single():await Supabase.from('announcements').insert(payload).select().single();if(result.error)return toast(friendlyError(result.error,'salvamento do comunicado'));if(id)Object.assign(State.db.announcements.find(x=>x.id===id),result.data);else State.db.announcements.unshift(result.data);await logAudit(id?'Editou comunicado':'Publicou comunicado',`${result.data.title} • ${result.data.sector==='all'?'Toda a Purple':SECTOR_LABELS[result.data.sector]}`);closeModal();renderPage();premiumToast('Comunicado publicado no Mural Purple.')}
async function deleteAnnouncement(id){if(!can('mural.delete'))return toast('Exclusão não autorizada.');const announcement=State.db.announcements.find(x=>x.id===id);if(!announcement)return toast('Comunicado não encontrado.');if(!confirm('Remover este comunicado?'))return;const {error}=await Supabase.from('announcements').delete().eq('id',id);if(error)return toast(friendlyError(error,'exclusão do comunicado'));State.db.announcements=State.db.announcements.filter(x=>x.id!==id);await logAudit('Removeu comunicado',`${announcement.title} • ${announcement.sector==='all'?'Toda a Purple':SECTOR_LABELS[announcement.sector]}`);renderPage()}

function adminTab(tab){State.inventoryTab=tab;renderPage()}
function setAdminButtonLoading(button,loading){if(!button)return;button.disabled=loading;button.classList.toggle('loading',loading)}
async function finishAdministrationCommit(successMessage,refreshFailureMessage){
  closeModal();
  try{await refreshAdministration();renderPage();toast(successMessage)}
  catch(error){console.error('Purple Gestão — atualização após gravação:',error);toast(refreshFailureMessage)}
}
function adminTabs(){const tabs=[['overview','Visão Geral',can('inventory.view')||can('assets.view')],['books','Estoque de Livros',can('inventory.view')],['assets','Patrimônio',can('assets.view')],['movements','Movimentações',can('inventory.view')||can('assets.view')]],exportButton=State.inventoryTab==='assets'&&can('assets.export')?'<button class="btn ghost admin-export" onclick="App.exportAssetsCSV()">Exportar patrimônio</button>':'';return `<nav class="admin-tabs">${tabs.filter(x=>x[2]).map(x=>`<button class="${State.inventoryTab===x[0]?'active':''}" onclick="App.adminTab('${x[0]}')">${x[1]}</button>`).join('')}</nav>${exportButton}`}
function bookItems(){return (State.db.inventoryItems||[]).filter(x=>x.item_type==='book')}
function activeBooks(){return bookItems().filter(x=>x.active)}
function bookCodeBase(name){const normalized=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9 ]/g,' ').trim(),parts=normalized.split(/\s+/).filter(Boolean),numbers=parts.filter(x=>/^\d+$/.test(x)).join(''),words=parts.filter(x=>!/^\d+$/.test(x));if(!words.length)return '';return `${words.length===1?words[0].slice(0,3):words.map(x=>x[0]).join('').slice(0,4)}${numbers}`}
function uniqueBookCode(base,id=''){const used=new Set(bookItems().filter(x=>x.id!==id).map(x=>(x.internal_code||'').toUpperCase()));let code=base,n=2;while(used.has(code))code=`${base}-${n++}`;return code}
function updateBookCodeFromName(){const code=$('#bookCode');if(!code||code.dataset.manual==='true')return;code.value=uniqueBookCode(bookCodeBase($('#bookName').value),code.dataset.bookId||'')}
function markBookCodeEdited(){const code=$('#bookCode');code.value=code.value.toUpperCase().replace(/[^A-Z0-9-]/g,'');code.dataset.manual='true'}
function bookSelectOptions(options,current){const values=current&&!options.includes(current)?[current,...options]:options;return values.map(value=>`<option value="${escapeHTML(value)}" ${value===current?'selected':''}>${escapeHTML(value)}</option>`).join('')}
const INVENTORY_INTEGRITY_MIGRATION='20260722_inventory_assets_integrity.sql';
let pendingBookReturnIssues=[];
function inventoryIntegrityMigrationMissing(error,feature=''){
  const details=[error?.code,error?.message,error?.details,error?.hint].filter(Boolean).join(' ').toLowerCase(),expected=String(feature||'').toLowerCase();
  if(error?.code==='42703'&&details.includes('related_movement_id'))return true;
  if(['PGRST202','42883'].includes(error?.code)&&(!expected||details.includes(expected)))return true;
  return ['save_inventory_book','record_book_return','related_movement_id'].some(name=>details.includes(name))&&/(schema cache|could not find|does not exist|undefined column|function)/.test(details)
}
function inventoryIntegrityError(error,context,feature=''){
  if(inventoryIntegrityMigrationMissing(error,feature))return `Recurso indisponível. Aplique a migração ${INVENTORY_INTEGRITY_MIGRATION} e recarregue o sistema. Nenhuma alteração foi realizada.`;
  if(['22023','23514','42501','P0002'].includes(error?.code)&&error?.message)return error.message;
  return friendlyError(error,context)
}
async function saveInventoryBookLegacy({id,existing,code,name,collection,level,language,edition,minimum,targetQuantity,notes}){
  const payload={internal_code:code,name,category:'Material didático',collection,course:existing?.course||null,level,volume:existing?.volume||null,edition,language,minimum_quantity:minimum,location:existing?.location||null,unit_value:existing?.unit_value??null,notes};
  let item=existing;
  if(id){
    const result=await Supabase.from('inventory_items').update(payload).eq('id',id).eq('item_type','book').select().single();
    if(result.error)throw result.error;
    item=result.data
  }else{
    const result=await Supabase.from('inventory_items').insert({...payload,item_type:'book',current_quantity:0,active:true,created_by:State.user.id}).select().single();
    if(result.error)throw result.error;
    item=result.data
  }
  if(targetQuantity!==null){
    const delta=id?targetQuantity-Number(existing?.current_quantity||0):targetQuantity;
    if(delta){
      const movement=await Supabase.rpc('record_book_movement',{p_item_id:item.id,p_movement_type:id?'adjustment':'entry',p_quantity:delta,p_student_name:null,p_class_name:null,p_movement_date:todayISO(),p_supplier:null,p_document_number:null,p_unit_value:item.unit_value??null,p_notes:id?'Saldo atualizado no cadastro do livro.':'Estoque inicial informado no cadastro.'});
      if(movement.error)throw movement.error
    }
  }
  return item
}
const ASSET_MOVEMENT_DEFINITIONS=[
  {type:'transfer',label:'Transferência entre salas',permission:'assets.move'},
  {type:'assignment',label:'Atribuição a responsável',permission:'assets.assign'},
  {type:'return',label:'Devolução',permission:'assets.move'},
  {type:'maintenance_out',label:'Envio para manutenção',permission:'assets.maintenance'},
  {type:'maintenance_return',label:'Retorno da manutenção',permission:'assets.return'},
  {type:'loan',label:'Empréstimo',permission:'assets.move'},
  {type:'retirement',label:'Baixa patrimonial',permission:'assets.retire'},
  {type:'adjustment',label:'Ajuste cadastral',permission:'assets.move'}
];
function assetItems(){return State.db.assets||[]}
function authorizedAssetMovements(){return ASSET_MOVEMENT_DEFINITIONS.filter(definition=>can(definition.permission))}
function canOperateAssets(){return authorizedAssetMovements().length>0}
function assetAcceptsMovement(asset){return asset&&!['retired','inactive'].includes(asset.status)}
function renderAdministration(){if(!can('inventory.view')&&!can('assets.view'))return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;const allowed=State.inventoryTab==='assets'?can('assets.view'):State.inventoryTab==='books'?can('inventory.view'):true;if(!allowed)State.inventoryTab='overview';const views={overview:renderAdminOverview,books:renderBooks,assets:renderAssets,movements:renderAdminMovements};return `<div class="page inventory-page"><div class="section-title"><div><span class="eyebrow">Administrativo</span><h2>Estoque e Patrimônio</h2><p>Livros distribuíveis e bens rastreáveis em controles independentes.</p></div></div>${adminTabs()}${(views[State.inventoryTab]||renderAdminOverview)()}</div>`}
function renderAdminOverview(){const books=activeBooks(),assets=assetItems(),qty=books.reduce((s,x)=>s+Number(x.current_quantity||0),0),low=books.filter(x=>inventoryStatus(x).key==='low').length,out=books.filter(x=>inventoryStatus(x).key==='out').length,deliveries=(State.db.inventoryMovements||[]).filter(x=>x.movement_type==='issue').slice(0,5);return `<div class="admin-overview">${can('inventory.view')?`<section class="admin-module books-module"><div class="module-head"><div><span class="eyebrow">Distribuição didática</span><h3>Estoque de Livros</h3></div><button class="btn primary" onclick="App.adminTab('books')">Abrir Estoque de Livros</button></div><div class="mini-kpis"><div><b>${books.length}</b><span>Títulos ativos</span></div><div><b>${fmtNumber(qty)}</b><span>Exemplares</span></div><div><b>${low}</b><span>Estoque baixo</span></div><div><b>${out}</b><span>Esgotados</span></div></div><h4>Últimas entregas para alunos</h4>${deliveries.map(m=>`<div class="overview-row"><span>${escapeHTML(m.student_name||'Aluno não informado')}</span><b>${escapeHTML(m.item_name)} · ${Math.abs(Number(m.quantity_change))}</b></div>`).join('')||'<p class="helper">Nenhuma entrega registrada.</p>'}</section>`:''}${can('assets.view')?`<section class="admin-module assets-module"><div class="module-head"><div><span class="eyebrow">Bens rastreáveis</span><h3>Patrimônio</h3></div><button class="btn primary" onclick="App.adminTab('assets')">Abrir Patrimônio</button></div><div class="mini-kpis"><div><b>${assets.length}</b><span>Bens cadastrados</span></div><div><b>${assets.filter(x=>x.status==='in_use').length}</b><span>Em uso</span></div><div><b>${assets.filter(x=>x.status==='available').length}</b><span>Disponíveis</span></div><div><b>${assets.filter(x=>x.status==='maintenance').length}</b><span>Em manutenção</span></div><div><b>${assets.filter(x=>x.status==='retired').length}</b><span>Baixados</span></div></div></section>`:''}</div>`}
function inventoryStatus(item){if(Number(item.current_quantity)<=0)return {key:'out',label:'Esgotado'};if(Number(item.current_quantity)<=Number(item.minimum_quantity))return {key:'low',label:'Estoque Baixo'};return {key:'available',label:'Disponível'}}
function renderBooks(){const items=activeBooks(),movements=State.db.inventoryMovements||[],total=items.reduce((s,x)=>s+Number(x.current_quantity||0),0),low=items.filter(x=>inventoryStatus(x).key==='low').length,out=items.filter(x=>inventoryStatus(x).key==='out').length,value=items.reduce((s,x)=>s+Number(x.current_quantity||0)*Number(x.unit_value||0),0),period=new Date().toISOString().slice(0,7),issues=movements.filter(x=>x.movement_type==='issue'&&(x.movement_date||x.created_at).startsWith(period)).length;return `${!State.db.inventoryAvailable?migrationNotice('Estoque de Livros','20260717_inventory.sql e 20260718_books_assets.sql'):''}<div class="section-title compact"><div><h3>Estoque de Livros</h3><p>Livros, apostilas e materiais didáticos físicos.</p></div><div class="section-actions">${can('inventory.export')?'<button class="btn ghost" onclick="App.exportBooksCSV()">Exportar</button>':''}${can('inventory.entry')?'<button class="btn soft" onclick="App.openBookMovement(\'entry\')">Registrar entrada</button>':''}${can('inventory.issue')?'<button class="btn soft" onclick="App.openBookMovement(\'issue\')">Entregar livro ao aluno</button>':''}${can('inventory.return')?'<button class="btn soft" onclick="App.openBookMovement(\'return\')">Registrar devolução</button>':''}${can('inventory.create')?'<button class="btn primary" onclick="App.editBook()">Novo livro</button>':''}</div></div><section class="grid cols-4 inventory-kpis">${metricCard('Títulos ativos',items.length,'▣',0,'Somente livros')}${metricCard('Total de exemplares',total,'▤',0,'Quantidade disponível')}${metricCard('Estoque baixo',low,'!',0,'Abaixo ou igual ao mínimo')}${metricCard('Esgotados',out,'○',0,'Sem unidades')}${metricCard('Valor estimado',fmtMoney(value),'R$',0,'Quando informado')}${metricCard('Entregas no período',issues,'↗',0,'Mês atual')}</section><section class="panel inventory-panel"><div class="inventory-toolbar"><input id="inventorySearch" class="search" placeholder="Pesquisar nome, código ou coleção" oninput="App.applyBookFilters()"/><select id="inventoryCourse" class="select" onchange="App.applyBookFilters()"><option value="all">Todos os cursos</option>${inventoryOptions(items,'course')}</select><select id="inventoryCollection" class="select" onchange="App.applyBookFilters()"><option value="all">Todas as coleções</option>${inventoryOptions(items,'collection')}</select><select id="inventoryLevel" class="select" onchange="App.applyBookFilters()"><option value="all">Todos os níveis</option>${inventoryOptions(items,'level')}</select><select id="inventoryAvailability" class="select" onchange="App.applyBookFilters()"><option value="all">Toda disponibilidade</option><option value="available">Disponível</option><option value="low">Estoque baixo</option><option value="out">Esgotado</option></select></div><div id="inventoryTable"></div></section><section class="panel inventory-history"><div class="panel-head"><div><span class="eyebrow">Análise</span><h3>Livros mais retirados e últimas movimentações</h3></div></div>${renderMostIssuedBooks()}${renderBookHistory(12)}</section>`}
function migrationNotice(name,files){return `<div class="alert yellow inventory-migration"><div class="alert-icon">!</div><div><b>${name} aguardando migração</b><span>Aplique, nesta ordem, ${files}. Nenhuma migração é executada automaticamente.</span></div></div>`}
function applyBookFilters(){const target=$('#inventoryTable');if(!target)return;const q=($('#inventorySearch')?.value||'').toLowerCase(),course=$('#inventoryCourse')?.value||'all',collection=$('#inventoryCollection')?.value||'all',level=$('#inventoryLevel')?.value||'all',availability=$('#inventoryAvailability')?.value||'all';const items=activeBooks().filter(x=>(!q||`${x.name} ${x.internal_code||''} ${x.collection||''}`.toLowerCase().includes(q))&&(course==='all'||x.course===course)&&(collection==='all'||x.collection===collection)&&(level==='all'||x.level===level)&&(availability==='all'||inventoryStatus(x).key===availability));target.innerHTML=`<div class="table-wrap"><table class="inventory-table"><thead><tr><th>Livro</th><th>Coleção / Curso</th><th>Nível / Volume</th><th>Disponível</th><th>Status</th><th>Ações</th></tr></thead><tbody>${items.map(item=>{const s=inventoryStatus(item),hasMoves=(State.db.inventoryMovements||[]).some(m=>m.item_id===item.id);return `<tr><td><b>${escapeHTML(item.name)}</b><small>${escapeHTML(item.internal_code||'Sem código')} · ${escapeHTML(item.language||'Idioma não informado')}</small></td><td>${escapeHTML(item.collection||'—')}<small>${escapeHTML(item.course||'—')}</small></td><td>${escapeHTML(item.level||'—')}<small>${escapeHTML(item.volume||item.edition||'—')}</small></td><td><b>${fmtNumber(item.current_quantity)}</b><small>Mínimo: ${fmtNumber(item.minimum_quantity)}</small></td><td><span class="stock-status ${s.key}">${s.label}</span></td><td><div class="table-actions">${can('inventory.edit')?`<button class="btn ghost small" onclick="App.editBook('${item.id}')">Editar</button>`:''}${can('inventory.adjust')?`<button class="btn soft small" onclick="App.openBookMovement('adjustment','${item.id}')">Ajustar</button>`:''}${can('inventory.inactivate')?`<button class="btn danger small" onclick="App.inactivateBook('${item.id}',this)">Inativar</button>`:''}${can('inventory.inactivate')&&!hasMoves?`<button class="btn ghost small" onclick="App.deleteUnmovedBook('${item.id}',this)">Excluir cadastro</button>`:''}</div></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty"><p>Nenhum livro encontrado.</p></div></td></tr>'}</tbody></table></div>`}
function renderBookHistory(limit=250){const labels={entry:'Entrada',issue:'Entrega ao aluno',return:'Devolução',adjustment:'Ajuste compensatório'};return `<div class="table-wrap"><table><thead><tr><th>Data</th><th>Livro</th><th>Operação</th><th>Quantidade</th><th>Aluno / Usuário</th></tr></thead><tbody>${(State.db.inventoryMovements||[]).slice(0,limit).map(m=>`<tr><td>${fmtDate(m.movement_date||m.created_at)}<small>${fmtDateTime(m.created_at)}</small></td><td>${escapeHTML(m.item_name)}</td><td>${labels[m.movement_type]||m.movement_type}</td><td class="movement-qty ${Number(m.quantity_change)>=0?'positive':'negative'}">${Number(m.quantity_change)>0?'+':''}${fmtNumber(m.quantity_change)}</td><td>${escapeHTML(m.student_name||m.responsible_name||'—')}<small>${escapeHTML(m.class_name||m.supplier||'')}</small></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty"><p>Nenhuma movimentação registrada.</p></div></td></tr>'}</tbody></table></div>`}
function renderMostIssuedBooks(){const totals={};(State.db.inventoryMovements||[]).filter(x=>x.movement_type==='issue').forEach(x=>totals[x.item_name]=(totals[x.item_name]||0)+Math.abs(Number(x.quantity_change)));const rows=Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,5);return rows.length?`<div class="ranking-list">${rows.map(([name,total],i)=>`<div><span>${i+1}</span><b>${escapeHTML(name)}</b><strong>${fmtNumber(total)} retirados</strong></div>`).join('')}</div>`:''}
function editBook(id=''){if(!can(id?'inventory.edit':'inventory.create'))return toast('Operação não autorizada.');if(!State.db.inventoryAvailable)return toast('Aplique as migrações do Estoque antes do cadastro.');const x=id?bookItems().find(i=>i.id===id):null,collections=['Little Learners','Super Kids','Young Learners','Purple Way','Experiences'],languages=['Inglês','Espanhol','Outro'],editions=['1ª edição','2ª edição'],canChangeStock=id?can('inventory.adjust'):can('inventory.entry'),originalQuantity=Number(x?.current_quantity||0);modal(`<div class="modal-head"><div><span class="eyebrow">Estoque de Livros</span><h3>${x?'Editar livro':'Novo livro'}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3"><div class="field"><label>Código interno</label><input id="bookCode" data-book-id="${id}" data-manual="${x?'true':'false'}" value="${escapeHTML(x?.internal_code||'')}" oninput="App.markBookCodeEdited()"/></div><div class="field"><label>Nome do livro</label><input id="bookName" value="${escapeHTML(x?.name||'')}" oninput="App.updateBookCodeFromName()" onblur="App.updateBookCodeFromName()"/></div><div class="field"><label>Coleção</label><select id="bookCollection"><option value="">Selecione</option>${bookSelectOptions(collections,x?.collection||'')}</select></div><div class="field"><label>Nível</label><input id="bookLevel" value="${escapeHTML(x?.level||'')}"/></div><div class="field"><label>Idioma</label><select id="bookLanguage"><option value="">Selecione</option>${bookSelectOptions(languages,x?.language||'')}</select></div><div class="field"><label>Edição</label><select id="bookEdition"><option value="">Selecione</option>${bookSelectOptions(editions,x?.edition||'')}</select></div><div class="field"><label>Quantidade mínima</label><input id="bookMinimum" type="number" min="0" step="1" value="${Number(x?.minimum_quantity||0)}"/></div><div class="field"><label>${id?'Estoque atual':'Estoque inicial'}</label><input id="bookCurrentQuantity" type="number" min="0" step="1" data-original-quantity="${originalQuantity}" value="${originalQuantity}" ${canChangeStock?'':'disabled'}/><small>${canChangeStock?'Alterações de saldo geram uma movimentação auditada.':'Permissão de movimentação necessária para alterar o saldo.'}</small></div><div class="field"><label>Status</label><input value="${x?.active===false?'Inativo':'Ativo'}" disabled/><small>A inativação usa uma permissão operacional separada.</small></div></div><div class="field"><label>Observações</label><textarea id="bookNotes">${escapeHTML(x?.notes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveBook('${id}',this)">Salvar livro</button></div>`,true)}
async function saveBook(id='',button=null){
  if(!can(id?'inventory.edit':'inventory.create'))return toast('Operação não autorizada.');
  const existing=id?bookItems().find(x=>x.id===id):null,name=$('#bookName').value.trim(),code=$('#bookCode').value.trim().toUpperCase(),collection=$('#bookCollection').value,level=$('#bookLevel').value.trim(),language=$('#bookLanguage').value,edition=$('#bookEdition').value,minimumInput=$('#bookMinimum'),minimum=Number(minimumInput.value),canChangeStock=id?can('inventory.adjust'):can('inventory.entry'),quantityInput=$('#bookCurrentQuantity'),quantityValue=Number(quantityInput.value),quantityChanged=!id||quantityValue!==Number(quantityInput.dataset.originalQuantity),targetQuantity=canChangeStock&&quantityChanged?quantityValue:null;
  if(id&&!existing)return toast('Livro não encontrado.');
  if(!code||!name||!collection||!level||!language||!edition||!minimumInput.value.trim()||!Number.isInteger(minimum)||minimum<0||targetQuantity!==null&&(!quantityInput.value.trim()||!Number.isInteger(targetQuantity)||targetQuantity<0))return toast('Preencha corretamente todos os campos obrigatórios.');
  if(bookItems().some(x=>x.id!==id&&(x.internal_code||'').toUpperCase()===code))return toast('Já existe um livro com este código interno.');
  setAdminButtonLoading(button,true);
  try{
    const {error}=await Supabase.rpc('save_inventory_book',{p_item_id:id||null,p_internal_code:code,p_name:name,p_category:'Material didático',p_collection:collection,p_course:existing?.course||null,p_level:level,p_volume:existing?.volume||null,p_edition:edition,p_language:language,p_minimum_quantity:minimum,p_target_quantity:targetQuantity,p_location:existing?.location||null,p_unit_value:existing?.unit_value??null,p_notes:$('#bookNotes').value.trim(),p_active:existing?.active??true});
    if(error)throw error;
    await finishAdministrationCommit(id?'Livro atualizado.':'Livro cadastrado com estoque inicial.','Livro salvo, mas não foi possível atualizar a tela. Recarregue para ver o estado confirmado.');
  }catch(error){
    if(inventoryIntegrityMigrationMissing(error,'save_inventory_book')){
      try{
        await saveInventoryBookLegacy({id,existing,code,name,collection,level,language,edition,minimum,targetQuantity,notes:$('#bookNotes').value.trim()});
        await finishAdministrationCommit(id?'Livro atualizado.':'Livro cadastrado com estoque inicial.','Livro salvo, mas não foi possível atualizar a tela. Recarregue para ver o estado confirmado.');
      }catch(legacyError){toast(legacyError.code==='23505'?'Já existe um livro com este código interno.':friendlyError(legacyError,'salvamento do livro'))}
    }else toast(error.code==='23505'?'Já existe um livro com este código interno.':inventoryIntegrityError(error,'salvamento do livro','save_inventory_book'))
  }
  finally{setAdminButtonLoading(button,false)}
}
async function inactivateBook(id,button=null){if(!can('inventory.inactivate'))return toast('Operação não autorizada.');if(!confirm('Inativar este livro? Todo o histórico será preservado.'))return;setAdminButtonLoading(button,true);try{const {error}=await Supabase.rpc('inactivate_inventory_item',{p_item_id:id});if(error)throw error;await refreshAdministration();renderPage();toast('Livro inativado. Histórico preservado.')}catch(error){toast(friendlyError(error,'inativação do livro'))}finally{setAdminButtonLoading(button,false)}}
async function deleteUnmovedBook(id,button=null){if(!can('inventory.inactivate'))return toast('Operação não autorizada.');if(!confirm('Excluir definitivamente este cadastro sem movimentações? Esta ação não pode ser desfeita.'))return;setAdminButtonLoading(button,true);try{const {error}=await Supabase.rpc('delete_unmoved_book',{p_item_id:id});if(error)throw error;await refreshAdministration();renderPage();toast('Cadastro sem movimentações excluído.')}catch(error){toast(friendlyError(error,'exclusão do livro'))}finally{setAdminButtonLoading(button,false)}}
async function loadPendingBookReturnIssues(){
  const rows=[],pageSize=1000,columns='id,item_id,item_name,movement_type,quantity_change,student_name,class_name,movement_date,created_at,related_movement_id';
  for(let from=0;;from+=pageSize){
    const {data,error}=await Supabase.from('book_movements').select(columns).in('movement_type',['issue','return']).order('created_at',{ascending:false}).order('id',{ascending:false}).range(from,from+pageSize-1);
    if(error)throw error;
    const batch=data||[];rows.push(...batch);
    if(batch.length<pageSize)break
  }
  const returnedByIssue=new Map(),legacyReturnKeys=new Set(),studentKey=value=>String(value||'').trim().toLocaleLowerCase('pt-BR'),movementKey=movement=>`${movement.item_id}::${studentKey(movement.student_name)}`;
  rows.filter(row=>row.movement_type==='return').forEach(row=>{if(row.related_movement_id)returnedByIssue.set(row.related_movement_id,(returnedByIssue.get(row.related_movement_id)||0)+Math.max(0,Number(row.quantity_change)||0));else legacyReturnKeys.add(movementKey(row))});
  let blocked=0;
  const activeIds=new Set(activeBooks().map(book=>book.id)),issues=rows.filter(row=>row.movement_type==='issue'&&activeIds.has(row.item_id)).map(row=>({...row,remaining:Math.max(0,Math.abs(Number(row.quantity_change)||0)-(returnedByIssue.get(row.id)||0))})).filter(row=>{if(row.remaining<=0)return false;if(legacyReturnKeys.has(movementKey(row))){blocked++;return false}return true});
  return {issues,blocked}
}
function updateBookReturnFields(){
  const issue=pendingBookReturnIssues.find(row=>row.id===$('#bookReturnIssue')?.value);
  if(!issue)return;
  const book=$('#bookReturnBook'),student=$('#bookReturnStudent'),balance=$('#bookReturnBalance'),quantity=$('#bookMovementQuantity');
  if(book)book.value=issue.item_name||bookItems().find(item=>item.id===issue.item_id)?.name||'';
  if(student)student.value=[issue.student_name,issue.class_name].filter(Boolean).join(' — ');
  if(balance)balance.value=`${issue.remaining} de ${Math.abs(Number(issue.quantity_change)||0)} exemplar(es)`;
  if(quantity){quantity.max=String(issue.remaining);const current=Number(quantity.value);if(!Number.isInteger(current)||current<1||current>issue.remaining)quantity.value='1'}
}
async function openBookMovement(type,itemId=''){
  const permission={entry:'inventory.entry',issue:'inventory.issue',return:'inventory.return',adjustment:'inventory.adjust'}[type];
  if(!permission||!can(permission))return toast('Operação não autorizada.');
  if(!State.db.inventoryAvailable)return toast('Aplique as migrações antes de registrar movimentações.');
  if(type==='return'){
    try{
      const {issues,blocked}=await loadPendingBookReturnIssues();
      if(!issues.length)return toast(blocked?'As entregas pendentes possuem devoluções históricas sem vínculo. Revise o histórico antes de continuar.':'Nenhuma entrega com saldo pendente foi encontrada.');
      pendingBookReturnIssues=issues;
      modal(`<div class="modal-head"><div><span class="eyebrow">Movimentação de livros</span><h3>Registrar devolução</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div>${blocked?'<div class="alert yellow"><div class="alert-icon">!</div><div><b>Histórico que exige revisão</b><span>Algumas entregas não aparecem porque possuem devoluções antigas sem vínculo.</span></div></div>':''}<div class="field"><label>Entrega original</label><select id="bookReturnIssue" onchange="App.updateBookReturnFields()">${issues.map(issue=>`<option value="${escapeHTML(issue.id)}">${escapeHTML(issue.item_name)} — ${escapeHTML(issue.student_name)} · ${fmtDate(issue.movement_date||issue.created_at)} · ${issue.remaining} pendente(s)</option>`).join('')}</select><small>A devolução ficará vinculada a esta entrega.</small></div><div class="form-grid cols-3"><div class="field"><label>Livro</label><input id="bookReturnBook" disabled/></div><div class="field"><label>Aluno / turma</label><input id="bookReturnStudent" disabled/></div><div class="field"><label>Saldo da entrega</label><input id="bookReturnBalance" disabled/></div></div><div class="form-grid cols-2"><div class="field"><label>Quantidade</label><input id="bookMovementQuantity" type="number" min="1" step="1" value="1"/></div><div class="field"><label>Data</label><input id="bookMovementDate" type="date" value="${todayISO()}"/></div></div><div class="field"><label>Responsável pelo registro</label><input value="${escapeHTML(State.user.name)}" disabled/></div><div class="field"><label>Observações</label><textarea id="bookMovementNotes"></textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveBookMovement('return',this)">Confirmar devolução</button></div>`,true);
      updateBookReturnFields()
    }catch(error){toast(inventoryIntegrityError(error,'consulta de entregas pendentes','related_movement_id'))}
    return
  }
  pendingBookReturnIssues=[];
  const items=activeBooks(),x=items.find(i=>i.id===itemId),titles={entry:'Registrar entrada',issue:'Entregar livro ao aluno',adjustment:'Ajuste manual de saldo'};
  modal(`<div class="modal-head"><div><span class="eyebrow">Movimentação de livros</span><h3>${titles[type]}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="field"><label>Livro</label><select id="bookMovementItem" ${itemId?'disabled':''}>${items.map(i=>`<option value="${i.id}" ${i.id===itemId?'selected':''}>${escapeHTML(i.name)} — ${i.current_quantity} disponíveis</option>`).join('')}</select></div>${type==='issue'?'<div class="form-grid cols-2"><div class="field"><label>Aluno</label><input id="bookMovementStudent" placeholder="Buscar aluno pelo nome"/></div><div class="field"><label>Turma (opcional)</label><input id="bookMovementClass"/></div></div>':''}<div class="form-grid cols-2"><div class="field"><label>${type==='adjustment'?'Novo saldo':'Quantidade'}</label><input id="bookMovementQuantity" type="number" min="${type==='adjustment'?0:1}" step="1" value="${type==='adjustment'?Number(x?.current_quantity||0):1}"/></div><div class="field"><label>Data</label><input id="bookMovementDate" type="date" value="${todayISO()}"/></div></div>${type==='entry'?'<div class="form-grid cols-3"><div class="field"><label>Fornecedor (opcional)</label><input id="bookMovementSupplier"/></div><div class="field"><label>Nota ou documento (opcional)</label><input id="bookMovementDocument"/></div><div class="field"><label>Valor unitário (opcional)</label><input id="bookMovementValue" type="number" min="0" step="0.01"/></div></div>':''}<div class="field"><label>Responsável pelo registro</label><input value="${escapeHTML(State.user.name)}" disabled/></div><div class="field"><label>Observações</label><textarea id="bookMovementNotes"></textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveBookMovement('${type}',this)">Confirmar</button></div>`,true)
}
async function saveBookMovement(type,button=null){
  const permission={entry:'inventory.entry',issue:'inventory.issue',return:'inventory.return',adjustment:'inventory.adjust'}[type];
  if(!permission||!can(permission))return toast('Operação não autorizada.');
  const value=Number($('#bookMovementQuantity')?.value),date=$('#bookMovementDate')?.value,notes=$('#bookMovementNotes')?.value.trim()||null;
  if(!Number.isInteger(value)||value<0||type!=='adjustment'&&value<=0)return toast('Informe uma quantidade inteira válida.');
  if(!date)return toast('Informe a data da movimentação.');
  if(type==='return'){
    const issue=pendingBookReturnIssues.find(row=>row.id===$('#bookReturnIssue')?.value);
    if(!issue)return toast('Selecione a entrega original.');
    if(value>issue.remaining)return toast(`A quantidade excede o saldo pendente desta entrega (${issue.remaining}).`);
    setAdminButtonLoading(button,true);
    try{
      const {error}=await Supabase.rpc('record_book_return',{p_item_id:issue.item_id,p_issue_id:issue.id,p_quantity:value,p_movement_date:date,p_notes:notes});
      if(error)throw error;
      pendingBookReturnIssues=[];
      await finishAdministrationCommit('Devolução registrada e vinculada à entrega original.','Devolução registrada, mas não foi possível atualizar a tela. Recarregue para ver o novo saldo.');
    }catch(error){toast(inventoryIntegrityError(error,'devolução do livro','record_book_return'))}
    finally{setAdminButtonLoading(button,false)}
    return
  }
  const id=$('#bookMovementItem')?.value,item=bookItems().find(x=>x.id===id),student=$('#bookMovementStudent')?.value.trim()||null;
  if(!item)return toast('Selecione um livro ativo.');
  if(type==='issue'&&!student)return toast('Informe o aluno.');
  const quantity=type==='adjustment'?value-Number(item.current_quantity):value;
  if(type==='adjustment'&&!quantity)return toast('O saldo informado já é o atual.');
  setAdminButtonLoading(button,true);
  try{
    const {error}=await Supabase.rpc('record_book_movement',{p_item_id:id,p_movement_type:type,p_quantity:quantity,p_student_name:student,p_class_name:$('#bookMovementClass')?.value.trim()||null,p_movement_date:date,p_supplier:$('#bookMovementSupplier')?.value.trim()||null,p_document_number:$('#bookMovementDocument')?.value.trim()||null,p_unit_value:Number($('#bookMovementValue')?.value||0)||null,p_notes:notes});
    if(error)throw error;
    await finishAdministrationCommit('Movimentação registrada e saldo atualizado.','Movimentação registrada, mas não foi possível atualizar a tela. Recarregue para ver o novo saldo.');
  }catch(error){toast(friendlyError(error,'movimentação do livro'))}
  finally{setAdminButtonLoading(button,false)}
}
function assetStatusLabel(status){return {available:'Disponível',in_use:'Em uso',maintenance:'Em manutenção',loaned:'Emprestado',inactive:'Inativo',retired:'Baixado'}[status]||status}
function renderAssets(){const items=assetItems(),value=items.reduce((s,x)=>s+Number(x.acquisition_value||0)*Number(x.quantity||1),0);return `${!State.db.assetsAvailable?migrationNotice('Patrimônio','20260718_books_assets.sql'):''}<div class="section-title compact"><div><h3>Patrimônio</h3><p>Bens físicos rastreados individualmente, sem relação com o saldo de livros.</p></div><div class="section-actions">${canOperateAssets()?'<button class="btn soft" onclick="App.openAssetMovement()">Nova movimentação</button>':''}${can('assets.create')?'<button class="btn primary" onclick="App.editAsset()">Novo bem</button>':''}</div></div><section class="grid cols-4 inventory-kpis">${metricCard('Total de bens',items.length,'◇',0,'Cadastros patrimoniais')}${metricCard('Valor estimado',fmtMoney(value),'R$',0,'Valor de aquisição')}${metricCard('Disponíveis',items.filter(x=>x.status==='available').length,'✓',0,'Prontos para uso')}${metricCard('Em uso',items.filter(x=>x.status==='in_use').length,'●',0,'Atribuídos')}${metricCard('Em manutenção',items.filter(x=>x.status==='maintenance').length,'⚙',0,'Em reparo')}${metricCard('Emprestados',items.filter(x=>x.status==='loaned').length,'↗',0,'Fora temporariamente')}</section><section class="panel inventory-panel"><div class="inventory-toolbar asset-toolbar"><input id="assetSearch" class="search" placeholder="Pesquisar bem, código, marca ou responsável" oninput="App.applyAssetFilters()"/><select id="assetCategory" class="select" onchange="App.applyAssetFilters()"><option value="all">Todas as categorias</option>${inventoryOptions(items,'category')}</select><select id="assetRoom" class="select" onchange="App.applyAssetFilters()"><option value="all">Todas as salas</option>${inventoryOptions(items,'location')}</select><select id="assetStatus" class="select" onchange="App.applyAssetFilters()"><option value="all">Todos os status</option>${['available','in_use','maintenance','loaned','inactive','retired'].map(s=>`<option value="${s}">${assetStatusLabel(s)}</option>`).join('')}</select></div><div id="assetsTable"></div></section><section class="panel inventory-history"><div class="panel-head"><div><span class="eyebrow">Patrimônio</span><h3>Últimas movimentações patrimoniais</h3></div></div>${renderAssetHistory(12)}</section>`}
function applyAssetFilters(){const target=$('#assetsTable');if(!target)return;const q=($('#assetSearch')?.value||'').toLowerCase(),category=$('#assetCategory')?.value||'all',room=$('#assetRoom')?.value||'all',status=$('#assetStatus')?.value||'all';const items=assetItems().filter(x=>(!q||`${x.name} ${x.asset_code} ${x.brand||''} ${x.current_responsible||''}`.toLowerCase().includes(q))&&(category==='all'||x.category===category)&&(room==='all'||x.location===room)&&(status==='all'||x.status===status));target.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Bem</th><th>Categoria</th><th>Sala / Responsável</th><th>Conservação</th><th>Status</th><th>Ações</th></tr></thead><tbody>${items.map(x=>`<tr><td><b>${escapeHTML(x.name)}</b><small>${escapeHTML(x.asset_code)} · ${escapeHTML([x.brand,x.model].filter(Boolean).join(' ')||'Sem marca/modelo')}</small></td><td>${escapeHTML(x.category)}</td><td>${escapeHTML(x.location||'—')}<small>${escapeHTML(x.current_responsible||'Sem responsável')}</small></td><td>${escapeHTML({new:'Novo',excellent:'Ótimo',good:'Bom',fair:'Regular',poor:'Ruim'}[x.condition]||x.condition)}</td><td><span class="asset-status ${x.status}">${assetStatusLabel(x.status)}</span></td><td><div class="table-actions">${can('assets.edit')?`<button class="btn ghost small" onclick="App.editAsset('${x.id}')">Editar</button>`:''}${canOperateAssets()&&assetAcceptsMovement(x)?`<button class="btn soft small" onclick="App.openAssetMovement('${x.id}')">Movimentar</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><p>Nenhum bem encontrado.</p></div></td></tr>'}</tbody></table></div>`}
function renderAssetHistory(limit=250){return `<div class="table-wrap"><table><thead><tr><th>Data</th><th>Bem</th><th>Movimentação</th><th>Origem → Destino</th><th>Responsável</th><th>Usuário</th></tr></thead><tbody>${(State.db.assetMovements||[]).slice(0,limit).map(m=>`<tr><td>${fmtDate(m.movement_date)}</td><td>${escapeHTML(m.asset_name)}</td><td>${escapeHTML({transfer:'Transferência',assignment:'Atribuição',return:'Devolução',maintenance_out:'Envio para manutenção',maintenance_return:'Retorno da manutenção',loan:'Empréstimo',retirement:'Baixa patrimonial',adjustment:'Ajuste cadastral'}[m.movement_type]||m.movement_type)}</td><td>${escapeHTML(m.origin||'—')} → ${escapeHTML(m.destination||'—')}</td><td>${escapeHTML(m.new_responsible||m.previous_responsible||'—')}</td><td>${escapeHTML(m.performed_by_name||'—')}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><p>Nenhuma movimentação patrimonial.</p></div></td></tr>'}</tbody></table></div>`}
function editAsset(id=''){if(!can(id?'assets.edit':'assets.create'))return toast('Operação não autorizada.');if(!State.db.assetsAvailable)return toast('Aplique a migração de Patrimônio antes do cadastro.');const x=id?assetItems().find(i=>i.id===id):null,canSetLocation=!x&&can('assets.move'),canSetResponsible=!x&&can('assets.assign');const fields=[['assetCode','Código patrimonial',x?.asset_code],['assetName','Nome do bem',x?.name],['assetCategoryEdit','Categoria',x?.category],['assetBrand','Marca',x?.brand],['assetModel','Modelo',x?.model],['assetSerial','Número de série',x?.serial_number],['assetSupplier','Fornecedor',x?.supplier]];modal(`<div class="modal-head"><div><span class="eyebrow">Patrimônio</span><h3>${x?'Editar bem':'Novo bem'}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-3">${fields.map(f=>`<div class="field"><label>${f[1]}</label><input id="${f[0]}" value="${escapeHTML(f[2]||'')}"/></div>`).join('')}<div class="field"><label>Unidade ou sala</label><input id="assetLocation" value="${escapeHTML(x?.location||'')}" ${canSetLocation?'':'disabled'}/><small>${x?'Altere por movimentação patrimonial.':canSetLocation?'Será registrada como movimentação inicial.':'Permissão de movimentação necessária.'}</small></div><div class="field"><label>Responsável atual</label><input id="assetResponsible" value="${escapeHTML(x?.current_responsible||'')}" ${canSetResponsible?'':'disabled'}/><small>${x?'Altere por movimentação patrimonial.':canSetResponsible?'Será registrado por atribuição auditada.':'Permissão de atribuição necessária.'}</small></div><div class="field"><label>Quantidade</label><input id="assetQuantity" type="number" min="1" value="${Number(x?.quantity||1)}"/></div><div class="field"><label>Data de aquisição</label><input id="assetAcquired" type="date" value="${x?.acquisition_date||''}"/></div><div class="field"><label>Valor de aquisição</label><input id="assetValue" type="number" min="0" step="0.01" value="${Number(x?.acquisition_value||0)}"/></div><div class="field"><label>Estado de conservação</label><select id="assetCondition">${[['new','Novo'],['excellent','Ótimo'],['good','Bom'],['fair','Regular'],['poor','Ruim']].map(o=>`<option value="${o[0]}" ${x?.condition===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div><div class="field"><label>Status</label><input id="assetStatusEdit" value="${assetStatusLabel(x?.status||'available')}" disabled/><small>${x?'Altere por movimentação patrimonial.':'Todo novo bem nasce disponível e ativo.'}</small></div></div><div class="field"><label>Observações</label><textarea id="assetNotes">${escapeHTML(x?.notes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveAsset('${id}',this)">Salvar bem</button></div>`,true)}
async function saveAsset(id='',button=null){
  if(!can(id?'assets.edit':'assets.create'))return toast('Operação não autorizada.');
  const name=$('#assetName').value.trim(),code=$('#assetCode').value.trim(),category=$('#assetCategoryEdit').value.trim();
  if(!name||!code||!category)return toast('Informe código, nome e categoria.');
  const payload={asset_code:code,name,category,brand:$('#assetBrand').value.trim()||null,model:$('#assetModel').value.trim()||null,serial_number:$('#assetSerial').value.trim()||null,quantity:Math.max(1,Number($('#assetQuantity').value||1)),acquisition_date:$('#assetAcquired').value||null,acquisition_value:Number($('#assetValue').value||0)||null,supplier:$('#assetSupplier').value.trim()||null,condition:$('#assetCondition').value,notes:$('#assetNotes').value.trim()},initialLocation=!id&&can('assets.move')?$('#assetLocation').value.trim()||null:null,initialResponsible=!id&&can('assets.assign')?$('#assetResponsible').value.trim()||null:null;
  setAdminButtonLoading(button,true);
  try{
    const result=id?await Supabase.from('assets').update(payload).eq('id',id).select().single():await Supabase.from('assets').insert({...payload,location:null,current_responsible:null,status:'available',created_by:State.user.id}).select().single();
    if(result.error)throw result.error;
    if(!id&&(initialResponsible||initialLocation)){
      const type=initialResponsible?'assignment':'transfer';
      const movement=await Supabase.rpc('record_asset_movement',{p_asset_id:result.data.id,p_movement_type:type,p_origin:null,p_destination:initialLocation,p_previous_responsible:null,p_new_responsible:initialResponsible,p_movement_date:todayISO(),p_notes:'Alocação inicial registrada no cadastro do bem.'});
      if(movement.error){await refreshAdministration();closeModal();renderPage();return toast(`Bem criado como disponível, mas a movimentação inicial falhou: ${movement.error.message}`)}
    }
    await refreshAdministration();
    closeModal();renderPage();toast(id?'Bem atualizado.':'Bem cadastrado.');
  }catch(error){toast(friendlyError(error,'salvamento do patrimônio'))}
  finally{setAdminButtonLoading(button,false)}
}
function openAssetMovement(id=''){
  if(!State.db.assetsAvailable)return toast('Aplique a migração de Patrimônio.');
  const operations=authorizedAssetMovements();
  if(!operations.length)return toast('Você não possui permissão para movimentações patrimoniais.');
  const selected=id?assetItems().find(x=>x.id===id):null;
  if(id&&!selected)return toast('Bem patrimonial não encontrado.');
  if(selected&&!assetAcceptsMovement(selected))return toast('Bens baixados ou inativos não podem ser movimentados.');
  const items=assetItems().filter(assetAcceptsMovement);
  if(!items.length)return toast('Não há bens ativos disponíveis para movimentação.');
  modal(`<div class="modal-head"><div><span class="eyebrow">Patrimônio</span><h3>Nova movimentação</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="field"><label>Bem</label><select id="assetMovementItem" onchange="App.updateAssetMovementFields()">${items.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${escapeHTML(x.asset_code)} — ${escapeHTML(x.name)}</option>`).join('')}</select></div><div class="field"><label>Tipo de movimentação</label><select id="assetMovementType" onchange="App.updateAssetMovementFields()">${operations.map(operation=>`<option value="${operation.type}">${operation.label}</option>`).join('')}</select></div><div class="form-grid cols-2"><div class="field"><label>Origem</label><input id="assetMovementOrigin" disabled/><small>Preenchida pelo estado atual do bem.</small></div><div class="field"><label>Destino</label><input id="assetMovementDestination"/></div><div class="field"><label>Responsável anterior</label><input id="assetMovementPrevious" disabled/><small>Preenchido pelo estado atual do bem.</small></div><div class="field"><label>Novo responsável</label><input id="assetMovementNew"/></div><div class="field"><label>Data</label><input id="assetMovementDate" type="date" value="${todayISO()}"/></div></div><div class="field"><label>Observação</label><textarea id="assetMovementNotes"></textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveAssetMovement(this)">Registrar movimentação</button></div>`,true);
  updateAssetMovementFields()
}
function updateAssetMovementFields(){const type=$('#assetMovementType')?.value,asset=assetItems().find(item=>item.id===$('#assetMovementItem')?.value),destination=$('#assetMovementDestination'),responsible=$('#assetMovementNew'),origin=$('#assetMovementOrigin'),previous=$('#assetMovementPrevious'),destinationAllowed=['transfer','return','maintenance_out','maintenance_return','loan','retirement'].includes(type)||(type==='assignment'&&can('assets.move'));if(origin)origin.value=asset?.location||'';if(previous)previous.value=asset?.current_responsible||'';if(destination){destination.disabled=!destinationAllowed;if(!destinationAllowed)destination.value=''}if(responsible){responsible.disabled=type!=='assignment';if(type!=='assignment')responsible.value=''}}
async function saveAssetMovement(button=null){const type=$('#assetMovementType').value,definition=authorizedAssetMovements().find(operation=>operation.type===type),asset=assetItems().find(item=>item.id===$('#assetMovementItem').value),destinationAllowed=['transfer','return','maintenance_out','maintenance_return','loan','retirement'].includes(type)||(type==='assignment'&&can('assets.move')),destination=destinationAllowed?$('#assetMovementDestination').value.trim()||null:null,newResponsible=type==='assignment'?$('#assetMovementNew').value.trim()||null:null;if(!definition)return toast('Permissão específica necessária para esta movimentação.');if(!assetAcceptsMovement(asset))return toast('Bens baixados ou inativos não podem ser movimentados.');if(type==='assignment'&&!newResponsible)return toast('Informe o novo responsável.');setAdminButtonLoading(button,true);try{const {error}=await Supabase.rpc('record_asset_movement',{p_asset_id:asset.id,p_movement_type:type,p_origin:null,p_destination:destination,p_previous_responsible:null,p_new_responsible:newResponsible,p_movement_date:$('#assetMovementDate').value,p_notes:$('#assetMovementNotes').value.trim()||null});if(error)throw error;await refreshAdministration();closeModal();renderPage();toast('Movimentação patrimonial registrada.')}catch(error){toast(friendlyError(error,'movimentação patrimonial'))}finally{setAdminButtonLoading(button,false)}}
function renderAdminMovements(){if(State.movementTab==='books'&&!can('inventory.view'))State.movementTab='assets';if(State.movementTab==='assets'&&!can('assets.view'))State.movementTab='books';return `<div class="movement-tabs"><button class="${State.movementTab==='books'?'active':''}" onclick="App.setMovementTab('books')" ${!can('inventory.view')?'disabled':''}>Movimentações de livros</button><button class="${State.movementTab==='assets'?'active':''}" onclick="App.setMovementTab('assets')" ${!can('assets.view')?'disabled':''}>Movimentações patrimoniais</button></div><div class="movement-filters"><input id="movementSearch" class="search" placeholder="Filtrar por item, aluno, responsável, usuário ou sala" oninput="App.filterMovementHistory()"/><input id="movementFrom" type="date" onchange="App.filterMovementHistory()"/><input id="movementTo" type="date" onchange="App.filterMovementHistory()"/></div><section class="panel inventory-history" id="movementHistory">${State.movementTab==='assets'?renderAssetHistory():renderBookHistory()}</section>`}
function setMovementTab(tab){if(tab==='books'&&!can('inventory.view')||tab==='assets'&&!can('assets.view'))return;State.movementTab=tab;renderPage()}
function filterMovementHistory(){const target=$('#movementHistory');if(!target)return;const q=($('#movementSearch')?.value||'').toLowerCase(),from=$('#movementFrom')?.value||'',to=$('#movementTo')?.value||'';if(State.movementTab==='books'){const original=State.db.inventoryMovements;State.db.inventoryMovements=original.filter(m=>(!q||JSON.stringify(m).toLowerCase().includes(q))&&(!from||(m.movement_date||m.created_at)>=from)&&(!to||(m.movement_date||m.created_at).slice(0,10)<=to));target.innerHTML=renderBookHistory();State.db.inventoryMovements=original}else{const original=State.db.assetMovements;State.db.assetMovements=original.filter(m=>(!q||JSON.stringify(m).toLowerCase().includes(q))&&(!from||m.movement_date>=from)&&(!to||m.movement_date<=to));target.innerHTML=renderAssetHistory();State.db.assetMovements=original}}
async function refreshAdministration(){
  const previous={inventoryItems:State.db.inventoryItems,inventoryMovements:State.db.inventoryMovements,assets:State.db.assets,assetMovements:State.db.assetMovements,inventoryAvailable:State.db.inventoryAvailable,assetsAvailable:State.db.assetsAvailable},container=$('#pageContainer');
  container?.setAttribute('aria-busy','true');
  try{
    const jobs=[];
    if(can('inventory.view'))jobs.push(Supabase.from('inventory_items').select('*').order('name'),Supabase.from('book_movements').select('*').order('created_at',{ascending:false}).limit(250));else jobs.push(Promise.resolve({data:[]}),Promise.resolve({data:[]}));
    if(can('assets.view'))jobs.push(Supabase.from('assets').select('*').order('name'),Supabase.from('asset_movements').select('*').order('movement_date',{ascending:false}).limit(250));else jobs.push(Promise.resolve({data:[]}),Promise.resolve({data:[]}));
    const [books,moves,assets,assetMoves]=await Promise.all(jobs),error=books.error||moves.error||assets.error||assetMoves.error;
    if(error)throw error;
    State.db.inventoryItems=books.data||[];State.db.inventoryMovements=moves.data||[];State.db.assets=assets.data||[];State.db.assetMovements=assetMoves.data||[];State.db.inventoryAvailable=can('inventory.view');State.db.assetsAvailable=can('assets.view');
    return true;
  }catch(error){
    Object.assign(State.db,previous);
    throw error;
  }finally{container?.removeAttribute('aria-busy')}
}
function csvCell(value){const raw=String(value??''),safe=/^[\t\r\n ]*[=+\-@]/.test(raw)?`'${raw}`:raw;return `"${safe.replace(/"/g,'""')}"`}
function exportBooksCSV(){if(!can('inventory.export'))return toast('Exportação não autorizada.');const keys=['internal_code','name','collection','course','level','volume','edition','language','current_quantity','minimum_quantity','location','unit_value','active'];download(`estoque-livros-${todayISO()}.csv`,[keys.join(';'),...bookItems().map(x=>keys.map(k=>csvCell(x[k])).join(';'))].join('\n'),'text/csv;charset=utf-8')}
function exportAssetsCSV(){if(!can('assets.export'))return toast('Exportação não autorizada.');const keys=['asset_code','name','category','brand','model','serial_number','quantity','location','current_responsible','acquisition_date','acquisition_value','condition','status'];download(`patrimonio-${todayISO()}.csv`,[keys.join(';'),...assetItems().map(x=>keys.map(k=>csvCell(x[k])).join(';'))].join('\n'),'text/csv;charset=utf-8')}
function inventoryOptions(items,key,label){return [...new Set(items.map(x=>x[key]).filter(Boolean))].sort().map(v=>`<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('')}
function renderInventory(){if(!can('inventory.view'))return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;const items=(State.db.inventoryItems||[]).filter(x=>x.active);const total=items.reduce((sum,x)=>sum+Number(x.current_quantity||0),0),low=items.filter(x=>inventoryStatus(x).key==='low').length,out=items.filter(x=>inventoryStatus(x).key==='out').length;return `<div class="page inventory-page"><div class="section-title"><div><span class="eyebrow">Administrativo</span><h2>Estoque</h2><p>Controle de livros e materiais físicos da Purple.</p></div><div class="section-actions">${can('inventory.entry')?'<button class="btn soft" onclick="App.openInventoryMovement(\'entry\')">Entrada de estoque</button>':''}${can('inventory.issue')?'<button class="btn soft" onclick="App.openInventoryMovement(\'issue\')">Baixa de estoque</button>':''}${can('inventory.create')?'<button class="btn primary" onclick="App.editInventoryItem()">Novo livro</button>':''}</div></div>${!State.db.inventoryAvailable?'<div class="alert yellow inventory-migration"><div class="alert-icon">!</div><div><b>Módulo aguardando migração do banco</b><span>A interface está pronta. Aplique a migração de Estoque para habilitar cadastros e movimentações.</span></div></div>':''}<section class="grid cols-4 inventory-kpis">${metricCard('Total de livros',fmtNumber(items.length),'▣',0,'Títulos ativos')}${metricCard('Quantidade em estoque',fmtNumber(total),'▤',0,'Unidades disponíveis')}${metricCard('Estoque baixo',fmtNumber(low),'!',0,'Abaixo ou igual ao mínimo')}${metricCard('Esgotados',fmtNumber(out),'○',0,'Sem unidades disponíveis')}</section><section class="panel inventory-panel"><div class="inventory-toolbar"><input id="inventorySearch" class="search" placeholder="Pesquisar livro, código ou curso" oninput="App.applyInventoryFilters()"/><select id="inventoryCourse" class="select" onchange="App.applyInventoryFilters()"><option value="all">Todos os cursos</option>${inventoryOptions(items,'course')}</select><select id="inventoryCategory" class="select" onchange="App.applyInventoryFilters()"><option value="all">Todas as categorias</option>${inventoryOptions(items,'category')}</select><select id="inventoryLevel" class="select" onchange="App.applyInventoryFilters()"><option value="all">Todos os níveis</option>${inventoryOptions(items,'level')}</select><select id="inventoryAvailability" class="select" onchange="App.applyInventoryFilters()"><option value="all">Toda disponibilidade</option><option value="available">Disponível</option><option value="low">Estoque Baixo</option><option value="out">Esgotado</option></select></div><div id="inventoryTable"></div></section><section class="panel inventory-history"><div class="panel-head"><div><span class="eyebrow">Histórico</span><h3>Últimas movimentações</h3></div></div>${renderInventoryHistory()}</section></div>`}
function applyInventoryFilters(){const target=$('#inventoryTable');if(!target)return;const search=($('#inventorySearch')?.value||'').toLowerCase(),course=$('#inventoryCourse')?.value||'all',category=$('#inventoryCategory')?.value||'all',level=$('#inventoryLevel')?.value||'all',availability=$('#inventoryAvailability')?.value||'all';const items=(State.db.inventoryItems||[]).filter(x=>x.active).filter(x=>(!search||`${x.name} ${x.internal_code||''} ${x.course||''}`.toLowerCase().includes(search))&&(course==='all'||x.course===course)&&(category==='all'||x.category===category)&&(level==='all'||x.level===level)&&(availability==='all'||inventoryStatus(x).key===availability));target.innerHTML=`<div class="table-wrap"><table class="inventory-table"><thead><tr><th>Nome</th><th>Curso</th><th>Nível</th><th>Quantidade disponível</th><th>Status</th><th>Ações</th></tr></thead><tbody>${items.map(item=>{const status=inventoryStatus(item);return `<tr><td><b>${escapeHTML(item.name)}</b>${item.internal_code?`<small>${escapeHTML(item.internal_code)}</small>`:''}</td><td>${escapeHTML(item.course||'—')}</td><td>${escapeHTML(item.level||'—')}</td><td><b>${fmtNumber(item.current_quantity)}</b><small>Mínimo: ${fmtNumber(item.minimum_quantity)}</small></td><td><span class="stock-status ${status.key}">${status.label}</span></td><td><div class="table-actions">${can('inventory.edit')?`<button class="btn ghost small" onclick="App.editInventoryItem('${item.id}')">Editar</button>`:''}${can('inventory.adjust')?`<button class="btn soft small" onclick="App.openInventoryMovement('adjustment','${item.id}')">Ajustar</button>`:''}${can('inventory.delete')?`<button class="btn danger small" onclick="App.deleteInventoryItem('${item.id}')">Excluir</button>`:''}</div></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty"><p>Nenhum item encontrado.</p></div></td></tr>'}</tbody></table></div>`}
function renderInventoryHistory(){const names=Object.fromEntries((State.db.inventoryItems||[]).map(x=>[x.id,x.name]));const labels={entry:'Entrada',issue:'Baixa',adjustment:'Ajuste manual'};return `<div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Operação</th><th>Quantidade</th><th>Livro</th></tr></thead><tbody>${(State.db.inventoryMovements||[]).slice(0,12).map(m=>`<tr><td>${fmtDateTime(m.created_at)}</td><td>${escapeHTML(m.responsible_name||'Usuário')}</td><td>${labels[m.movement_type]||m.movement_type}${m.student_name?`<small>Aluno: ${escapeHTML(m.student_name)}</small>`:''}</td><td class="movement-qty ${Number(m.quantity_change)>=0?'positive':'negative'}">${Number(m.quantity_change)>0?'+':''}${fmtNumber(m.quantity_change)}</td><td>${escapeHTML(names[m.item_id]||m.item_name||'Item')}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty"><p>Nenhuma movimentação registrada.</p></div></td></tr>'}</tbody></table></div>`}
function editInventoryItem(id=''){if(!can(id?'inventory.edit':'inventory.create'))return toast('Operação não autorizada.');if(!State.db.inventoryAvailable)return toast('Aplique a migração do Estoque antes de cadastrar itens.');const item=id?State.db.inventoryItems.find(x=>x.id===id):null;modal(`<div class="modal-head"><div><span class="eyebrow">Estoque</span><h3>${item?'Editar livro':'Novo livro'}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="form-grid cols-2"><div class="field"><label>Código interno (opcional)</label><input id="inventoryCode" value="${escapeHTML(item?.internal_code||'')}"/></div><div class="field"><label>Nome do livro</label><input id="inventoryName" value="${escapeHTML(item?.name||'')}" required/></div><div class="field"><label>Categoria</label><input id="inventoryCategoryEdit" value="${escapeHTML(item?.category||'Livro didático')}"/></div><div class="field"><label>Curso</label><input id="inventoryCourseEdit" value="${escapeHTML(item?.course||'')}"/></div><div class="field"><label>Nível</label><input id="inventoryLevelEdit" value="${escapeHTML(item?.level||'')}"/></div><div class="field"><label>Quantidade mínima</label><input id="inventoryMinimum" type="number" min="0" value="${Number(item?.minimum_quantity||0)}"/></div>${item?'':`<div class="field"><label>Quantidade inicial</label><input id="inventoryInitial" type="number" min="0" value="0"/></div>`}<div class="field"><label>Localização (opcional)</label><input id="inventoryLocation" value="${escapeHTML(item?.location||'')}"/></div></div><div class="field"><label>Observações</label><textarea id="inventoryNotes">${escapeHTML(item?.notes||'')}</textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveInventoryItem('${id}')">Salvar livro</button></div>`,true)}
function saveInventoryItem(id='',button=null){return saveBook(id,button)}
function deleteInventoryItem(id,button=null){return inactivateBook(id,button)}
function openInventoryMovement(type,itemId=''){const permission={entry:'inventory.entry',issue:'inventory.issue',adjustment:'inventory.adjust'}[type];if(!can(permission))return toast('Operação não autorizada.');if(!State.db.inventoryAvailable)return toast('Aplique a migração do Estoque antes de registrar movimentações.');const items=(State.db.inventoryItems||[]).filter(x=>x.active),selected=items.find(x=>x.id===itemId);modal(`<div class="modal-head"><div><span class="eyebrow">Movimentação de estoque</span><h3>${type==='entry'?'Entrada de Estoque':type==='issue'?'Baixa de Livro':'Ajuste de Quantidade'}</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="field"><label>Livro</label><select id="movementItem" ${itemId?'disabled':''}>${items.map(x=>`<option value="${x.id}" ${x.id===itemId?'selected':''}>${escapeHTML(x.name)} — ${fmtNumber(x.current_quantity)} disponíveis</option>`).join('')}</select></div>${type==='issue'?'<div class="field"><label>Aluno</label><input id="movementStudent" placeholder="Nome do aluno"/></div>':''}<div class="field"><label>${type==='adjustment'?'Nova quantidade':'Quantidade'}</label><input id="movementQuantity" type="number" min="${type==='adjustment'?0:1}" value="${type==='adjustment'?Number(selected?.current_quantity||0):1}"/></div><div class="field"><label>Observações</label><textarea id="movementNotes"></textarea></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveInventoryMovement('${type}')">Confirmar</button></div>`,true)}
function saveInventoryMovement(type,button=null){return saveBookMovement(type,button)}
function refreshInventory(){return Promise.reject(new Error('Fluxo legado de estoque removido.'))}

function renderAudit(){if(State.user.role!=='direction')return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;const events=State.db.audit.slice().sort((a,b)=>b.at.localeCompare(a.at)).map(e=>`<div class="audit-event"><time>${fmtDateTime(e.at)}</time><div><b>${escapeHTML(e.action)}</b><div class="muted" style="margin-top:3px">${escapeHTML(e.detail||'')}</div></div><div class="actor">${escapeHTML(e.actor)}</div></div>`).join('');return `<div class="page"><div class="section-title"><div><h2>Auditoria</h2><p>Registro das principais alterações realizadas no sistema.</p></div><button class="btn ghost" onclick="App.exportAuditCSV()">Exportar CSV</button></div><section class="panel">${events||'<div class="empty"><p>Nenhum evento registrado.</p></div>'}</section></div>`}
function exportAuditCSV(){const rows=[['Data','Ator','Ação','Detalhe'],...State.db.audit.map(e=>[fmtDateTime(e.at),e.actor,e.action,e.detail||''])];download(`purple-auditoria-${new Date().toISOString().slice(0,10)}.csv`,'\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\n'),'text/csv;charset=utf-8')}

function renderSettings(){const s=State.db.settings,u=State.user;return `<div class="page account-page"><div class="section-title"><div><h2>Configurações</h2><p>Gerencie sua conta e as preferências do Purple Gestão.</p></div></div><div class="settings-tabs"><button onclick="App.settingsTab('account')">Minha Conta</button><button onclick="App.settingsTab('security')">Segurança</button><button onclick="App.settingsTab('preferences')">Preferências</button>${u.role==='direction'?'<button onclick="App.settingsTab(\'system\')">Sistema</button>':''}</div><div id="settingsContent">${renderSettingsTab('account',s,u)}</div></div>`}
function renderSettingsTab(tab,s=State.db.settings,u=State.user){if(tab==='security')return `<section class="form-card account-card"><h3>Segurança</h3><p class="helper">Use uma senha exclusiva com pelo menos 8 caracteres.</p><div class="field"><label>Senha atual</label><input id="currentPassword" type="password" autocomplete="current-password"/></div><div class="form-grid cols-2"><div class="field"><label>Nova senha</label><input id="newPassword" type="password" minlength="8" autocomplete="new-password"/></div><div class="field"><label>Confirmar nova senha</label><input id="confirmPassword" type="password" minlength="8" autocomplete="new-password"/></div></div><button id="changePasswordButton" class="btn primary" onclick="App.changePassword()">Alterar senha</button></section>`;if(tab==='preferences')return `<section class="form-card account-card"><h3>Preferências</h3><div class="setting-row"><div><b>Notificações</b><p>Configuração global de alertas operacionais e lembretes.</p></div><button class="switch ${s.notifications?'on':''}" onclick="App.toggleSetting('notifications')" ${can('settings.edit')?'':'disabled'}></button></div></section>`;if(tab==='system'&&u.role==='direction'){const status=window.PurpleSystemStatus?.()||{};return `<section class="form-card account-card"><h3>Status do Sistema</h3><p class="helper">Leitura técnica rápida da instalação atual, cache, Supabase e sessão.</p>${[['Status do Supabase',status.supabaseReady?'Conectado':'Verificando'],['Versão do sistema',status.appVersion||s.version||'1.0'],['Data da implantação',s.deploymentDate||'18/07/2026'],['Versão do banco',s.databaseVersion||'20260719'],['Versão do cache',status.serviceWorkerVersion||s.cacheVersion||'v85'],['Service Worker',status.serviceWorkerSupported?(status.controllerActive?'Ativo':'Suportado, aguardando controle'):'Não suportado'],['Estado da autenticação',status.authState||'—'],['Última sincronização',fmtDateTime(s.lastSync)],['Atualizado em',fmtDateTime(status.timestamp)]].map(x=>`<div class="setting-row"><b>${x[0]}</b><span>${escapeHTML(x[1]||'—')}</span></div>`).join('')}<div class="section-actions" style="justify-content:flex-start;margin-top:14px"><button class="btn ghost" onclick="App.showDiagnostics()">Abrir diagnóstico técnico</button></div></section>`}return `<section class="form-card account-card"><h3>Meu Perfil</h3><div class="profile-summary"><div class="user-avatar profile-avatar">${escapeHTML(u.name.charAt(0).toUpperCase())}</div><div><b>${escapeHTML(u.name)}</b><span>${escapeHTML(u.email)}</span></div></div><div class="form-grid cols-2"><div class="field"><label>Nome</label><input id="profileName" value="${escapeHTML(u.name)}"/></div><div class="field"><label>Telefone</label><input id="profilePhone" value="${escapeHTML(u.phone)}"/></div><div class="field"><label>Cargo</label><input id="profileJobTitle" value="${escapeHTML(u.jobTitle)}"/></div><div class="field"><label>Foto</label><input id="profileAvatarUrl" value="${escapeHTML(u.avatarUrl||'')}" placeholder="Foto administrada pela Direção" disabled/></div><div class="field"><label>E-mail</label><input value="${escapeHTML(u.email)}" disabled/></div><div class="field"><label>Perfil</label><input value="${ROLE_LABELS[u.role]}" disabled/></div><div class="field"><label>Último acesso</label><input value="${fmtDateTime(u.lastLoginAt)}" disabled/></div><div class="field"><label>Data de criação</label><input value="${fmtDateTime(u.createdAt)}" disabled/></div></div><div class="field"><label>Assinatura eletrônica</label><textarea id="profileSignature" placeholder="Assinatura utilizada em aprovações e registros internos">${escapeHTML(u.electronicSignature)}</textarea></div><button id="saveProfileButton" class="btn primary" onclick="App.saveMyProfile()">Salvar perfil</button></section>`}
function settingsTab(tab){$('#settingsContent').innerHTML=renderSettingsTab(tab)}
async function saveMyProfile(){
  const button=$('#saveProfileButton'),payload={p_name:$('#profileName').value.trim(),p_phone:$('#profilePhone').value.trim(),p_job_title:$('#profileJobTitle').value.trim(),p_electronic_signature:$('#profileSignature').value.trim()};
  if(!payload.p_name)return toast('Informe seu nome.');
  button.disabled=true;
  try{
    const {data,error}=await Supabase.rpc('update_my_profile',payload);
    if(error)throw error;
    const profilePatch={name:data.name,phone:data.phone||'',jobTitle:data.job_title||'',electronicSignature:data.electronic_signature||''};
    Object.assign(State.user,profilePatch);
    const listedUser=State.db.users.find(user=>user.id===State.user.id);
    if(listedUser)Object.assign(listedUser,profilePatch);
    $('#userName').textContent=State.user.name;
    $('#userAvatar').textContent=State.user.name.charAt(0).toUpperCase();
    logAudit('Editou o próprio perfil','Dados pessoais atualizados');
    toast('Perfil atualizado com sucesso.');
    State.page='settings';
    renderPage();
  }catch(e){toast(friendlyError(e,'atualização de perfil'))}
  finally{button.disabled=false}
}
async function clearPasswordChangeRequirement(){
  State.user.mustChangePassword=false;
  const listedUser=State.db.users.find(user=>user.id===State.user.id);
  if(listedUser)listedUser.mustChangePassword=false;
  if(!hasSupabaseClient())return;
  try{
    const {error}=await Supabase.rpc('clear_my_password_change_required');
    if(error)throw error;
  }catch(error){
    console.warn('Purple Gestão — limpeza da troca obrigatória de senha:',error);
  }
}
function showRequiredPasswordChange(){
  modal(`<div class="required-password-modal"><div class="modal-head"><div><span class="eyebrow">Primeiro acesso</span><h3>Crie sua senha definitiva</h3><p class="helper">A Direção criou um acesso inicial para você. Por segurança, altere a senha agora antes de continuar no Purple Gestão.</p></div></div><div class="field"><label>Senha recebida</label><input id="currentPassword" type="password" autocomplete="current-password" autofocus/></div><div class="form-grid cols-2"><div class="field"><label>Nova senha</label><input id="newPassword" type="password" minlength="8" autocomplete="new-password"/></div><div class="field"><label>Confirmar nova senha</label><input id="confirmPassword" type="password" minlength="8" autocomplete="new-password"/></div></div><div class="alert info"><div class="alert-icon">i</div><div><b>Senha mínima de 8 caracteres</b><span>Depois de salvar, seu acesso continua com as permissões definidas pela Direção.</span></div></div><div class="section-actions"><button id="changePasswordButton" class="btn primary full" onclick="App.changePassword(true)">Salvar minha senha e entrar</button></div></div>`,true,true);
}
async function changePassword(force=false){const current=$('#currentPassword').value,next=$('#newPassword').value,confirmPassword=$('#confirmPassword').value,button=$('#changePasswordButton');if(!current)return toast('Informe a senha atual.');if(next.length<8)return toast('A nova senha deve ter pelo menos 8 caracteres.');if(next!==confirmPassword)return toast('A confirmação da senha não confere.');button.disabled=true;try{const {error:verifyError}=await Supabase.auth.signInWithPassword({email:State.user.email,password:current});if(verifyError)throw new Error('Senha atual inválida.');const {error}=await Supabase.auth.updateUser({password:next});if(error)throw error;if(force||State.user.mustChangePassword)await clearPasswordChangeRequirement();logAudit('Alterou a senha',force?'Senha definitiva criada no primeiro acesso':'Senha atualizada pelo próprio usuário');toast('Senha alterada com sucesso.');$('#currentPassword').value=$('#newPassword').value=$('#confirmPassword').value='';if(force){closeModal();if(State.page==='home')showPendingDataReminder()}}catch(e){console.error('Purple Gestão — alteração de senha:',e);toast(e.message==='Senha atual inválida.'?e.message:'Não foi possível alterar a senha. Tente novamente.')}finally{button.disabled=false}}
async function saveSettings(){const before=cloneValue(State.db.settings);Object.assign(State.db.settings,{retentionRisk:Number($('#settingRetentionRisk').value),rematriculationTarget:Number($('#settingRematriculation').value),delinquencyAlert:Number($('#settingDelinquency').value),criticalGroups:Number($('#settingCriticalGroups').value),weeklyDeadline:$('#settingWeekly').value,biweeklyDeadline:$('#settingBiweekly').value,monthlyDeadline:$('#settingMonthly').value});try{await Storage.save(State.db);logAudit('Atualizou configurações','Metas, alertas e prazos padrão');toast('Configurações salvas.');renderPage()}catch(error){State.db.settings=before;toast(friendlyError(error,'salvamento das configurações'))}}
async function toggleSetting(key){if(State.user.role!=='direction')return toast('Somente a direção pode alterar esta configuração.');const before=State.db.settings[key];State.db.settings[key]=!before;try{await Storage.save(State.db);logAudit('Alterou configuração',`${key}: ${State.db.settings[key]}`);renderPage()}catch(error){State.db.settings[key]=before;toast(friendlyError(error,'alteração da configuração'))}}
function defaultPermissions(role,sector){const all=Object.values(PERMISSION_GROUPS).flat().map(x=>x[0]);if(role==='direction')return Object.fromEntries(all.map(k=>[k,true]));const base=['panel.view','settings.view'];if(role==='viewer')base.push('reports.view','indicators.view','mural.view','whatsapp.view','inventory.view','assets.view');if(role==='teacher')base.push('twr.view.own','classes.view','lesson_plans.view');if(role==='leader')base.push('reports.view','reports.create','reports.edit','reports.export','indicators.view','tasks.view','tasks.create','tasks.edit','tasks.delete','pulse.view','pulse.answer','mural.view','meetings.view','cases.view','actions.view','actions.create','actions.edit','students.view','classes.view','teachers.view','whatsapp.view','whatsapp.reply','inventory.view','inventory.issue','inventory.return','twr.manage','twr.submit.own','class_opening.manage','lesson_plans.view','lesson_plans.edit');if(role==='leader'&&sector==='pedagogico')base.push('twr.approve','lesson_plans.review','lesson_plans.publish','lesson_plans.ai','lesson_plans.cycles.manage');if(role==='leader'&&sector==='financeiro')base.push('financial.receipts.view','financial.payments.view','financial.receivables.view','financial.payables.view','financial.bank_accounts.view','financial.balances.view','financial.transactions.create','financial.transactions.edit','financial.transactions.delete','financial.export','inventory.create','inventory.edit','inventory.entry','inventory.adjust','inventory.inactivate','inventory.export','assets.view','assets.export');return Object.fromEntries(all.map(k=>[k,base.includes(k)]))}
function accessProfiles(){
  const settings=State.db.settings||{};
  const defaults=[
    {id:'profile-professor-basic',name:'Professor básico',description:'Acesso essencial para rotina do professor, TWR, turmas e Biblioteca.',role:'teacher',sector:'pedagogico',accessScope:'own_sector',permissions:defaultPermissions('teacher','pedagogico')},
    {id:'profile-professor-twr-team',name:'Professor coordenação TWR',description:'Professor(a) que acompanha horários de todos os teachers sem permissão para limpar/criar atividades.',role:'teacher',sector:'pedagogico',accessScope:'own_sector',permissions:{...defaultPermissions('teacher','pedagogico'),'teachers.view':true,'twr.manage':false,'twr.approve':false}},
    {id:'profile-professor-library',name:'Professor + Biblioteca ativa',description:'Professor com consulta e contribuição nos Lesson Plans.',role:'teacher',sector:'pedagogico',accessScope:'own_sector',permissions:{...defaultPermissions('teacher','pedagogico'),'lesson_plans.edit':true,'mural.view':true}},
    {id:'profile-coord-pedagogica',name:'Coordenação pedagógica',description:'Gestão pedagógica, TWR e publicação/revisão de Lesson Plans.',role:'leader',sector:'pedagogico',accessScope:'own_sector',permissions:defaultPermissions('leader','pedagogico')},
    {id:'profile-financeiro',name:'Financeiro operacional',description:'Rotina financeira, estoque de livros e relatórios financeiros.',role:'leader',sector:'financeiro',accessScope:'own_sector',permissions:defaultPermissions('leader','financeiro')}
  ];
  if(!Array.isArray(settings.userAccessProfiles))settings.userAccessProfiles=[];
  defaults.forEach(profile=>{if(!settings.userAccessProfiles.some(item=>item.id===profile.id))settings.userAccessProfiles.push(profile)});
  settings.userAccessProfiles=settings.userAccessProfiles.map(profile=>({...profile,permissions:validPermissionObject(profile.permissions)?profile.permissions:defaultPermissions(profile.role,profile.sector),accessScope:profile.accessScope||profile.access_scope||'own_sector'}));
  return settings.userAccessProfiles;
}
function findAccessProfile(id){return accessProfiles().find(profile=>profile.id===id)||null}
function accessProfileOptions(selected=''){return accessProfiles().map(profile=>`<option value="${escapeHTML(profile.id)}" ${selected===profile.id?'selected':''}>${escapeHTML(profile.name)}</option>`).join('')}
function profileCard(profile){const count=Object.values(profile.permissions||{}).filter(Boolean).length;return `<article class="access-profile-card"><div><b>${escapeHTML(profile.name)}</b><span>${escapeHTML(ROLE_LABELS[profile.role]||profile.role)} • ${escapeHTML(profile.sector==='all'?'Todos os setores':SECTOR_LABELS[profile.sector]||profile.sector)} • ${fmtNumber(count)} permissões</span><p>${escapeHTML(profile.description||'')}</p></div><div class="section-actions"><button class="btn ghost small" onclick="App.editAccessProfile('${escapeHTML(profile.id)}')">Editar</button><button class="btn danger small" onclick="App.deleteAccessProfile('${escapeHTML(profile.id)}')">Excluir</button></div></article>`}
function permissionChecklist(permissions){return Object.entries(PERMISSION_GROUPS).map(([group,items])=>`<section class="permission-group"><h4>${group}</h4><div class="permission-checks">${items.map(([key,label])=>`<label class="check-chip"><input type="checkbox" data-permission="${key}" onchange="App.updatePermissionSummary();App.syncTeacherAccessDesigner()" ${permissions[key]?'checked':''}/> ${label}</label>`).join('')}</div></section>`).join('')}
function teacherAccessDesigner(permissions){
  const cards=[
    ['panel.view','Início','Painel inicial e avisos do professor.'],
    ['twr.view.own','Meu TWR','Rotina semanal, sala e próximos compromissos.'],
    ['teachers.view','TWR da equipe','Mostra horários de todos os teachers, sem liberar criação ou exclusão.'],
    ['classes.view','Minhas turmas','Turmas, horários e contexto pedagógico.'],
    ['lesson_plans.view','Biblioteca pedagógica','Coleções, livros, unidades, recursos e contribuições.'],
    ['lesson_plans.edit','Editar planos','Permite entrar em modo edição quando autorizado.'],
    ['mural.view','Mural','Comunicados internos da Purple.'],
    ['settings.view','Minha conta','Perfil, preferências e troca de senha.']
  ];
  return `<section class="teacher-access-designer"><div><span class="eyebrow">Acesso do professor</span><h4>Menus e ações liberadas</h4><p>Use estes botões para montar a experiência que o professor verá no sistema. O checklist técnico abaixo continua disponível para ajustes finos.</p></div><div class="teacher-access-grid">${cards.map(([key,title,description])=>`<label class="teacher-access-card ${permissions[key]?'active':''}"><input type="checkbox" data-teacher-access="${key}" onchange="App.toggleTeacherAccess('${key}',this.checked)" ${permissions[key]?'checked':''}/><span>${escapeHTML(title)}</span><small>${escapeHTML(description)}</small></label>`).join('')}</div></section>`;
}
function validPermissionObject(value){return !!value&&!Array.isArray(value)&&typeof value==='object'&&Object.entries(value).every(([key,enabled])=>PERMISSION_KEY_SET.has(key)&&typeof enabled==='boolean')}
function userEffectivePermissions(user){return validPermissionObject(user?.permissions)?user.permissions:defaultPermissions(user?.role,user?.sector)}
function isEffectiveAdministrator(user){return user?.role==='direction'&&user.active===true&&user.sector==='all'&&user.accessScope==='all_sectors'&&user.permissions?.['users.edit']===true}
function enforceUserAccessFields(){
  const role=$('#userEditRole')?.value,sector=$('#userEditSector'),scope=$('#userEditScope');
  if(!role||!sector||!scope)return;
  if(role==='direction'){sector.value='all';scope.value='all_sectors';sector.disabled=true;scope.disabled=true;return}
  sector.disabled=false;scope.value='own_sector';scope.disabled=true;
  if(role==='leader'&&sector.value==='all')sector.value='retencao';
  if(role==='teacher')sector.value='pedagogico';
}
function renderUsers(){if(!can('users.view'))return `<div class="page"><div class="empty"><div class="emoji">🔒</div><h3>Acesso restrito</h3></div></div>`;const editable=can('users.edit')&&State.user.role==='direction',users=State.db.users||[],profiles=accessProfiles(),active=users.filter(u=>u.active!==false).length,teachers=users.filter(u=>u.role==='teacher').length,admins=users.filter(u=>isEffectiveAdministrator({...u,accessScope:u.accessScope||(u.role==='direction'?'all_sectors':'own_sector'),permissions:userEffectivePermissions(u)})).length,cards=users.map(u=>{const effectivePermissions=userEffectivePermissions(u),activePerms=Object.entries(effectivePermissions).filter(([,enabled])=>enabled).length;return `<article class="user-admin-card ${u.active?'':'inactive'}"><div class="user-admin-avatar">${escapeHTML((u.name||'?').charAt(0).toUpperCase())}</div><div class="user-admin-copy"><b>${escapeHTML(u.name)}</b><span>${escapeHTML(u.email)}</span><small>${escapeHTML(ROLE_LABELS[u.role]||u.role)} • ${escapeHTML(u.sector==='all'?'Todos os setores':SECTOR_LABELS[u.sector]||u.sector)} • ${activePerms} permissões</small><div class="user-admin-badges"><span class="status ${u.active?'approved':'archived'}">${u.active?'Ativo':'Inativo'}</span>${u.mustChangePassword?'<span class="status pending">Troca de senha obrigatória</span>':''}</div></div><div class="user-admin-actions">${editable?`<button class="btn ghost small" onclick="App.editUser('${u.id}')">Editar</button><button class="btn danger small" onclick="App.deleteUser('${u.id}')">Excluir</button>`:'<span class="muted">Somente leitura</span>'}</div></article>`}).join('');return `<div class="page users-admin-page"><section class="users-admin-hero"><div><span class="eyebrow">Acessos e permissões</span><h2>Usuários do Purple Gestão</h2><p>Crie logins, defina senha inicial e aplique perfis prontos de acesso para não marcar as mesmas permissões toda vez.</p></div>${editable?`<div class="section-actions"><button class="btn soft" onclick="App.editAccessProfile()">+ Novo perfil</button><button class="btn primary" onclick="App.editUser()">+ Novo usuário</button></div>`:''}</section><section class="users-admin-metrics"><div><span>Usuários ativos</span><b>${fmtNumber(active)}</b></div><div><span>Professores</span><b>${fmtNumber(teachers)}</b></div><div><span>Admins efetivos</span><b>${fmtNumber(admins)}</b></div><div><span>Perfis salvos</span><b>${fmtNumber(profiles.length)}</b></div></section>${editable?`<section class="panel access-profile-panel"><div class="panel-head"><div><span class="eyebrow">Perfis de acesso</span><h3>Modelos reutilizáveis</h3><small>Crie um perfil uma vez e aplique no cadastro de novos professores/equipe.</small></div><button class="btn primary small" onclick="App.editAccessProfile()">Criar perfil</button></div><div class="access-profile-list">${profiles.map(profileCard).join('')}</div></section>`:''}<section class="user-admin-list">${cards||'<div class="empty"><p>Nenhum usuário cadastrado.</p></div>'}</section></div>`}
function editUser(id=''){if(State.user.role!=='direction'||!can('users.edit'))return toast('Operação não autorizada.');const isNew=!id,u=isNew?{id:'',name:'',email:'',role:'teacher',sector:'pedagogico',accessScope:'own_sector',active:true,jobTitle:'Professor(a)',avatarUrl:'',permissions:defaultPermissions('teacher','pedagogico'),mustChangePassword:true}:State.db.users.find(x=>x.id===id);if(!u)return toast('Usuário não encontrado.');const permissions={...(u.permissions||defaultPermissions(u.role,u.sector))},linkedTeacherId=resolveTeacherIdForUser(u);modal(`<div class="user-editor"><div class="modal-head"><div><span class="eyebrow">${isNew?'Novo acesso':'Gerenciar usuário'}</span><h3>${isNew?'Criar usuário no sistema':escapeHTML(u.name)}</h3><p class="helper">${isNew?'Defina login, senha inicial e aplique um perfil de acesso pronto.':'Ajuste permissões, status e, se necessário, redefina a senha.'}</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div><section class="user-editor-section"><h4>Dados de acesso</h4><div class="form-grid cols-2"><div class="field"><label>Nome completo</label><input id="userEditName" value="${escapeHTML(u.name)}" placeholder="Nome do colaborador"/></div><div class="field"><label>E-mail / login</label><input id="userEditEmail" type="email" value="${escapeHTML(u.email)}" placeholder="professor@purple..."/></div><div class="field"><label>Cargo</label><input id="userEditJobTitle" value="${escapeHTML(u.jobTitle||'')}"/></div><div class="field"><label>Professor vinculado</label><select id="userEditTeacherId"><option value="">Sem vínculo</option>${twrActiveTeachers().map(t=>`<option value="${escapeHTML(t.id)}" ${linkedTeacherId===t.id?'selected':''}>${escapeHTML(t.name)}</option>`).join('')}</select><small>Usado para Meu TWR, Minhas Turmas e chamadas.</small></div><div class="field span-2"><label>Avatar</label><input id="userEditAvatarUrl" value="${escapeHTML(u.avatarUrl||'')}" placeholder="URL da imagem"/></div></div></section><section class="user-editor-section"><h4>Perfil e escopo</h4><div class="form-grid cols-4"><div class="field span-2"><label>Aplicar perfil salvo</label><select id="userAccessProfile" onchange="App.applyAccessProfileToUser(this.value)"><option value="">Personalizado / sem modelo</option>${accessProfileOptions('')}</select><small>Aplica cargo, setor, escopo e permissões do modelo.</small></div><div class="field"><label>Perfil padrão</label><select id="userEditRole" onchange="App.restoreUserPermissions()"><option value="direction" ${u.role==='direction'?'selected':''}>Direção</option><option value="leader" ${u.role==='leader'?'selected':''}>Líder</option><option value="teacher" ${u.role==='teacher'?'selected':''}>Professor</option><option value="viewer" ${u.role==='viewer'?'selected':''}>Consulta</option></select></div><div class="field"><label>Setor</label><select id="userEditSector" onchange="App.restoreUserPermissions()"><option value="all" ${u.sector==='all'?'selected':''}>Todos</option>${['retencao','pedagogico','financeiro'].map(s=>`<option value="${s}" ${u.sector===s?'selected':''}>${SECTOR_LABELS[s]}</option>`).join('')}</select></div><div class="field"><label>Escopo</label><select id="userEditScope"><option value="own_sector" ${u.accessScope!=='all_sectors'?'selected':''}>Próprio setor</option><option value="all_sectors" ${u.accessScope==='all_sectors'?'selected':''}>Todos os setores</option></select></div><div class="field"><label>Status</label><select id="userEditActive"><option value="true" ${u.active?'selected':''}>Ativo</option><option value="false" ${!u.active?'selected':''}>Inativo</option></select></div></div><div class="section-actions" style="justify-content:flex-start;margin-top:8px"><button class="btn soft small" onclick="App.saveCurrentUserPermissionsAsProfile()">Salvar permissões atuais como perfil</button></div></section><div id="teacherAccessDesigner">${teacherAccessDesigner(permissions)}</div><div id="permissionChecklist">${permissionChecklist(permissions)}</div><div class="form-card"><h4>Permissões efetivas</h4><p id="permissionSummary" class="helper">${Object.entries(permissions).filter(x=>x[1]).map(x=>x[0]).join(' • ')||'Nenhuma permissão concedida.'}</p></div><section class="user-editor-section"><div class="password-reset-head"><div><h4>${isNew?'Senha inicial':'Senha'}</h4><p class="helper">${isNew?'Você cria a senha inicial. O professor troca no primeiro acesso.':'Redefina somente quando precisar entregar uma senha provisória.'}</p></div>${!isNew?'<button type="button" class="btn soft small" onclick="App.toggleUserPasswordReset()">Redefinir senha</button>':''}</div><div id="userPasswordReset" class="form-card ${isNew?'':'hidden'}"><div class="form-grid cols-2"><div class="field"><label>${isNew?'Senha inicial':'Nova senha'}</label><input id="userEditPassword" type="password" minlength="8" autocomplete="new-password"/></div><div class="field"><label>Confirmar senha</label><input id="userEditPasswordConfirm" type="password" minlength="8" autocomplete="new-password"/></div></div><label class="check-chip force-password"><input id="userMustChangePassword" type="checkbox" ${isNew||u.mustChangePassword?'checked':''}/> Exigir troca de senha no próximo acesso</label></div></section><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button id="saveUserAdminButton" class="btn primary" onclick="App.saveUserPermissions('${u.id}')">${isNew?'Criar usuário':'Salvar alterações'}</button></div></div>`,false);enforceUserAccessFields();syncTeacherAccessDesigner()}
function toggleUserPasswordReset(){$('#userPasswordReset').classList.toggle('hidden');if(!$('#userPasswordReset').classList.contains('hidden'))$('#userEditPassword').focus()}
function updatePermissionSummary(){const summary=$('#permissionSummary');if(summary)summary.textContent=$$('[data-permission]:checked').map(x=>x.dataset.permission).join(' • ')||'Nenhuma permissão concedida.'}
function syncTeacherAccessDesigner(){$$('[data-teacher-access]').forEach(input=>{const match=$(`[data-permission="${input.dataset.teacherAccess}"]`);input.checked=Boolean(match?.checked);input.closest('.teacher-access-card')?.classList.toggle('active',input.checked)})}
function toggleTeacherAccess(permission,enabled){const match=$(`[data-permission="${permission}"]`);if(match){match.checked=enabled;updatePermissionSummary()}syncTeacherAccessDesigner()}
function restoreUserPermissions(){enforceUserAccessFields();const role=$('#userEditRole').value,sector=$('#userEditSector').value;const permissions=defaultPermissions(role,sector);$('#permissionChecklist').innerHTML=permissionChecklist(permissions);$('#teacherAccessDesigner').innerHTML=teacherAccessDesigner(permissions);updatePermissionSummary();syncTeacherAccessDesigner()}
function applyPermissionMapToEditor(permissions){$('#permissionChecklist').innerHTML=permissionChecklist(permissions);$('#teacherAccessDesigner').innerHTML=teacherAccessDesigner(permissions);updatePermissionSummary();syncTeacherAccessDesigner()}
function editorPermissionMap(){const permissions=Object.fromEntries(PERMISSION_KEYS.map(key=>[key,false]));$$('[data-permission]').forEach(input=>permissions[input.dataset.permission]=input.checked);return permissions}
function applyAccessProfileToUser(profileId){const profile=findAccessProfile(profileId);if(!profile)return;$('#userEditRole').value=profile.role;$('#userEditSector').value=profile.sector;$('#userEditScope').value=profile.accessScope||profile.access_scope||'own_sector';enforceUserAccessFields();applyPermissionMapToEditor(profile.permissions);toast(`Perfil aplicado: ${profile.name}`)}
async function persistAccessProfiles(){await Storage.save(State.db);logAudit('Atualizou perfis de acesso','Modelos de permissão de usuários');renderPage()}
function editAccessProfile(profileId=''){if(State.user.role!=='direction'||!can('users.edit'))return toast('Operação não autorizada.');const isNew=!profileId,profile=isNew?{id:'',name:'Novo perfil',description:'',role:'teacher',sector:'pedagogico',accessScope:'own_sector',permissions:defaultPermissions('teacher','pedagogico')}:findAccessProfile(profileId);if(!profile)return toast('Perfil não encontrado.');modal(`<div class="user-editor access-profile-editor"><div class="modal-head"><div><span class="eyebrow">${isNew?'Novo perfil de acesso':'Editar perfil de acesso'}</span><h3>${escapeHTML(profile.name)}</h3><p class="helper">Modelo reutilizável para aplicar permissões rapidamente em novos usuários.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div><section class="user-editor-section"><div class="form-grid cols-2"><div class="field"><label>Nome do perfil</label><input id="accessProfileName" value="${escapeHTML(profile.name)}"/></div><div class="field"><label>Descrição</label><input id="accessProfileDescription" value="${escapeHTML(profile.description||'')}"/></div><div class="field"><label>Perfil padrão</label><select id="userEditRole" onchange="App.restoreUserPermissions()"><option value="direction" ${profile.role==='direction'?'selected':''}>Direção</option><option value="leader" ${profile.role==='leader'?'selected':''}>Líder</option><option value="teacher" ${profile.role==='teacher'?'selected':''}>Professor</option><option value="viewer" ${profile.role==='viewer'?'selected':''}>Consulta</option></select></div><div class="field"><label>Setor</label><select id="userEditSector" onchange="App.restoreUserPermissions()"><option value="all" ${profile.sector==='all'?'selected':''}>Todos</option>${['retencao','pedagogico','financeiro'].map(s=>`<option value="${s}" ${profile.sector===s?'selected':''}>${SECTOR_LABELS[s]}</option>`).join('')}</select></div><div class="field"><label>Escopo</label><select id="userEditScope"><option value="own_sector" ${(profile.accessScope||profile.access_scope)!=='all_sectors'?'selected':''}>Próprio setor</option><option value="all_sectors" ${(profile.accessScope||profile.access_scope)==='all_sectors'?'selected':''}>Todos os setores</option></select></div></div></section><div id="teacherAccessDesigner">${teacherAccessDesigner(profile.permissions)}</div><div id="permissionChecklist">${permissionChecklist(profile.permissions)}</div><div class="form-card"><h4>Permissões do perfil</h4><p id="permissionSummary" class="helper">${Object.entries(profile.permissions).filter(x=>x[1]).map(x=>x[0]).join(' • ')||'Nenhuma permissão concedida.'}</p></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Cancelar</button><button class="btn primary" onclick="App.saveAccessProfile('${escapeHTML(profileId)}')">${isNew?'Criar perfil':'Salvar perfil'}</button></div></div>`,false);enforceUserAccessFields();syncTeacherAccessDesigner()}
async function saveAccessProfile(profileId=''){if(State.user.role!=='direction'||!can('users.edit'))return toast('Operação não autorizada.');enforceUserAccessFields();const name=$('#accessProfileName')?.value.trim(),description=$('#accessProfileDescription')?.value.trim()||'',role=$('#userEditRole').value,sector=$('#userEditSector').value,accessScope=$('#userEditScope').value,permissions=editorPermissionMap();if(!name)return toast('Informe o nome do perfil.');if(!validPermissionObject(permissions))return toast('Permissões inválidas.');let profile=findAccessProfile(profileId);if(!profile){profile={id:uid('access-profile'),name,description,role,sector,accessScope,permissions};accessProfiles().push(profile)}else Object.assign(profile,{name,description,role,sector,accessScope,permissions,updatedAt:new Date().toISOString()});closeModal();await persistAccessProfiles();toast(profileId?'Perfil atualizado.':'Perfil criado.')}
async function deleteAccessProfile(profileId){if(State.user.role!=='direction'||!can('users.edit'))return toast('Operação não autorizada.');const profile=findAccessProfile(profileId);if(!profile)return toast('Perfil não encontrado.');if(!confirm(`Excluir o perfil "${profile.name}"? Isso não altera usuários já cadastrados.`))return;State.db.settings.userAccessProfiles=accessProfiles().filter(item=>item.id!==profileId);await persistAccessProfiles();toast('Perfil excluído.')}
function saveCurrentUserPermissionsAsProfile(){const name=prompt('Nome do novo perfil de acesso:');if(!name?.trim())return;const profile={id:uid('access-profile'),name:name.trim(),description:'Criado a partir das permissões selecionadas em um cadastro de usuário.',role:$('#userEditRole').value,sector:$('#userEditSector').value,accessScope:$('#userEditScope').value,permissions:editorPermissionMap(),createdAt:new Date().toISOString()};accessProfiles().push(profile);Storage.save(State.db).then(()=>toast('Perfil salvo para reutilização.')).catch(error=>toast(friendlyError(error,'salvamento do perfil')))}
async function saveUserPermissions(id){
  if(State.user.role!=='direction'||!can('users.edit'))return toast('Operação não autorizada.');
  const isNew=!id,user=isNew?null:State.db.users.find(x=>x.id===id);if(!isNew&&!user)return toast('Usuário não encontrado.');
  enforceUserAccessFields();
  const name=$('#userEditName').value.trim(),email=$('#userEditEmail').value.trim().toLowerCase(),role=$('#userEditRole').value,sector=$('#userEditSector').value,access_scope=$('#userEditScope').value,active=$('#userEditActive').value==='true',job_title=$('#userEditJobTitle').value.trim(),avatar_url=$('#userEditAvatarUrl').value.trim(),teacher_id=$('#userEditTeacherId')?.value||'',password=$('#userEditPassword')?.value||'',passwordConfirm=$('#userEditPasswordConfirm')?.value||'',must_change_password=$('#userMustChangePassword')?.checked===true,permissions=Object.fromEntries(Object.entries(user?.permissions||defaultPermissions(role,sector)).filter(([key,enabled])=>PERMISSION_KEY_SET.has(key)&&typeof enabled==='boolean')),button=$('#saveUserAdminButton');
  $$('[data-permission]').forEach(x=>permissions[x.dataset.permission]=x.checked);
  if(!name||!email)return toast('Informe nome e e-mail.');
  if(!validPermissionObject(permissions))return toast('As permissões informadas são inválidas.');
  if(role==='direction'&&(sector!=='all'||access_scope!=='all_sectors'))return toast('A Direção deve possuir acesso global.');
  if(role==='leader'&&(sector==='all'||access_scope!=='own_sector'))return toast('O líder deve permanecer restrito ao próprio setor.');
  if(role==='teacher'&&(sector!=='pedagogico'||access_scope!=='own_sector'))return toast('O professor deve permanecer restrito ao setor pedagógico.');
  if(role==='viewer'&&access_scope!=='own_sector')return toast('O perfil Consulta deve permanecer restrito ao escopo configurado.');
  if(isNew&&!password)return toast('Informe a senha inicial do usuário.');
  if(password&&password.length<8)return toast('A nova senha deve ter pelo menos 8 caracteres.');
  if(password!==passwordConfirm)return toast('A confirmação da senha não confere.');
  if(!isNew&&password&&!confirm(`Redefinir a senha de ${user.name}?`))return;
  const effectiveAdmins=State.db.users.filter(isEffectiveAdministrator),finalUser={...(user||{}),role,sector,accessScope:access_scope,permissions,active};
  if(!isNew&&isEffectiveAdministrator(user)&&!isEffectiveAdministrator(finalUser)&&effectiveAdmins.length===1)return toast('O último administrador efetivo da Direção deve permanecer ativo, global e com permissão para gerenciar usuários.');
  const body={action:isNew?'create':'update'},assign=(key,value,current)=>{if(isNew||JSON.stringify(value)!==JSON.stringify(current))body[key]=value};
  if(!isNew)body.user_id=id;
  assign('name',name,user?.name);assign('email',email,user?.email);assign('role',role,user?.role);assign('sector',sector,user?.sector);assign('access_scope',access_scope,user?.accessScope);assign('permissions',permissions,user?.permissions||{});assign('active',active,user?.active);assign('job_title',job_title,user?.jobTitle||'');assign('avatar_url',avatar_url,user?.avatarUrl||'');assign('must_change_password',must_change_password,user?.mustChangePassword||false);
  if(password)body.password=password;
  if(!isNew&&Object.keys(body).length===2)return toast('Nenhuma alteração para salvar.');
  button.disabled=true;button.classList.add('loading');
  try{
    const {data,error}=await Supabase.functions.invoke('admin-manage-user',{body});
    if(error){let message='Não foi possível atualizar o usuário.';try{message=(await error.context.json())?.error||message}catch{}throw new Error(message)}
    if(data?.error)throw new Error(data.error);
    const profile=data.profile||{},profilePatch={id:profile.id??id,name:profile.name??name,email:profile.email??email,role:profile.role??role,sector:profile.sector??sector,accessScope:profile.access_scope??access_scope,permissions:profile.permissions??permissions,active:profile.active??active,jobTitle:profile.job_title??job_title,avatarUrl:profile.avatar_url??avatar_url,mustChangePassword:profile.must_change_password??must_change_password,teacherId:teacher_id};
    const savedUser=isNew?profilePatch:user;Object.assign(savedUser,profilePatch);if(isNew)State.db.users.push(savedUser);
    const links=userTeacherLinks();if(teacher_id)links[savedUser.id]=teacher_id;else delete links[savedUser.id];await Storage.save(State.db).catch(error=>console.warn('Purple Gestão — vínculo user/teacher local:',error));
    const selfUpdated=savedUser.id===State.user.id;
    if(selfUpdated){Object.assign(State.user,profilePatch);State.sector=State.user.accessScope==='all_sectors'?'integrado':State.user.sector;$('#userName').textContent=State.user.name;$('#userAvatar').textContent=State.user.name.charAt(0).toUpperCase();$('#userAccess').textContent=State.user.role==='direction'?'Acesso geral':State.user.role==='viewer'?'Somente consulta':`Acesso: ${SECTOR_LABELS[State.user.sector]}`;renderSectorSwitcher();renderNav()}
    logAudit(isNew?'Criou usuário':'Atualizou usuário',`${savedUser.name} • ${ROLE_LABELS[savedUser.role]}`);closeModal();toast(isNew?'Usuário criado com senha inicial.':password?'Usuário e senha atualizados.':'Usuário atualizado com sucesso.');
    if(selfUpdated&&!State.user.active)return logout();
    if(selfUpdated&&!can('users.view'))return go('home');
    renderPage();
  }catch(e){console.error('Purple Gestão — atualização de usuário:',e);toast(e.message||'Não foi possível atualizar o usuário.')}
  finally{button.disabled=false;button.classList.remove('loading')}
}
async function deleteUser(id){if(State.user.role!=='direction'||!can('users.edit'))return toast('Operação não autorizada.');const user=State.db.users.find(item=>item.id===id);if(!user)return toast('Usuário não encontrado.');if(user.id===State.user.id)return toast('Você não pode excluir o próprio usuário logado.');const effectiveAdmins=State.db.users.filter(isEffectiveAdministrator);if(isEffectiveAdministrator(user)&&effectiveAdmins.length===1)return toast('O último administrador efetivo da Direção não pode ser excluído.');if(!confirm(`Excluir definitivamente ${user.name}? O login e o perfil serão removidos.`))return;try{const {data,error}=await Supabase.functions.invoke('admin-manage-user',{body:{action:'delete',user_id:id}});if(error){let message='Não foi possível excluir o usuário.';try{message=(await error.context.json())?.error||message}catch{}throw new Error(message)}if(data?.error)throw new Error(data.error);State.db.users=State.db.users.filter(item=>item.id!==id);logAudit('Excluiu usuário',`${user.name} • ${user.email}`);renderPage();toast('Usuário excluído.')}catch(error){console.error('Purple Gestão — exclusão de usuário:',error);toast(error.message||'Não foi possível excluir o usuário.')}}
