async function saveFinancialEntryLegacy5(type,id=''){if(!can('financial.transactions.create'))return toast('Operação não autorizada.');const studentId=$('#financialPinnedStudentId')?.value||$('#financialStudentId')?.value||'';const student=(State.db.students||[]).find(item=>item.id===studentId);const chargeType=normalizeChargeTypeValue($('#financialCategory')?.value||'OUTRO');const value=Number($('#financialAmount')?.value||0);const dueDate=$('#financialDueDate')?.value||'';const billingType=String($('#financialPaymentMethod')?.value||'PIX').toUpperCase();const competence=$('#financialCompetence')?.value||'';const description=upperFormValue($('#financialDescription')?.value)||`${chargeTypeLabel(chargeType)} - ${student?.name||''}`;if(!studentId||!student)return toast('Selecione o aluno.');if(!['PIX','BOLETO'].includes(billingType))return toast('A forma deve ser PIX ou BOLETO.');if(!value||value<=0)return toast('Informe um valor válido.');if(!dueDate)return toast('Informe o vencimento.');const button=$('#financialSubmitButton');const originalLabel=button?.innerHTML||'Gerar cobrança';button&&(button.disabled=true,button.classList.add('loading'),button.innerHTML='Gerando cobrança no Asaas...');try{const {data,error}=await Supabase.functions.invoke('asaas-create-charge',{body:{studentId,chargeType,value,dueDate,billingType,description,competence}});if(error)throw error;if(data?.error)throw new Error(data.error);const charge=data?.charge||null;if(!charge?.id)throw new Error('Cobrança criada sem retorno válido.');State.db.financialEntries=State.db.financialEntries||[];const entry={id:charge.id,supabaseId:charge.id,type:'receivable',studentId,person:student.name,student:student.name,description:charge.description,category:chargeTypeLabel(charge.chargeType),subaccount:chargeTypeLabel(charge.chargeType),competence:charge.competence||competence,dueDate:charge.dueDate,amount:Number(charge.value||0),paidAmount:0,paidDate:'',paymentMethod:charge.billingType,status:String(charge.status||'PENDING').toLowerCase()==='paid'?'paid':'pending',invoiceUrl:charge.invoiceUrl||'',bankSlipUrl:charge.bankSlipUrl||'',digitableLine:charge.digitableLine||'',pixCopyPaste:charge.pixCopyPaste||'',pixQrCode:charge.pixQrCode||'',externalChargeId:charge.externalChargeId||'',account:'ASAAS',active:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};State.db.financialEntries=mergeRecords(State.db.financialEntries,[entry]);closeModal();renderPage();requestAnimationFrame(()=>openFinancialChargeResultModal(entry,student))}catch(error){console.error('Purple Gestão — erro ao criar cobrança Asaas:',error);toast(humanizeFinancialError(error))}finally{if(button){button.disabled=false;button.classList.remove('loading');button.innerHTML=originalLabel}}}
function openFinancialActionLegacy2(action,id){const item=financialEntries('all').find(entry=>entry.id===id);if(!item)return toast('Cobrança não encontrada.');if(action==='copyPix')return financialClipboardCopy(item.pixCopyPaste,'PIX copiado.');if(action==='copyLine')return financialClipboardCopy(item.digitableLine,'Linha digitável copiada.');if(action==='copyLink')return financialClipboardCopy(item.invoiceUrl||item.bankSlipUrl,'Link de pagamento copiado.');if(action==='openCharge'&&(item.invoiceUrl||item.bankSlipUrl))return window.open(item.invoiceUrl||item.bankSlipUrl,'_blank','noopener');if(action==='openBoleto'&&item.bankSlipUrl)return window.open(item.bankSlipUrl,'_blank','noopener');if(action==='viewPix'){const qrImage=financialQrImageSrc(item.pixQrCode||'');return modal(`<div class="modal-head"><div><span class="eyebrow">PIX</span><h3>${escapeHTML(item.person||'Cobrança')}</h3><p class="helper" style="margin-top:6px">Compartilhe o QR Code, o copia e cola ou o link de pagamento.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div>${qrImage?`<div class="student-financial-qr"><img src="${qrImage}" alt="QR Code PIX da cobrança"/></div>`:''}<div class="field"><label>PIX copia e cola</label><textarea readonly>${escapeHTML(item.pixCopyPaste||'')}</textarea></div><div class="section-actions" style="justify-content:flex-start"><button class="btn primary" onclick="App.openFinancialAction('copyPix','${item.id}')">Copiar PIX</button>${item.invoiceUrl?`<button class="btn ghost" onclick="App.openFinancialAction('copyLink','${item.id}')">Copiar link</button><button class="btn ghost" onclick="App.openFinancialAction('openCharge','${item.id}')">Abrir cobrança</button>`:''}</div>`,true)}toast('Ação indisponível para esta cobrança.')}
