function studentPaymentsContentFullLegacy4(s){const financial=studentFinancialTotals(s),rows=financial.rows,nextDue=financial.nextDue;return `<div class="student-financial-panel"><section class="student-financial-hero"><div><span class="eyebrow">Central financeira individual</span><h3>Pagamentos de ${escapeHTML(s.name||'aluno')}</h3><p class="helper">Tudo que este aluno deve, já pagou ou ainda precisa receber fica centralizado aqui.</p></div><div class="section-actions">${can('financial.transactions.create')?`<button class="btn primary" onclick="App.editFinancialEntry('receivable','','${s.id}')">+ Nova cobrança</button>`:''}<button class="btn ghost" onclick="App.openStudent('${s.id}');App.setStudentTab('payments')">Atualizar histórico</button></div></section><section class="student-financial-stat-grid">${financialStudentCard('Total do contrato',fmtMoney(financial.total),`${fmtNumber(rows.length)} cobrança(s)`,'neutral')}${financialStudentCard('Total pago',fmtMoney(financial.paid),`${fmtNumber(financial.paidRows.length)} pagamento(s) confirmados`,'positive')}${financialStudentCard('Em aberto',fmtMoney(financial.open),`${fmtNumber(financial.openRows.length)} cobrança(s) ativas`,'accent')}${financialStudentCard('Vencido',fmtMoney(financial.overdue),financial.overdueRows.length?`${fmtNumber(financial.overdueRows.length)} cobrança(s) vencida(s)`:'Nenhuma cobrança vencida','danger')}${financialStudentCard('Próximo vencimento',nextDue?fmtDate(nextDue.dueDate):'—',nextDue?`${fmtMoney(financial.nextDueAmount)} • ${escapeHTML(nextDue.description||chargeTypeLabel(nextDue.category||''))}`:'Sem parcelas futuras','soft')}</section><section class="student-financial-config-grid"><article class="form-card student-financial-config-card"><div class="panel-head"><div><h3>Configuração financeira</h3><small>Dados padrão usados pela equipe no momento da geração.</small></div><span class="status ${String(s.financialStatus||'').toLowerCase()==='em dia'?'approved':'draft'}">${escapeHTML(s.financialStatus||'EM DIA')}</span></div><div class="kpi-strip"><span><b>Forma padrão:</b> ${escapeHTML(studentFinancialDefaultMethod(s))}</span><span><b>Dia de vencimento:</b> ${s.financeDueDay?`Dia ${fmtNumber(s.financeDueDay)}`:'Não definido'}</span><span><b>Mensalidade padrão:</b> ${fmtMoney(s.financeMonthlyValue||0)}</span><span><b>Responsável financeiro:</b> ${escapeHTML(s.financialResponsibleName||s.guardian||'—')}</span></div>${s.financeNotes?`<p class="muted student-financial-note">${escapeHTML(s.financeNotes)}</p>`:''}</article><article class="form-card student-financial-config-card"><div class="panel-head"><div><h3>Resumo operacional</h3><small>Leitura rápida para o atendimento e o financeiro.</small></div></div><div class="student-financial-highlights"><span class="${financial.overdueRows.length?'danger':'positive'}">${financial.overdueRows.length?'Cobrança vencida exige ação':'Carteira sem atraso ativo'}</span><span>${nextDue?`Próxima cobrança em ${fmtDate(nextDue.dueDate)}`:'Nenhum vencimento futuro'}</span><span>${financial.paidRows.length?`${fmtNumber(financial.paidRows.length)} pagamento(s) já reconciliados`:'Ainda sem pagamento confirmado'}</span></div></article></section><section class="form-card"><div class="panel-head"><div><h3>Histórico financeiro do aluno</h3><small>Cobranças criadas, status, forma de pagamento e ações seguras.</small></div></div><div class="table-wrap student-financial-table"><table><thead><tr><th>Competência</th><th>Descrição</th><th>Vencimento</th><th>Valor</th><th>Forma</th><th>Status</th><th>Pagamento</th><th>Ações</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${escapeHTML(financialCompetenceLabel(x.competence))}</td><td><div class="student-financial-row-title"><strong>${escapeHTML(x.description||chargeTypeLabel(x.category||''))}</strong><small>${escapeHTML(x.subaccount||chargeTypeLabel(x.category||''))}</small></div></td><td>${fmtDate(x.dueDate||x.date||x.createdAt)}</td><td>${fmtMoney(x.amount||x.value||0)}</td><td>${escapeHTML(x.paymentMethod||'—')}</td><td><span class="status ${financialStatusTone(financialStatusFor(x))}">${escapeHTML(FINANCIAL_STATUS[financialStatusFor(x)]||x.status||'—')}</span></td><td>${financialStatusFor(x)==='paid'?fmtDate(x.paidDate):'—'}</td><td><div class="table-actions">${studentFinancialQuickActions(x)}</div></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty"><p>Nenhuma cobrança cadastrada para este aluno.</p></div></td></tr>'}</tbody></table></div></section></div>`}
function studentDetailContentNextV2Legacy4(s){const tab=State.studentTab&&State.studentTab!=='search'?State.studentTab:'profile';if(tab==='profile')return studentDataContentFull(s);if(tab==='courses')return studentCoursesContentFull(s,studentFinancialTotals(s));if(tab==='payments')return studentPaymentsContentFull(s);if(tab==='schedule')return studentScheduleContent(s);if(tab==='frequency')return studentAttendanceContent(s);if(tab==='grades')return studentGradesContent(s);if(tab==='contacts')return studentContactsContentFull(s);return studentDataContentFull(s)}

