function editFinancialEntryLegacy6(type,id='',forcedStudentId=''){if(!can(id?'financial.transactions.edit':'financial.transactions.create'))return toast('Operação não autorizada.');const item=id?financialEntries('all').find(x=>x.id===id):null;if(item&&financialStatusFor(item)==='paid')return openFinancialDetails(id);const student=item?(State.db.students||[]).find(x=>x.id===item.studentId):(State.db.students||[]).find(x=>x.id===forcedStudentId),pinned=Boolean(student),full=item?.fullValue??item?.amount??student?.financeFullValue??student?.financeMonthlyValue??0,punctual=item?.punctualValue??student?.financePunctualValue??student?.financeMonthlyValue??full,due=item?.dueDate||financialDueDateSuggestion(student||{}),category=normalizeChargeTypeValue(item?.chargeType||item?.category||'MENSALIDADE');State.financialScheduleOpen=false;modal(`<div class="financial-charge-modal"><div class="modal-head"><div><span class="eyebrow">Central financeira</span><h3>${item?'Editar cobrança':'Nova cobrança'}</h3><p class="helper">${item?'Altere somente cobranças pendentes ou vencidas.':'Competência, descrição e parcelas são calculadas automaticamente.'}</p></div><button class="modal-close" aria-label="Fechar" onclick="App.closeModal()">×</button></div>${pinned?`<div class="student-financial-student-chip"><b>${escapeHTML(student.name)}</b><span>${escapeHTML(studentFinancialDefaultMethod(student))} · vencimento padrão ${student.financeDueDay?`dia ${student.financeDueDay}`:'não definido'}</span><input type="hidden" id="financialPinnedStudentId" value="${escapeHTML(student.id)}"/></div>`:`<div class="field"><label for="financialStudentId">Aluno</label><select id="financialStudentId" onchange="App.updateFinancialStudentDefaults()"><option value="">Selecione</option>${financialStudentOptions()}</select></div>`}<div class="form-grid cols-2"><div class="field"><label for="financialCategory">Tipo de cobrança</label><select id="financialCategory" onchange="App.refreshFinancialPreview()">${FINANCIAL_CHARGE_TYPES.map(([value,label])=>`<option value="${value}" ${value===category?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="financialPaymentMethod">Forma de pagamento</label><select id="financialPaymentMethod" onchange="App.refreshFinancialPreview()"><option value="PIX" ${(item?.paymentMethod||studentFinancialDefaultMethod(student||{}))==='PIX'?'selected':''}>PIX</option><option value="BOLETO" ${(item?.paymentMethod||studentFinancialDefaultMethod(student||{}))==='BOLETO'?'selected':''}>Boleto</option></select></div>${financialMoneyInput('financialFullValue','Valor integral',full)}${financialMoneyInput('financialPunctualValue','Valor com desconto até o vencimento',punctual)}<div class="field"><label for="financialInstallmentCount">Quantidade de parcelas</label><div class="financial-stepper"><button type="button" aria-label="Diminuir parcelas" onclick="App.changeFinancialInstallmentCount(-1)" ${item?'disabled':''}>−</button><input id="financialInstallmentCount" type="number" min="1" max="24" value="${item?1:1}" onchange="App.refreshFinancialPreview()" ${item?'disabled':''}/><button type="button" aria-label="Aumentar parcelas" onclick="App.changeFinancialInstallmentCount(1)" ${item?'disabled':''}>+</button></div></div><div class="field"><label for="financialDueDate">${item?'Vencimento':'Primeiro vencimento'}</label><input id="financialDueDate" type="date" value="${due}" onchange="App.refreshFinancialPreview()"/></div></div><div id="financialChargePreview" class="financial-charge-preview" aria-live="polite"></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Voltar</button><button class="btn primary" id="financialSubmitButton" onclick="App.saveFinancialEntry('receivable','${item?.id||''}')">${item?'Salvar alterações':'Gerar cobrança'}</button></div></div>`,true);requestAnimationFrame(()=>{refreshFinancialPreview();(pinned?$('#financialCategory'):$('#financialStudentId'))?.focus()})}
async function saveFinancialEntryLegacy6(type,id=''){const item=id?financialEntries('all').find(x=>x.id===id):null;if(!can(item?'financial.transactions.edit':'financial.transactions.create'))return toast('Operação não autorizada.');const studentId=$('#financialPinnedStudentId')?.value||$('#financialStudentId')?.value||item?.studentId||'',student=(State.db.students||[]).find(x=>x.id===studentId);if(!student)return toast('Selecione o aluno.');const schedule=financialScheduleFromForm();if(!schedule[0]?.fullValue||schedule[0].punctualValue>schedule[0].fullValue)return toast('Revise os valores da cobrança.');const button=$('#financialSubmitButton'),label=button?.textContent||'Salvar';if(button?.disabled)return;button&&(button.disabled=true,button.classList.add('loading'));try{if(item){const row=schedule[0],{data,error}=await Supabase.functions.invoke('asaas-manage-charge',{body:{action:'update',chargeId:item.supabaseId||item.id,fullValue:row.fullValue,punctualValue:row.punctualValue,dueDate:row.dueDate,billingType:row.billingType,description:row.description,chargeType:row.chargeType,competence:row.competence}});if(error||data?.error)throw new Error(data?.error||error?.message);Object.assign(item,{fullValue:row.fullValue,amount:row.fullValue,punctualValue:row.punctualValue,discountValue:row.discountValue,dueDate:row.dueDate,discountDueDate:row.dueDate,paymentMethod:row.billingType,description:row.description,competence:row.competence,chargeType:row.chargeType,updatedAt:new Date().toISOString()});await logAudit('Atualizou cobrança',`${student.name} · ${row.description} · ${fmtMoney(row.fullValue)}`);closeModal();renderPage();return toast('Cobrança atualizada no Purple Gestão e no Asaas.')}const groupId=crypto.randomUUID(),batchKey=`pg-batch-${crypto.randomUUID()}`,created=[],failed=[];button&&(button.textContent=`Gerando 0/${schedule.length}...`);for(const row of schedule){try{const {data,error}=await Supabase.functions.invoke('asaas-create-charge',{body:{studentId,...row,idempotencyKey:`${batchKey}-${row.installmentNumber}`,installmentGroupId:groupId}});if(error||data?.error)throw new Error(data?.error||error?.message);const entry=financialEntryFromCharge(data.charge,student);created.push(entry);State.db.financialEntries=mergeRecords(State.db.financialEntries||[],[entry])}catch(error){failed.push({row,error:String(error?.message||error)});break}button&&(button.textContent=`Gerando ${created.length}/${schedule.length}...`)}closeModal();renderPage();await logAudit('Gerou cobranças em lote',`${student.name} · ${created.length} criada(s) · ${schedule.length-created.length} pendente(s)`);if(failed.length)return modal(`<div class="modal-head"><div><span class="eyebrow">Falha parcial</span><h3>${created.length} criada(s), ${schedule.length-created.length} não criada(s)</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><p class="helper">As cobranças confirmadas foram preservadas. As demais não foram marcadas como criadas e podem ser tentadas novamente com conferência.</p><div class="alert red"><div class="alert-icon">!</div><div><b>Interrupção na parcela ${failed[0].row.installmentNumber}/${failed[0].row.installmentTotal}</b><span>${escapeHTML(failed[0].error)}</span></div></div>`,true);created.length===1?requestAnimationFrame(()=>openFinancialChargeResultModal(created[0],student)):toast(`${created.length} cobranças criadas com sucesso.`)}catch(error){console.error('Purple Gestão — financeiro:',error);toast(humanizeFinancialError(error))}finally{if(button){button.disabled=false;button.classList.remove('loading');button.textContent=label}}}
function openFinancialDetailsLegacy2(id){const item=(State.db.financialEntries||[]).find(x=>x.id===id);if(!item)return toast('Cobrança não encontrada.');const paid=financialStatusFor(item)==='paid';modal(`<div class="modal-head"><div><span class="eyebrow">${financialOriginLabel(item)}</span><h3>${escapeHTML(item.description||'Cobrança')}</h3><p class="helper">${financialInstallmentLabel(item)} · ${escapeHTML(item.person||item.student||'')}</p></div><button class="modal-close" aria-label="Fechar" onclick="App.closeModal()">×</button></div><div class="student-financial-detail-grid"><div class="student-financial-detail-card"><span>Valor integral</span><strong>${fmtMoney(item.fullValue??item.amount)}</strong></div><div class="student-financial-detail-card"><span>${paid?'Valor pago':'Valor devido agora'}</span><strong>${fmtMoney(paid?(item.paidAmount??item.amount):financialCurrentValue(item))}</strong></div><div class="student-financial-detail-card"><span>Vencimento</span><strong>${fmtDate(item.dueDate)}</strong></div><div class="student-financial-detail-card"><span>Status</span><strong>${FINANCIAL_STATUS[financialStatusFor(item)]}</strong></div><div class="student-financial-detail-card"><span>Forma</span><strong>${escapeHTML(item.paymentMethod||'—')}</strong></div><div class="student-financial-detail-card"><span>ID externo</span><strong>${escapeHTML(item.externalChargeId||'Sem cobrança externa')}</strong></div></div>${paid?'<p class="financial-rule-note">Pagamento confirmado: valores, data e identificadores ficam congelados como fato histórico.</p>':''}`,true)}
