function financialPrimaryLinkLegacy3(item={}){return item.invoiceUrl||item.bankSlipUrl||item.paymentUrl||item.checkoutUrl||item.link||item.url||''}
function financialExternalCodeLegacy3(item={}){return item.externalChargeId||item.asaasChargeId||item.supabaseId||item.id||''}
function openFinancialActionLegacy3(action,id){const item=financialEntries('all').find(entry=>entry.id===id);if(!item)return toast('Cobrança não encontrada.');const link=financialPrimaryLink(item);if(action==='copyPix')return financialClipboardCopy(item.pixCopyPaste,'PIX copiado.');if(action==='copyLine')return financialClipboardCopy(item.digitableLine,'Linha digitável copiada.');if(action==='copyCode')return financialClipboardCopy(financialExternalCode(item),'Código da cobrança copiado.');if(action==='copyLink')return financialClipboardCopy(link,'Link de pagamento copiado.');if(action==='openCharge'&&link)return window.open(link,'_blank','noopener');if(action==='openBoleto'&&(item.bankSlipUrl||link))return window.open(item.bankSlipUrl||link,'_blank','noopener');if(action==='viewPix'){const qrImage=financialQrImageSrc(item.pixQrCode||'');return modal(`<div class="modal-head"><div><span class="eyebrow">PIX</span><h3>${escapeHTML(item.person||'Cobrança')}</h3><p class="helper" style="margin-top:6px">Compartilhe o QR Code, o copia e cola ou o link de pagamento.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div>${qrImage?`<div class="student-financial-qr"><img src="${qrImage}" alt="QR Code PIX da cobrança"/></div>`:''}<div class="field"><label>PIX copia e cola</label><textarea readonly>${escapeHTML(item.pixCopyPaste||'')}</textarea></div><div class="section-actions" style="justify-content:flex-start"><button class="btn primary" onclick="App.openFinancialAction('copyPix','${item.id}')">Copiar PIX</button>${link?`<button class="btn ghost" onclick="App.openFinancialAction('copyLink','${item.id}')">Copiar link</button><button class="btn ghost" onclick="App.openFinancialAction('openCharge','${item.id}')">Abrir cobrança</button>`:''}</div>`,true)}toast('Ação indisponível para esta cobrança.')}
function studentFinancialQuickActionsLegacy4(item){if(!item)return '<span class="muted">Sem ação</span>';const id=item.id,status=financialStatusFor(item),paid=status==='paid',asaas=financialIsAsaas(item),link=financialPrimaryLink(item),actions=[];if(!paid)actions.push(`<button onclick="App.editFinancialEntry('receivable','${id}','${item.studentId||''}')">Editar cobrança</button>`);if(link)actions.push(`<button onclick="App.openFinancialAction('openCharge','${id}')">Abrir cobrança</button>`,`<button onclick="App.openFinancialAction('copyLink','${id}')">Copiar link</button>`);actions.push(`<button onclick="App.openFinancialAction('copyCode','${id}')">Copiar código</button>`);if(item.bankSlipUrl)actions.push(`<button onclick="App.openFinancialAction('openBoleto','${id}')">Abrir boleto</button>`);if(item.digitableLine)actions.push(`<button onclick="App.openFinancialAction('copyLine','${id}')">Copiar linha digitável</button>`);if(item.pixCopyPaste)actions.push(`<button onclick="App.openFinancialAction('copyPix','${id}')">Copiar PIX</button>`);if(!paid&&asaas)actions.push(`<button class="danger" onclick="App.confirmCancelFinancialCharge('${id}')">Cancelar / excluir cobrança</button>`);if(!paid&&!asaas)actions.push(`<button class="danger" onclick="App.archiveHistoricalPayment('${id}')">Excluir / arquivar registro</button>`);if(paid)actions.push('<button disabled>Pagamento protegido</button>');return `<button class="btn ghost small" onclick="App.openFinancialDetails('${id}')">Detalhes</button><details class="financial-actions-menu"><summary aria-label="Mais ações" title="Mais ações">⋯</summary><div>${actions.join('')}</div></details>`}
function studentPaymentsContentFullLegacy5(s){const f=studentFinancialTotals(s),rows=f.rows,next=f.nextDue,economy=Math.max(0,f.totalFull-f.totalPunctual);return `<div class="student-financial-panel"><section class="student-financial-hero"><div><span class="eyebrow">Central financeira individual</span><h3>${escapeHTML(s.name)}</h3><p class="helper">Contrato, cobranças Asaas e fatos históricos em uma única leitura.</p></div><div class="section-actions">${can('financial.transactions.create')?`<button class="btn ghost" onclick="App.openHistoricalPayment('${s.id}')">Registrar pagamento anterior</button><button class="btn primary" onclick="App.editFinancialEntry('receivable','','${s.id}')">+ Nova cobrança</button>`:''}</div></section><section class="student-financial-stat-grid">${financialStudentCard('Valor integral',fmtMoney(f.totalFull),`${fmtMoney(f.totalPunctual)} com pontualidade · economia ${fmtMoney(economy)}`,'neutral')}${financialStudentCard('Pago',fmtMoney(f.paid),`${f.paidRows.length} pagamento(s) pelo valor realmente recebido`,'positive')}${financialStudentCard('Em aberto',fmtMoney(f.open),`${f.openRows.length} cobrança(s) dentro do prazo`,'accent')}${financialStudentCard('Vencido',fmtMoney(f.overdue),f.overdueRows.length?`${f.overdueRows.length} cobrança(s) com desconto expirado`:'Nenhum atraso','danger')}${financialStudentCard('Próximo',next?fmtDate(next.dueDate):'—',next?`${fmtMoney(f.nextDueAmount)} até a data · integral ${fmtMoney(next.fullValue??next.amount)}`:'Sem vencimento futuro','soft')}</section><section class="student-financial-config-grid"><article class="form-card student-financial-config-card"><div class="panel-head"><div><h3>Configuração financeira</h3><small>Padrões usados para pré-preencher novas cobranças.</small></div></div><div class="kpi-strip"><span><b>Forma:</b> ${escapeHTML(studentFinancialDefaultMethod(s))}</span><span><b>Vencimento:</b> ${s.financeDueDay?`dia ${s.financeDueDay}`:'não definido'}</span><span><b>Integral:</b> ${fmtMoney(s.financeFullValue||s.financeMonthlyValue||0)}</span><span><b>Pontual:</b> ${fmtMoney(s.financePunctualValue||s.financeMonthlyValue||0)}</span><span><b>Responsável:</b> ${escapeHTML(s.financialResponsibleName||s.guardian||'—')}</span></div></article><article class="form-card student-financial-config-card"><div class="panel-head"><div><h3>Resumo operacional</h3><small>Valores pendentes mudam com o vencimento; fatos pagos ficam congelados.</small></div></div><div class="student-financial-highlights"><span class="${f.overdueRows.length?'danger':'positive'}">${f.overdueRows.length?'Há desconto expirado':'Sem atraso ativo'}</span><span>${next?`Próxima cobrança em ${fmtDate(next.dueDate)}`:'Nenhum vencimento futuro'}</span><span>${f.paidRows.length?`${f.paidRows.length} pagamento(s) conciliado(s)`:'Ainda sem pagamento confirmado'}</span></div></article></section><section class="form-card"><div class="panel-head"><div><h3>Histórico financeiro</h3><small>Ações secundárias foram agrupadas no menu ⋯.</small></div></div><div class="student-financial-history">${rows.map(x=>{const status=financialStatusFor(x),paid=status==='paid',due=paid?Number(x.paidAmount??x.amount):financialCurrentValue(x);return `<article class="student-financial-history-row"><div class="student-financial-row-title"><strong>${escapeHTML(x.description||chargeTypeLabel(x.category||''))}</strong><small>${financialInstallmentLabel(x)} · ${escapeHTML(x.subaccount||chargeTypeLabel(x.category||''))} ${financialOriginLabel(x)==='MIGRAÇÃO'?'<span class="badge">MIGRAÇÃO</span>':''}</small></div><div><small>Vencimento</small><b>${fmtDate(x.dueDate)}</b></div><div><small>${paid?'Pago':'Devido agora'}</small><b>${fmtMoney(due)}</b><em>${!paid&&status==='pending'&&Number(x.fullValue||x.amount)>due?`Integral ${fmtMoney(x.fullValue||x.amount)}`:!paid&&status==='overdue'?'desconto expirado':''}</em></div><div><span class="status ${financialStatusTone(status)}">${FINANCIAL_STATUS[status]||status}</span>${paid?`<small>${fmtDate(x.paidDate)}</small>`:''}</div><div class="table-actions">${studentFinancialQuickActions(x)}</div></article>`}).join('')||'<div class="empty"><p>Nenhuma cobrança cadastrada para este aluno.</p></div>'}</div></section></div>`}
function studentDetailContentNextV2(s){const tab=State.studentTab&&State.studentTab!=='search'?State.studentTab:'profile';if(tab==='profile')return studentDataContentFull(s);if(tab==='courses')return studentCoursesContentFull(s,studentFinancialTotals(s));if(tab==='payments')return studentPaymentsContentFull(s);if(tab==='schedule')return studentScheduleContent(s);if(tab==='frequency')return studentAttendanceContent(s);if(tab==='grades')return studentGradesContent(s);if(tab==='contacts')return studentContactsContentFull(s);return studentDataContentFull(s)}

/* Override autoritativo final — Financeiro individual do aluno deve vencer todos os blocos legados acima. */
function formatBRL(value){return window.PurpleFinancial.moneyFromCents(window.PurpleFinancial.cents(value))}
function parseBRLInput(value){return window.PurpleFinancial.decimal(window.PurpleFinancial.cents(value))}
function formatFinancialMoneyInput(input){const digits=String(input?.value||'').replace(/\D/g,'').slice(0,12),value=Number(digits||0);input.dataset.cents=String(value);input.value=window.PurpleFinancial.moneyFromCents(value).replace(/^R\$\s?/,'').trim()}
function financialMoneyInput(id,label,value,extra=''){const centsValue=window.PurpleFinancial.cents(value);return `<div class="field financial-money-field"><label for="${id}">${label}</label><div class="brl-input-wrap"><span>R$</span><input class="financial-money-input" id="${id}" inputmode="decimal" autocomplete="off" value="${escapeHTML(window.PurpleFinancial.moneyFromCents(centsValue).replace(/^R\\$\\s?/,'').trim())}" data-cents="${centsValue}" oninput="App.formatFinancialMoneyInput(this);App.refreshFinancialPreview()" ${extra}/></div></div>`}
function financialReadMoney(id){return window.PurpleFinancial.decimal(Number($(`#${id}`)?.dataset?.cents||window.PurpleFinancial.cents($(`#${id}`)?.value||0)))}
function financialCompetenceFromDue(dueDate=''){return window.PurpleFinancial.competence(dueDate)}
function financialCompetenceHuman(value=''){const source=/^\d{4}-\d{2}-\d{2}$/.test(String(value))?String(value).slice(0,7):String(value||'');return /^\d{4}-\d{2}$/.test(source)?`${source.slice(5,7)}/${source.slice(0,4)}`:'—'}
function financialDescriptionFromParts(type,dueDate,installmentNumber=1,installmentTotal=1){const base=window.PurpleFinancial.description(type,dueDate);return Number(installmentTotal)>1?`${base} · ${installmentNumber}/${installmentTotal}`:base}
function financialStatusFor(item={}){const status=String(item.status||'').toLowerCase();if(['paid','pago'].includes(status))return 'paid';if(['cancelled','canceled','cancelado','archived','deleted','void'].includes(status))return 'cancelled';if(['refunded','estornado'].includes(status))return 'refunded';if(['sync_error','erro de sincronização','erro de sincronizacao'].includes(status))return 'sync_error';if(item.dueDate&&item.dueDate<todayISO()&&status!=='paid')return 'overdue';return 'pending'}
function financialStatusLabel(status){return {paid:'PAGO',pending:'EM ABERTO',overdue:'VENCIDO',cancelled:'CANCELADO',refunded:'ESTORNADO',sync_error:'ERRO DE SINCRONIZAÇÃO'}[status]||String(status||'AGUARDANDO').toUpperCase()}
function financialStatusTone(status='pending'){return status==='paid'?'approved':status==='overdue'?'adjust':status==='cancelled'?'archived':status==='refunded'?'review':status==='sync_error'?'danger':'draft'}
function financialOriginLabel(item={}){return ['HISTORICAL','MIGRATION','MANUAL_HISTORY','LEGACY'].includes(String(item.origin||'').toUpperCase())?'HISTÓRICO':'ASAAS'}
function financialIsAsaasLegacy4(item={}){const origin=String(item.origin||item.provider||item.account||'').toUpperCase();return origin.includes('ASAAS')||Boolean(item.externalChargeId||item.asaasChargeId||item.invoiceUrl||item.bankSlipUrl||item.pixCopyPaste||item.pixQrCode||item.digitableLine)}
function financialPrimaryLinkLegacy4(item={}){return item.invoiceUrl||item.bankSlipUrl||item.paymentUrl||item.checkoutUrl||item.link||item.url||''}
function financialExternalCodeLegacy4(item={}){return item.externalChargeId||item.asaasChargeId||item.supabaseId||item.id||''}
function financialInstallmentLabel(item={}){return item.installmentNumber&&item.installmentTotal?`${item.installmentNumber}/${item.installmentTotal}`:'Parcela única'}
function financialCurrentValue(item={}){
  const engine=window.PurpleFinancial;
  if(engine?.decimal&&engine?.dueCents)return engine.decimal(engine.dueCents(item,todayISO()));
  const status=financialStatusFor(item);
  const gross=Number(item.fullValue??item.amount??item.value??0);
  const discounted=Number(item.punctualValue??item.amount??item.value??0);
  const base=status==='overdue'?gross:discounted;
  return Math.max(0,base-Number(item.paidAmount||0));
}
function studentFinancialTotals(s){
  const rows=studentMoneyRows(s),engine=window.PurpleFinancial;
  if(engine?.summary)return engine.summary(rows,todayISO());
  const paidRows=rows.filter(item=>financialStatusFor(item)==='paid'),openRows=rows.filter(item=>financialStatusFor(item)==='pending'),overdueRows=rows.filter(item=>financialStatusFor(item)==='overdue'),cancelledRows=rows.filter(item=>financialStatusFor(item)==='cancelled'),paid=paidRows.reduce((sum,item)=>sum+Number(item.paidAmount||0),0),totalFull=rows.reduce((sum,item)=>sum+Number(item.fullValue??item.amount??item.value??0),0),totalPunctual=rows.reduce((sum,item)=>sum+Number(item.punctualValue??item.amount??item.value??0),0),open=openRows.reduce((sum,item)=>sum+Math.max(0,Number(item.punctualValue??item.amount??item.value??0)-Number(item.paidAmount||0)),0),overdue=overdueRows.reduce((sum,item)=>sum+Math.max(0,Number(item.fullValue??item.amount??item.value??0)-Number(item.paidAmount||0)),0),nextDue=[...openRows,...overdueRows].sort((a,b)=>String(a.dueDate||'').localeCompare(String(b.dueDate||'')))[0]||null;
  return {rows,paid,total:totalFull,totalFull,totalPunctual,open,overdue,paidRows,openRows,overdueRows,cancelledRows,nextDue,nextDueAmount:nextDue?Math.max(0,Number((financialStatusFor(nextDue)==='overdue'?nextDue.fullValue:nextDue.punctualValue)??nextDue.amount??nextDue.value??0)-Number(nextDue.paidAmount||0)):0};
}
function financialScheduleFromFormLegacy3(){return window.PurpleFinancial.schedule({count:Number($('#financialInstallmentCount')?.value||1),fullValue:financialReadMoney('financialFullValue'),punctualValue:financialReadMoney('financialPunctualValue'),firstDueDate:$('#financialDueDate')?.value||todayISO(),billingType:$('#financialPaymentMethod')?.value||'PIX',chargeType:$('#financialCategory')?.value||'MENSALIDADE'}).map(row=>({...row,description:financialDescriptionFromParts(row.chargeType,row.dueDate,row.installmentNumber,row.installmentTotal)}))}
function refreshFinancialPreview(){const target=$('#financialChargePreview');if(!target)return;const schedule=financialScheduleFromForm(),first=schedule[0],count=schedule.length,full=count*Number(first.fullValue||0),punctual=count*Number(first.punctualValue||0),saving=full-punctual;const competence=$('#financialCompetence'),due=$('#financialDueDate')?.value||todayISO();if(competence)competence.value=financialCompetenceFromDue(due);target.innerHTML=`<div class="financial-preview-grid compact"><span><small>Parcelas</small><b>${count}</b></span><span><small>Integral/parcela</small><b>${fmtMoney(first.fullValue)}</b></span><span><small>Até vencimento</small><b>${fmtMoney(first.punctualValue)}</b></span><span><small>Economia total</small><b>${fmtMoney(saving)}</b></span></div><p class="financial-rule-note">Até o vencimento vale o valor com pontualidade. Depois do vencimento, a parcela perde o desconto e volta ao valor integral.</p><button type="button" class="btn ghost small" aria-expanded="${State.financialScheduleOpen?'true':'false'}" onclick="App.toggleFinancialSchedule()">${State.financialScheduleOpen?'Ocultar':'Ver'} prévia das parcelas</button>${State.financialScheduleOpen?`<div class="financial-schedule">${schedule.map(row=>`<div class="financial-schedule-row"><b>${row.installmentNumber}/${row.installmentTotal}</b><span><strong>${escapeHTML(row.description)}</strong><small>${financialCompetenceHuman(row.competence)} · ${fmtDate(row.dueDate)}</small></span><span><small>Pontualidade</small><strong>${fmtMoney(row.punctualValue)}</strong></span></div>`).join('')}</div>`:''}`}
function updateFinancialStudentDefaults(){const student=(State.db.students||[]).find(item=>item.id===($('#financialStudentId')?.value||$('#financialPinnedStudentId')?.value||''));if(!student)return;const method=$('#financialPaymentMethod'),full=$('#financialFullValue'),punctual=$('#financialPunctualValue'),due=$('#financialDueDate');if(method)method.value=studentFinancialDefaultMethod(student);if(full){full.dataset.cents=String(window.PurpleFinancial.cents(student.financeFullValue||student.financeMonthlyValue||0));full.value=window.PurpleFinancial.moneyFromCents(full.dataset.cents).replace(/^R\$\s?/,'').trim()}if(punctual){punctual.dataset.cents=String(window.PurpleFinancial.cents(student.financePunctualValue||student.financeMonthlyValue||0));punctual.value=window.PurpleFinancial.moneyFromCents(punctual.dataset.cents).replace(/^R\$\s?/,'').trim()}if(due&&!due.value)due.value=financialDueDateSuggestion(student);refreshFinancialPreview()}
function studentFinancialCanDelete(item={}){return financialStatusFor(item)!=='paid'}
function studentFinancialMenuActionsLegacy2(item={}){const status=financialStatusFor(item),paid=status==='paid',asaas=financialIsAsaas(item),link=financialPrimaryLink(item),actions=[['details','Detalhes']];if(!paid)actions.push(['edit','Editar parcela']);if(!paid&&!asaas)actions.push(['generate','Gerar cobrança Asaas']);if(link)actions.push(['openCharge','Ver cobrança'],['copyLink','Copiar link']);if(item.pixCopyPaste||item.pixQrCode)actions.push(['viewPix','PIX / QR Code'],['copyPix','Copiar PIX']);if(item.bankSlipUrl)actions.push(['openBoleto','Abrir boleto']);if(item.digitableLine)actions.push(['copyLine','Copiar linha digitável']);actions.push(['copyCode','Copiar código']);if(!paid&&!asaas)actions.push(['recordPayment','Registrar pagamento']);if(studentFinancialCanDelete(item))actions.push(['delete','Excluir parcela','danger']);if(paid)actions.push(['locked','Pagamento protegido']);return actions}
function closeStudentFinancialMenu(){document.querySelector('.student-financial-popover')?.remove();State.studentFinancialMenuOpenId='';document.querySelectorAll('[data-financial-menu-trigger][aria-expanded="true"]').forEach(button=>button.setAttribute('aria-expanded','false'))}
function positionStudentFinancialMenu(popover,button){const rect=button.getBoundingClientRect(),pad=10;popover.style.visibility='hidden';popover.style.display='grid';const width=Math.min(260,Math.max(220,popover.offsetWidth||240)),height=popover.offsetHeight||260;let left=Math.min(window.innerWidth-width-pad,Math.max(pad,rect.right-width)),top=rect.bottom+8;if(top+height>window.innerHeight-pad)top=Math.max(pad,rect.top-height-8);popover.style.left=`${left+window.scrollX}px`;popover.style.top=`${top+window.scrollY}px`;popover.style.visibility='visible'}
function openStudentFinancialMenu(button){const id=button?.dataset?.financialMenuId,item=(State.db.financialEntries||[]).find(row=>row.id===id);if(!button||!item)return;closeStudentFinancialMenu();const popover=document.createElement('div');popover.className='student-financial-popover';popover.dataset.financialMenuFor=id;popover.setAttribute('role','menu');popover.innerHTML=studentFinancialMenuActions(item).map(([action,label,tone])=>`<button type="button" role="menuitem" data-financial-menu-action="${action}" data-financial-id="${id}" class="${tone||''}" ${action==='locked'?'disabled':''}>${escapeHTML(label)}</button>`).join('');document.body.appendChild(popover);State.studentFinancialMenuOpenId=id;button.setAttribute('aria-expanded','true');positionStudentFinancialMenu(popover,button)}
function toggleStudentFinancialMenu(button){if(State.studentFinancialMenuOpenId===button?.dataset?.financialMenuId)return closeStudentFinancialMenu();openStudentFinancialMenu(button)}
function handleStudentFinancialMenuActionLegacy2(action,id){closeStudentFinancialMenu();if(action==='details')return openFinancialDetails(id);if(action==='edit')return editFinancialEntry('receivable',id);if(action==='generate')return generateAsaasChargeForEntry(id);if(action==='openCharge')return openFinancialAction('openCharge',id);if(action==='copyLink')return openFinancialAction('copyLink',id);if(action==='viewPix')return openFinancialAction('viewPix',id);if(action==='copyPix')return openFinancialAction('copyPix',id);if(action==='openBoleto')return openFinancialAction('openBoleto',id);if(action==='copyLine')return openFinancialAction('copyLine',id);if(action==='copyCode')return openFinancialAction('copyCode',id);if(action==='recordPayment')return openStudentFinancialPayment(id);if(action==='delete')return confirmArchiveHistoricalPayment(id)}
function bindStudentFinancialMenuDelegation(){if(window.__purpleStudentFinancialMenuBound)return;window.__purpleStudentFinancialMenuBound=true;document.addEventListener('click',event=>{const selector=event.target.closest?.('[data-financial-select-toggle]');if(selector){event.preventDefault();event.stopPropagation();if(selector.disabled)return;return toggleStudentFinancialSelection(selector.dataset.financialId,selector.getAttribute('aria-pressed')!=='true',selector.dataset.studentId||'')}const row=event.target.closest?.('[data-financial-row-selectable="true"]');if(row&&!event.target.closest?.('button,a,input,select,textarea,.table-actions,.student-financial-popover')){event.preventDefault();event.stopPropagation();const button=row.querySelector('[data-financial-select-toggle]');if(button&&!button.disabled)return toggleStudentFinancialSelection(button.dataset.financialId,button.getAttribute('aria-pressed')!=='true',button.dataset.studentId||'')}const trigger=event.target.closest?.('[data-financial-menu-trigger]');if(trigger){event.preventDefault();event.stopPropagation();return toggleStudentFinancialMenu(trigger)}const action=event.target.closest?.('[data-financial-menu-action]');if(action){event.preventDefault();event.stopPropagation();return handleStudentFinancialMenuAction(action.dataset.financialMenuAction,action.dataset.financialId)}if(!event.target.closest?.('.student-financial-popover'))closeStudentFinancialMenu()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeStudentFinancialMenu()});window.addEventListener('resize',()=>closeStudentFinancialMenu());window.addEventListener('scroll',()=>{const id=State.studentFinancialMenuOpenId;if(!id)return;const button=document.querySelector(`[data-financial-menu-trigger][data-financial-menu-id="${CSS.escape(id)}"]`),popover=document.querySelector('.student-financial-popover');if(button&&popover)positionStudentFinancialMenu(popover,button);else closeStudentFinancialMenu()},true)}
function studentFinancialQuickActions(item){if(!item)return '<span class="muted">Sem ação</span>';return `<button class="btn ghost small" data-financial-menu-action="details" data-financial-id="${escapeHTML(item.id)}">Detalhes</button><button class="btn ghost small student-financial-menu-button" type="button" data-financial-menu-trigger data-financial-menu-id="${escapeHTML(item.id)}" aria-haspopup="menu" aria-expanded="false" aria-label="Mais ações da parcela ${escapeHTML(item.description||'financeira')}">⋯</button>`}
function studentFinancialSelection(){if(!Array.isArray(State.studentFinancialSelectedIds))State.studentFinancialSelectedIds=[];return State.studentFinancialSelectedIds}
function studentFinancialSelectionSummary(s){const selected=new Set(studentFinancialSelection()),rows=studentFinancialTotals(s).rows.filter(row=>selected.has(row.id)),deletable=rows.filter(row=>studentFinancialCanDelete(row)),protectedRows=rows.filter(row=>!deletable.includes(row));return {rows,deletable,protectedRows,count:rows.length,deletableCount:deletable.length,protectedCount:protectedRows.length}}
function studentFinancialRefreshBulkBar(studentId){const student=(State.db.students||[]).find(item=>item.id===studentId),bar=$('#studentFinancialBulkBar');if(!student||!bar)return;const selectedIds=studentFinancialSelection(),summary=studentFinancialSelectionSummary(student),count=$('#studentFinancialBulkCount'),deleteButton=$('#studentFinancialBulkDelete');if(count)count.textContent=summary.count?`${summary.count} parcela(s) selecionada(s) · ${summary.deletableCount} pode(m) ser excluída(s)`: 'Nenhuma parcela selecionada';if(deleteButton)deleteButton.disabled=!summary.count;document.querySelectorAll('[data-financial-row-id]').forEach(row=>row.classList.toggle('selected',selectedIds.includes(row.dataset.financialRowId)));document.querySelectorAll('[data-financial-select-toggle]').forEach(button=>{const pressed=selectedIds.includes(button.dataset.financialId);button.setAttribute('aria-pressed',pressed?'true':'false');button.classList.toggle('checked',pressed)})}
function toggleStudentFinancialSelection(id,checked,studentId=''){const selection=new Set(studentFinancialSelection());checked?selection.add(id):selection.delete(id);State.studentFinancialSelectedIds=[...selection];studentFinancialRefreshBulkBar(studentId)}
function selectStudentFinancialRows(studentId,mode='open'){const student=(State.db.students||[]).find(item=>item.id===studentId);if(!student)return;const rows=studentFinancialTotals(student).rows;if(mode==='clear')State.studentFinancialSelectedIds=[];else State.studentFinancialSelectedIds=rows.filter(row=>studentFinancialCanDelete(row)).map(row=>row.id);renderPage()}
function setStudentFinancialHistoryTab(){State.studentFinancialSelectedIds=[];renderPage()}
function openStudentFinancialPayment(id){const item=financialEntries('all').find(x=>x.id===id);if(!item||financialIsAsaas(item)||financialStatusFor(item)==='paid')return toast('Pagamento manual disponível apenas para registros internos em aberto.');modal(`<div class="financial-charge-modal"><div class="modal-head"><div><span class="eyebrow">Registrar pagamento</span><h3>${escapeHTML(item.description||'Parcela')}</h3><p class="helper">Baixa manual local. Não gera PIX, boleto nem chamada Asaas.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div><input id="manualPaymentEntryId" type="hidden" value="${escapeHTML(id)}"/><div class="form-grid cols-2">${financialMoneyInput('manualPaymentAmount','Valor efetivamente pago',financialCurrentValue(item))}<div class="field"><label for="manualPaymentDate">Data do pagamento</label><input id="manualPaymentDate" type="date" value="${todayISO()}"/></div><div class="field"><label for="manualPaymentMethod">Forma</label><select id="manualPaymentMethod"><option>PIX</option><option>BOLETO</option><option>DINHEIRO</option><option>TRANSFERENCIA</option><option>CARTAO</option></select></div><div class="field"><label for="manualPaymentNote">Observação</label><input id="manualPaymentNote" placeholder="Opcional"/></div></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Voltar</button><button class="btn primary" onclick="App.saveStudentFinancialPayment()">Registrar pagamento</button></div></div>`,true)}
async function saveStudentFinancialPayment(){const id=$('#manualPaymentEntryId')?.value,item=financialEntries('all').find(x=>x.id===id);if(!item||financialIsAsaas(item))return toast('Pagamento manual indisponível para cobrança Asaas.');const before=cloneValue(item),paid=financialReadMoney('manualPaymentAmount');if(paid<0)return toast('Revise o valor pago.');Object.assign(item,{paidAmount:paid,paidDate:$('#manualPaymentDate')?.value||todayISO(),paymentMethod:$('#manualPaymentMethod')?.value||item.paymentMethod,notes:$('#manualPaymentNote')?.value.trim()||item.notes||'',status:'paid',updatedAt:new Date().toISOString()});try{await Storage.save(State.db);await logAudit('Registrou pagamento manual',`${item.person} · ${item.description} · ${fmtMoney(paid)}`);closeModal();renderPage();toast('Pagamento manual registrado.')}catch(error){Object.assign(item,before);toast(friendlyError(error,'registro de pagamento'))}}
function confirmArchiveHistoricalPayment(id){const item=(State.db.financialEntries||[]).find(x=>x.id===id);if(!item)return toast('Registro não encontrado.');if(!studentFinancialCanDelete(item))return toast('Parcelas pagas permanecem protegidas.');modal(`<div class="modal-head"><div><span class="eyebrow">Excluir parcela</span><h3>Excluir esta parcela de vez?</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="financial-confirm-card"><b>${escapeHTML(item.description||'Parcela financeira')}</b><span>${financialInstallmentLabel(item)} · ${fmtMoney(item.fullValue??item.amount)}</span><small>${financialIsAsaas(item)?'A cobrança vinculada será encerrada no Asaas e a parcela vai sumir da tela, sem ir para arquivo oculto.':'A parcela será removida definitivamente do Purple Gestão, sem arquivamento.'}</small></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Voltar</button><button class="btn danger" onclick="App.archiveHistoricalPayment('${id}')">Excluir definitivamente</button></div>`,true)}
async function archiveHistoricalPayment(id){const list=State.db.financialEntries||[],index=list.findIndex(x=>x.id===id),item=index>=0?list[index]:null;if(!item||!studentFinancialCanDelete(item))return toast('Esta parcela não pode ser excluída.');const button=$('.modal .btn.danger');if(button?.disabled)return;button&&(button.disabled=true,button.textContent='Excluindo...');try{if(financialIsAsaas(item)){const {data,error}=await Supabase.functions.invoke('asaas-manage-charge',{body:{action:'cancel',chargeId:item.supabaseId||item.id}});if(error||data?.error)throw new Error(data?.error||error?.message)}list.splice(index,1);await Storage.save(State.db);await logAudit('Excluiu parcela financeira',`${item.person} · ${item.description}`);State.studentFinancialSelectedIds=studentFinancialSelection().filter(selectedId=>selectedId!==id);closeModal();renderPage();toast('Parcela removida definitivamente.')}catch(error){toast(humanizeFinancialError(error));button&&(button.disabled=false,button.textContent='Excluir definitivamente')}}
function confirmArchiveSelectedFinancialRows(studentId){const student=(State.db.students||[]).find(item=>item.id===studentId);if(!student)return toast('Aluno não encontrado.');const summary=studentFinancialSelectionSummary(student);if(!summary.count)return toast('Selecione uma ou mais parcelas.');if(!summary.deletableCount)return toast('As parcelas selecionadas estão protegidas.');modal(`<div class="modal-head"><div><span class="eyebrow">Excluir em lote</span><h3>Excluir ${summary.deletableCount} parcela(s) selecionada(s)?</h3></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="financial-confirm-card"><b>${escapeHTML(student.name)}</b><span>${summary.deletable.map(row=>escapeHTML(row.description||'Parcela')).join('<br>')}</span><small>As parcelas selecionadas serão removidas definitivamente. ${summary.protectedCount?`${summary.protectedCount} parcela(s) paga(s) serão ignoradas.`:'Nenhuma parcela será arquivada.'}</small></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Voltar</button><button class="btn danger" onclick="App.archiveSelectedFinancialRows('${studentId}')">Excluir definitivamente</button></div>`,true)}
async function archiveSelectedFinancialRows(studentId){const student=(State.db.students||[]).find(item=>item.id===studentId);if(!student)return toast('Aluno não encontrado.');const summary=studentFinancialSelectionSummary(student);if(!summary.deletableCount)return toast('Nenhuma parcela selecionada pode ser excluída.');const ids=new Set(summary.deletable.map(row=>row.id)),asaasRows=summary.deletable.filter(row=>financialIsAsaas(row));try{for(const row of asaasRows){const {data,error}=await Supabase.functions.invoke('asaas-manage-charge',{body:{action:'cancel',chargeId:row.supabaseId||row.id}});if(error||data?.error)throw new Error(data?.error||error?.message)}State.db.financialEntries=(State.db.financialEntries||[]).filter(item=>!ids.has(item.id));await Storage.save(State.db);await logAudit('Excluiu parcelas financeiras em lote',`${student.name} · ${summary.deletableCount} parcela(s)`);State.studentFinancialSelectedIds=studentFinancialSelection().filter(id=>!ids.has(id));closeModal();renderPage();toast(`${summary.deletableCount} parcela(s) removida(s) definitivamente.${summary.protectedCount?` ${summary.protectedCount} paga(s) foram preservadas.`:''}`)}catch(error){toast(humanizeFinancialError(error))}}
function confirmCancelFinancialCharge(id){return confirmArchiveHistoricalPayment(id)}
async function cancelFinancialCharge(id){return archiveHistoricalPayment(id)}

/* Fase 2 — Asaas: cobrança única com PIX + boleto, carnê digital e baixa segura. */
STUDENT_PAYMENT_METHODS.splice(0,STUDENT_PAYMENT_METHODS.length,'UNDEFINED','PIX','BOLETO');
function studentFinancialDefaultMethod(student={}){const method=String(student?.financeDefaultMethod||'UNDEFINED').toUpperCase();return ['UNDEFINED','PIX','BOLETO'].includes(method)?method:'UNDEFINED'}
function financialPaymentMethodLabel(value=''){return {UNDEFINED:'PIX + Boleto',PIX:'PIX',BOLETO:'Boleto'}[String(value||'').toUpperCase()]||String(value||'—')}
function financialIsAsaas(item={}){const origin=String(item.origin||item.provider||item.account||'').toUpperCase();return origin.includes('ASAAS')||Boolean(item.externalChargeId||item.asaasPaymentId||item.asaasChargeId||item.externalReference||item.invoiceUrl||item.bankSlipUrl||item.pixCopyPaste||item.pixQrCode||item.digitableLine)}
function financialPrimaryLink(item={}){return item.invoiceUrl||item.bankSlipUrl||item.paymentUrl||item.checkoutUrl||item.link||item.url||''}
function financialExternalCode(item={}){return item.asaasPaymentId||item.externalChargeId||item.asaasChargeId||item.externalReference||item.supabaseId||item.id||''}
function financialScheduleFromForm(){return window.PurpleFinancial.schedule({count:Number($('#financialInstallmentCount')?.value||1),fullValue:financialReadMoney('financialFullValue'),punctualValue:financialReadMoney('financialPunctualValue'),firstDueDate:$('#financialDueDate')?.value||todayISO(),billingType:$('#financialPaymentMethod')?.value||'UNDEFINED',chargeType:$('#financialCategory')?.value||'MENSALIDADE'}).map(row=>({...row,billingType:['UNDEFINED','PIX','BOLETO'].includes(String(row.billingType||'').toUpperCase())?String(row.billingType).toUpperCase():'UNDEFINED',description:financialDescriptionFromParts(row.chargeType,row.dueDate,row.installmentNumber,row.installmentTotal)}))}
function financialEntryFromCharge(charge,student){return {id:charge.id,supabaseId:charge.supabaseId||charge.id,type:'receivable',studentId:student.id,person:student.name,student:student.name,description:charge.description,category:chargeTypeLabel(charge.chargeType),chargeType:charge.chargeType,subaccount:chargeTypeLabel(charge.chargeType),competence:charge.competence||String(charge.dueDate||'').slice(0,7),dueDate:charge.dueDate,amount:Number(charge.fullValue??charge.value??0),fullValue:Number(charge.fullValue??charge.value??0),punctualValue:Number(charge.punctualValue??charge.value??0),discountValue:Number(charge.discountValue||0),discountDueDate:charge.dueDate,installmentNumber:charge.installmentNumber||1,installmentTotal:charge.installmentTotal||1,installmentGroupId:charge.installmentGroupId||'',origin:'ASAAS',provider:'ASAAS',paidAmount:0,paidDate:'',paymentMethod:charge.billingType||'UNDEFINED',status:String(charge.status||'PENDING').toLowerCase()==='paid'?'paid':String(charge.syncStatus||'').toUpperCase()==='SYNC_ERROR'?'sync_error':'pending',syncStatus:charge.syncStatus||'',syncError:charge.syncError||'',invoiceUrl:charge.invoiceUrl||'',bankSlipUrl:charge.bankSlipUrl||'',digitableLine:charge.digitableLine||'',boletoBarCode:charge.boletoBarCode||'',boletoNossoNumero:charge.boletoNossoNumero||'',pixCopyPaste:charge.pixCopyPaste||'',pixQrCode:charge.pixQrCode||'',pixQrExpiresAt:charge.pixQrExpiresAt||'',externalChargeId:charge.externalChargeId||charge.asaasPaymentId||'',asaasPaymentId:charge.asaasPaymentId||charge.externalChargeId||'',externalReference:charge.externalReference||'',account:'ASAAS',active:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}}
function studentFinancialMenuActions(item={}){const status=financialStatusFor(item),paid=status==='paid',asaas=financialIsAsaas(item),link=financialPrimaryLink(item),actions=[['details','Detalhes']];if(!paid)actions.push(['edit','Editar parcela']);if(!paid&&!asaas)actions.push(['generate','Gerar cobrança Asaas']);if(link)actions.push(['openCharge','Ver cobrança'],['copyLink','Copiar link']);if(item.pixCopyPaste||item.pixQrCode)actions.push(['viewPix','PIX / QR Code'],['copyPix','Copiar PIX']);if(item.bankSlipUrl)actions.push(['openBoleto','Abrir boleto']);if(item.digitableLine)actions.push(['copyLine','Copiar linha digitável']);actions.push(['copyCode','Copiar código']);if(!paid&&!asaas)actions.push(['recordPayment','Registrar pagamento']);if(studentFinancialCanDelete(item))actions.push(['delete','Excluir parcela','danger']);if(paid)actions.push(['locked','Pagamento protegido']);return actions}
function handleStudentFinancialMenuAction(action,id){closeStudentFinancialMenu();if(action==='details')return openFinancialDetails(id);if(action==='edit')return editFinancialEntry('receivable',id);if(action==='generate')return generateAsaasChargeForEntry(id);if(action==='openCharge')return openFinancialAction('openCharge',id);if(action==='copyLink')return openFinancialAction('copyLink',id);if(action==='viewPix')return openFinancialAction('viewPix',id);if(action==='copyPix')return openFinancialAction('copyPix',id);if(action==='openBoleto')return openFinancialAction('openBoleto',id);if(action==='copyLine')return openFinancialAction('copyLine',id);if(action==='copyCode')return openFinancialAction('copyCode',id);if(action==='recordPayment')return openStudentFinancialPayment(id);if(action==='delete')return confirmArchiveHistoricalPayment(id)}
function openFinancialChargeResultModal(charge,student){const linkValue=financialPrimaryLink(charge),qrImage=financialQrImageSrc(charge?.pixQrCode||''),studentName=student?.name||charge?.studentName||'Aluno';modal(`<div class="modal-head"><div><span class="eyebrow">Cobrança criada</span><h3>PIX + boleto prontos para envio</h3><p class="helper" style="margin-top:6px">Uma única cobrança Asaas foi registrada para ${escapeHTML(studentName)}. Use o link, PIX ou boleto conforme a necessidade do responsável.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div><div class="student-financial-result pix"><div class="student-financial-result-main"><div class="student-financial-result-kpis"><span><b>Valor integral</b>${fmtMoney(charge?.fullValue||charge?.amount||charge?.value||0)}</span><span><b>Vencimento</b>${fmtDate(charge?.dueDate)}</span><span><b>Forma</b>${financialPaymentMethodLabel(charge?.billingType||charge?.paymentMethod)}</span></div>${qrImage?`<div class="student-financial-qr"><img src="${qrImage}" alt="QR Code PIX da cobrança"/></div>`:''}${charge?.pixCopyPaste?`<div class="field"><label>PIX copia e cola</label><textarea readonly>${escapeHTML(charge.pixCopyPaste)}</textarea></div>`:''}${charge?.digitableLine?`<div class="field"><label>Linha digitável do boleto</label><textarea readonly>${escapeHTML(charge.digitableLine)}</textarea></div>`:''}</div><aside class="student-financial-result-side"><div class="student-financial-result-note"><b>Código Asaas</b><span>${escapeHTML(financialExternalCode(charge)||'Aguardando sincronização')}</span></div><div class="section-actions" style="justify-content:flex-start">${charge?.pixCopyPaste?`<button class="btn primary" onclick="App.openFinancialAction('copyPix','${charge.id}')">Copiar PIX</button>`:''}${charge?.digitableLine?`<button class="btn ghost" onclick="App.openFinancialAction('copyLine','${charge.id}')">Copiar linha</button>`:''}${linkValue?`<button class="btn ghost" onclick="App.openFinancialAction('copyLink','${charge.id}')">Copiar link</button><button class="btn ghost" onclick="App.openFinancialAction('openCharge','${charge.id}')">Abrir cobrança</button>`:''}</div></aside></div>`,true)}
function openFinancialDetails(id){const item=(State.db.financialEntries||[]).find(x=>x.id===id);if(!item)return toast('Cobrança não encontrada.');const paid=financialStatusFor(item)==='paid',link=financialPrimaryLink(item),qrImage=financialQrImageSrc(item.pixQrCode||'');modal(`<div class="modal-head"><div><span class="eyebrow">${financialOriginLabel(item)}</span><h3>${escapeHTML(item.description||'Cobrança')}</h3><p class="helper">${financialInstallmentLabel(item)} · ${escapeHTML(item.person||item.student||'')}</p></div><button class="modal-close" aria-label="Fechar" onclick="App.closeModal()">×</button></div><div class="student-financial-detail-grid"><div class="student-financial-detail-card"><span>Valor integral</span><strong>${fmtMoney(item.fullValue??item.amount)}</strong></div><div class="student-financial-detail-card"><span>${paid?'Valor pago':'Valor devido agora'}</span><strong>${fmtMoney(paid?(item.paidAmount??item.amount):financialCurrentValue(item))}</strong></div><div class="student-financial-detail-card"><span>Vencimento</span><strong>${fmtDate(item.dueDate)}</strong></div><div class="student-financial-detail-card"><span>Status</span><strong>${financialStatusLabel(financialStatusFor(item))}</strong></div><div class="student-financial-detail-card"><span>Forma</span><strong>${escapeHTML(financialPaymentMethodLabel(item.paymentMethod))}</strong></div><div class="student-financial-detail-card"><span>Código Asaas</span><strong>${escapeHTML(financialExternalCode(item)||'Sem cobrança externa')}</strong></div></div>${qrImage?`<div class="student-financial-qr"><img src="${qrImage}" alt="QR Code PIX da cobrança"/></div>`:''}<div class="student-financial-result-side"><div class="section-actions" style="justify-content:flex-start">${item.pixCopyPaste?`<button class="btn primary" onclick="App.openFinancialAction('copyPix','${item.id}')">Copiar PIX</button>`:''}${item.digitableLine?`<button class="btn ghost" onclick="App.openFinancialAction('copyLine','${item.id}')">Copiar linha digitável</button>`:''}${link?`<button class="btn ghost" onclick="App.openFinancialAction('copyLink','${item.id}')">Copiar link</button><button class="btn ghost" onclick="App.openFinancialAction('openCharge','${item.id}')">Abrir cobrança</button>`:''}<button class="btn ghost" onclick="App.openFinancialAction('copyCode','${item.id}')">Copiar código</button></div></div>${paid?'<p class="financial-rule-note">Pagamento confirmado: valores, data e identificadores ficam congelados como fato histórico.</p>':item.syncError?`<p class="financial-rule-note danger">Erro de sincronização: ${escapeHTML(item.syncError)}</p>`:''}`,true)}
function openFinancialAction(action,id){const item=financialEntries('all').find(entry=>entry.id===id)||(State.db.financialEntries||[]).find(entry=>entry.id===id);if(!item)return toast('Cobrança não encontrada.');const link=financialPrimaryLink(item);if(action==='copyPix')return financialClipboardCopy(item.pixCopyPaste,'PIX copiado.');if(action==='copyLine')return financialClipboardCopy(item.digitableLine,'Linha digitável copiada.');if(action==='copyCode')return financialClipboardCopy(financialExternalCode(item),'Código da cobrança copiado.');if(action==='copyLink')return financialClipboardCopy(link,'Link de pagamento copiado.');if(action==='openCharge'&&link)return window.open(link,'_blank','noopener');if(action==='openBoleto'&&(item.bankSlipUrl||link))return window.open(item.bankSlipUrl||link,'_blank','noopener');if(action==='viewPix'){const qrImage=financialQrImageSrc(item.pixQrCode||'');return modal(`<div class="modal-head"><div><span class="eyebrow">PIX</span><h3>${escapeHTML(item.person||'Cobrança')}</h3><p class="helper" style="margin-top:6px">Compartilhe o QR Code, o copia e cola ou o link de pagamento.</p></div><button class="modal-close" onclick="App.closeModal()">×</button></div>${qrImage?`<div class="student-financial-qr"><img src="${qrImage}" alt="QR Code PIX da cobrança"/></div>`:''}<div class="field"><label>PIX copia e cola</label><textarea readonly>${escapeHTML(item.pixCopyPaste||'')}</textarea></div><div class="section-actions" style="justify-content:flex-start"><button class="btn primary" onclick="App.openFinancialAction('copyPix','${item.id}')">Copiar PIX</button>${link?`<button class="btn ghost" onclick="App.openFinancialAction('copyLink','${item.id}')">Copiar link</button><button class="btn ghost" onclick="App.openFinancialAction('openCharge','${item.id}')">Abrir cobrança</button>`:''}</div>`,true)}toast('Ação indisponível para esta cobrança.')}
function editFinancialEntryLegacy7(type,id='',forcedStudentId=''){if(!can(id?'financial.transactions.edit':'financial.transactions.create'))return toast('Operação não autorizada.');const item=id?financialEntries('all').find(x=>x.id===id):null;if(item&&financialStatusFor(item)==='paid')return openFinancialDetails(id);const student=item?(State.db.students||[]).find(x=>x.id===item.studentId):(State.db.students||[]).find(x=>x.id===forcedStudentId),pinned=Boolean(student),full=item?.fullValue??item?.amount??student?.financeFullValue??student?.financeMonthlyValue??0,punctual=item?.punctualValue??student?.financePunctualValue??student?.financeMonthlyValue??full,due=item?.dueDate||financialDueDateSuggestion(student||{}),category=normalizeChargeTypeValue(item?.chargeType||item?.category||'MENSALIDADE'),method=String(item?.paymentMethod||studentFinancialDefaultMethod(student||{})).toUpperCase();State.financialScheduleOpen=false;modal(`<div class="financial-charge-modal"><div class="modal-head"><div><span class="eyebrow">Financeiro individual</span><h3>${item?'Editar parcela':'Nova cobrança'}</h3><p class="helper">${item?'Altere somente cobranças pendentes/vencidas.':'Por padrão será criada uma cobrança única Asaas com PIX + boleto.'}</p></div><button class="modal-close" aria-label="Fechar" onclick="App.closeModal()">×</button></div>${pinned?`<div class="student-financial-student-chip"><b>${escapeHTML(student.name)}</b><span>${escapeHTML(financialPaymentMethodLabel(studentFinancialDefaultMethod(student)))} · vencimento padrão ${student.financeDueDay?`dia ${student.financeDueDay}`:'não definido'}</span><input type="hidden" id="financialPinnedStudentId" value="${escapeHTML(student.id)}"/></div>`:`<div class="field"><label for="financialStudentId">Aluno</label><select id="financialStudentId" onchange="App.updateFinancialStudentDefaults()"><option value="">Selecione</option>${financialStudentOptions()}</select></div>`}<div class="form-grid cols-2"><div class="field"><label for="financialCategory">Tipo de cobrança</label><select id="financialCategory" onchange="App.refreshFinancialPreview()">${FINANCIAL_CHARGE_TYPES.map(([value,label])=>`<option value="${value}" ${value===category?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="financialPaymentMethod">Forma de pagamento</label><select id="financialPaymentMethod" onchange="App.refreshFinancialPreview()"><option value="UNDEFINED" ${method==='UNDEFINED'?'selected':''}>PIX + Boleto</option><option value="PIX" ${method==='PIX'?'selected':''}>Somente PIX</option><option value="BOLETO" ${method==='BOLETO'?'selected':''}>Somente boleto</option></select></div>${financialMoneyInput('financialFullValue','Valor integral',full)}${financialMoneyInput('financialPunctualValue','Valor com pontualidade/desconto',punctual)}<div class="field"><label for="financialInstallmentNumber">Número da parcela</label><input id="financialInstallmentNumber" type="number" min="1" max="24" value="${item?.installmentNumber||1}" ${item?'disabled':''}/></div><div class="field"><label for="financialInstallmentCount">Total de parcelas</label><input id="financialInstallmentCount" type="number" min="1" max="24" value="${item?.installmentTotal||1}" onchange="App.refreshFinancialPreview()" ${item?'disabled':''}/></div><div class="field"><label for="financialDueDate">${item?'Vencimento':'Primeiro vencimento'}</label><input id="financialDueDate" type="date" value="${due}" onchange="App.refreshFinancialPreview()"/></div><div class="field"><label for="financialCompetence">Competência automática</label><input id="financialCompetence" value="${financialCompetenceFromDue(due)}" readonly/></div></div><details class="advanced-row"><summary>Descrição/observação avançada</summary><div class="field"><label for="financialManualDescription">Descrição automática editável</label><input id="financialManualDescription" value="${escapeHTML(item?.description||financialDescriptionFromParts(category,due,item?.installmentNumber||1,item?.installmentTotal||1))}"/></div><div class="field"><label for="financialNotes">Observação</label><textarea id="financialNotes">${escapeHTML(item?.notes||'')}</textarea></div></details><div id="financialChargePreview" class="financial-charge-preview" aria-live="polite"></div><div class="section-actions"><button class="btn ghost" onclick="App.closeModal()">Voltar</button><button class="btn primary" id="financialSubmitButton" onclick="App.saveFinancialEntry('receivable','${item?.id||''}')">${item?'Salvar parcela':'Gerar cobrança Asaas'}</button></div></div>`,true);requestAnimationFrame(()=>{refreshFinancialPreview();(pinned?$('#financialCategory'):$('#financialStudentId'))?.focus()})}
function financialStableIdempotencyKey(studentId,row){return ['purple',studentId,row.chargeType,row.dueDate,row.fullValue,row.punctualValue,row.installmentNumber,row.installmentTotal].map(value=>String(value||'').replace(/[^A-Za-z0-9_.:-]/g,'')).join(':')}
