    student.followUpEntries.unshift({id:uid('fup-twr'),at:new Date().toISOString(),contactDate:todayISO(),contactTime:new Date().toTimeString().slice(0,5),employee:State.user?.name||'Purple',type:'TWR',result:status,subject:detail,done:true});
